-- La jointure sur `exercises.slug` saute EN SILENCE ce qu'elle ne trouve pas :
-- le bloc final compte les lignes posées et lève si le compte ne tombe pas juste.
insert into public.program_exercises
  (program_day_id, exercise_id, position, target_sets,
   target_reps_min, target_reps_max, target_rir, rest_seconds, note)
select d.id, e.id, v.position, v.target_sets,
       v.target_reps_min, v.target_reps_max, v.target_rir, v.rest_seconds, v.note
  from (values
    ('levers-comptes', 1, 'belt-squat', 1, 5, 4, 4, 3, 240, 'Vingt levers, et vous vous arrêtez à la cinquième série même si la charge monte encore vite. Le compte est la limite, pas la fatigue.'),
    ('levers-comptes', 1, 'floor-press', 2, 5, 4, 4, 3, 210, 'Les bras s''arrêtent au sol : la descente ne va jamais plus loin que ce que l''épaule tient confortablement.'),
    ('levers-comptes', 1, 'leg-curl-allonge', 3, 4, 8, 10, 3, 120, 'L''arrière de la cuisse ne reçoit presque rien du squat : c''est ici qu''il travaille. Le bassin reste posé, on ne décolle pas les hanches pour finir la série.'),
    ('levers-comptes', 1, 'elevation-laterale', 4, 4, 12, 15, 3, 90, 'Les bras montent à hauteur d''épaule et pas plus haut, sans balancer le buste.'),
    ('levers-comptes', 1, 'face-pull', 5, 4, 12, 15, 3, 90, 'Charge légère, volontairement. Cet exercice est là pour l''arrière de l''épaule, pas pour un record.'),
    ('levers-comptes', 1, 'dead-bug', 6, 4, 10, 12, 3, 90, 'Le bas du dos reste plaqué au sol du début à la fin. S''il décolle, réduisez l''amplitude.'),
    ('levers-comptes', 2, 'presse-a-cuisses', 1, 5, 4, 4, 3, 240, 'Vingt levers ici aussi. Les genoux ne partent jamais chercher la poitrine : arrêtez la descente là où le bas du dos reste plaqué.'),
    ('levers-comptes', 2, 'traction-assistee', 2, 5, 4, 4, 3, 210, 'Réglez l''assistance pour que les cinq séries se ressemblent. Une série arrachée en fin d''exercice ne compte pas comme les autres.'),
    ('levers-comptes', 2, 'hip-thrust', 3, 4, 8, 10, 3, 150, 'Le bassin monte jusqu''à l''alignement, pas au-delà. Chercher plus haut se paie au bas du dos.'),
    ('levers-comptes', 2, 'leg-curl-assis', 4, 4, 8, 10, 3, 120, 'Deuxième passage de la semaine sur l''arrière de la cuisse. Le retour se contrôle, il ne se laisse pas tomber.'),
    ('levers-comptes', 2, 'oiseau-machine', 5, 4, 12, 15, 3, 90, 'Buste posé, coudes légèrement fléchis. On écarte les bras, on ne tire pas avec le haut du dos.'),
    ('levers-comptes', 2, 'pallof-press', 6, 3, 10, 12, 3, 90, 'L''exercice consiste à ne pas tourner. Si le buste pivote, la charge est trop lourde.'),
    ('levers-comptes', 3, 'rowing-machine-buste-soutenu', 1, 5, 4, 4, 3, 210, 'Vingt levers. Buste posé : c''est le dos qui tire, pas les jambes ni l''élan.'),
    ('levers-comptes', 3, 'developpe-machine-convergent', 2, 5, 4, 4, 3, 210, 'Les coudes restent sous les mains et ne s''ouvrent pas à l''horizontale en fin de descente.'),
    ('levers-comptes', 3, 'presse-pieds-hauts', 3, 4, 8, 10, 3, 150, 'Pieds hauts sur la plateforme : le travail se déplace vers les fessiers et l''arrière de la cuisse. Même consigne qu''à la presse, la descente s''arrête avant que le bas du dos s''arrondisse.'),
    ('levers-comptes', 3, 'elevation-laterale-machine', 4, 4, 12, 15, 3, 90, 'Même mouvement qu''en séance A, sur machine. Réglez le siège pour que l''axe soit à hauteur d''épaule.'),
    ('levers-comptes', 3, 'pull-apart-elastique', 5, 4, 12, 15, 3, 90, 'Bras tendus, élastique léger. Si les coudes se plient pour finir la série, l''élastique est trop dur.'),
    ('levers-comptes', 3, 'mcgill-curl-up', 6, 3, 8, 10, 3, 90, 'Une main sous le bas du dos, un genou fléchi : seules la tête et les épaules décollent, le bas du dos ne bouge pas.'),
    ('charge-ondulee', 1, 'hip-hinge-baton', 1, 2, 12, 12, 3, 90, 'Toujours le même dosage, les trois jours. Le bâton doit rester en contact avec la tête, le haut du dos et le sacrum pendant tout le mouvement.'),
    ('charge-ondulee', 1, 'squat-halteres', 2, 4, 5, 5, 2, 210, 'Jour lourd : deux répétitions de garde, jamais moins. Deux de garde, cela veut dire que vous pourriez encore en faire deux propres à la fin de la série.'),
    ('charge-ondulee', 1, 'hip-thrust', 3, 3, 5, 5, 2, 180, 'Trois séries, une de moins que le squat et le développé, et c''est le même chiffre les trois jours. Les fessiers travaillent déjà au squat : ce nombre tient le total de la semaine, il n''est pas à augmenter.'),
    ('charge-ondulee', 1, 'developpe-couche-halteres', 4, 4, 5, 5, 2, 210, 'Les haltères descendent jusqu''où l''épaule reste confortable, pas plus bas. Ce repère est personnel et ne change pas avec la charge.'),
    ('charge-ondulee', 1, 'rowing-haltere', 5, 4, 5, 5, 2, 180, null),
    ('charge-ondulee', 1, 'leg-curl-allonge', 6, 3, 10, 10, 3, 120, 'Même dosage les trois jours : il n''ondule pas. C''est le seul travail chargé des ischio-jambiers du programme, il ne se saute pas.'),
    ('charge-ondulee', 1, 'elevation-laterale', 7, 3, 12, 12, 3, 90, 'Charge légère, hors de la vague. Trois de garde veut dire que la dernière série se termine sans à-coup et sans élan du buste.'),
    ('charge-ondulee', 1, 'dead-bug', 8, 3, 12, 12, 3, 90, 'Comme la charnière au bâton : hors de la vague, il ne participe pas au dosage du jour.'),
    ('charge-ondulee', 2, 'hip-hinge-baton', 1, 2, 12, 12, 3, 90, null),
    ('charge-ondulee', 2, 'squat-halteres', 2, 3, 15, 15, 3, 120, 'Charge nettement plus légère qu''au jour lourd : celle qui vous laisse encore trois répétitions propres à la quinzième. Si vous ne les avez pas, elle est trop lourde et vous la baissez.'),
    ('charge-ondulee', 2, 'hip-thrust', 3, 3, 15, 15, 3, 120, null),
    ('charge-ondulee', 2, 'developpe-couche-halteres', 4, 3, 15, 15, 3, 120, null),
    ('charge-ondulee', 2, 'rowing-haltere', 5, 3, 15, 15, 3, 120, null),
    ('charge-ondulee', 2, 'leg-curl-allonge', 6, 3, 10, 10, 3, 120, null),
    ('charge-ondulee', 2, 'elevation-laterale', 7, 5, 12, 12, 3, 90, 'Le jour léger porte ses séries supplémentaires ici, sur les exercices légers, et jamais sur les mouvements chargés.'),
    ('charge-ondulee', 2, 'dead-bug', 8, 5, 12, 12, 3, 90, 'Ce jour est léger, pas court. Ce qui baisse, ce sont les séries et la charge des mouvements chargés — pas le repos, qui reste celui qui est écrit.'),
    ('charge-ondulee', 3, 'hip-hinge-baton', 1, 2, 12, 12, 3, 90, null),
    ('charge-ondulee', 3, 'squat-halteres', 2, 3, 8, 8, 3, 150, 'Charge entre celle du jour lourd et celle du jour léger. Elle se déduit des deux autres, elle ne se choisit pas au ressenti.'),
    ('charge-ondulee', 3, 'hip-thrust', 3, 3, 8, 8, 3, 150, null),
    ('charge-ondulee', 3, 'developpe-couche-halteres', 4, 4, 8, 8, 3, 150, null),
    ('charge-ondulee', 3, 'rowing-haltere', 5, 4, 8, 8, 3, 150, null),
    ('charge-ondulee', 3, 'leg-curl-allonge', 6, 3, 10, 10, 3, 120, null),
    ('charge-ondulee', 3, 'elevation-laterale', 7, 4, 12, 12, 3, 90, null),
    ('charge-ondulee', 3, 'dead-bug', 8, 4, 12, 12, 3, 90, null),
    ('double-passage', 1, 'belt-squat', 1, 4, 5, 5, 3, 240, 'Premier passage. La charge tire sur les hanches par une ceinture, pas sur les épaules : on peut charger sans que le dos ait à tenir la position. Trois répétitions de garde veut dire que la quatrième série se termine comme la première ; si elle ralentit, la charge était trop lourde pour aujourd''hui.'),
    ('double-passage', 1, 'squat-gobelet', 2, 3, 10, 12, 3, 150, 'Second passage, le même mouvement en plus léger et déjà fatigué. La charge est bornée par ce que les bras tiennent devant eux : le passage léger ne peut pas devenir lourd. C''est ici que la technique se corrige.'),
    ('double-passage', 1, 'developpe-machine-convergent', 3, 3, 8, 10, 3, 150, 'Dose réduite du schéma de poussée : présent, pas chargé.'),
    ('double-passage', 1, 'rowing-machine-buste-soutenu', 4, 4, 10, 12, 3, 120, 'Dose réduite du schéma de tirage. Buste soutenu : le tronc n''a pas à retenir la charge une fois de plus dans la séance.'),
    ('double-passage', 1, 'leg-curl-assis', 5, 4, 10, 12, 3, 120, null),
    ('double-passage', 1, 'elevation-laterale', 6, 3, 12, 15, 2, 90, null),
    ('double-passage', 1, 'face-pull', 7, 4, 12, 15, 2, 90, 'Léger et lent. Il compense les poussées de la semaine, il n''est pas là pour ajouter de la charge.'),
    ('double-passage', 1, 'pallof-press', 8, 3, 10, 12, 3, 90, 'Le tronc revient à chaque séance de la semaine et n''est jamais mené à l''échec : c''est la position tenue qui compte, pas la charge. Dix à douze répétitions de chaque côté.'),
    ('double-passage', 2, 'hip-thrust', 1, 4, 5, 5, 3, 240, 'Premier passage. Même extension de hanche qu''un soulevé de terre, mais le dos est posé sur le banc et il n''y a pas de buste fléchi à retenir sous la charge.'),
    ('double-passage', 2, 'hip-thrust-une-jambe', 2, 3, 10, 12, 3, 120, 'Second passage, une jambe et sans charge ajoutée : le plafond, c''est votre poids de corps. Dix à douze répétitions par jambe.'),
    ('double-passage', 2, 'tirage-vertical-prise-neutre', 3, 4, 8, 10, 3, 150, 'Dose réduite du schéma de tirage. Prise neutre, paumes face à face.'),
    ('double-passage', 2, 'developpe-machine-pectoraux', 4, 3, 10, 12, 3, 120, 'Dose réduite du schéma de poussée.'),
    ('double-passage', 2, 'presse-a-cuisses', 5, 3, 8, 10, 3, 150, 'Dose réduite du schéma de squat : la fréquence de Sheiko, sans son volume.'),
    ('double-passage', 2, 'curl-nordique-assiste', 6, 3, 6, 8, 3, 120, 'Descente lente et contrôlée. Réduisez l''amplitude plutôt que de laisser le bassin partir.'),
    ('double-passage', 2, 'oiseau', 7, 4, 12, 15, 2, 90, null),
    ('double-passage', 2, 'mcgill-curl-up', 8, 3, 10, 12, 3, 90, null),
    ('double-passage', 3, 'floor-press', 1, 4, 5, 5, 3, 210, 'Premier passage. Le sol arrête la descente : l''épaule ne va pas chercher son amplitude la plus large sous la charge la plus lourde de la séance. Aucune série ne se termine à l''échec, gardez trois répétitions y compris sur la dernière.'),
    ('double-passage', 3, 'developpe-incline-machine', 2, 3, 10, 12, 3, 150, 'Second passage. Sur machine, la trajectoire est tenue pour vous — ce qui compte ici est de refaire le geste fatigué, pas de charger.'),
    ('double-passage', 3, 'traction-assistee', 3, 4, 8, 10, 3, 150, 'Dose réduite du schéma de tirage. Réglez l''assistance pour finir les huit à dix répétitions propres, pas pour les arracher.'),
    ('double-passage', 3, 'fente-arriere', 4, 3, 10, 12, 3, 120, 'Fente arrière et non avant : le pied qui recule demande moins au genou avant. Dix à douze répétitions par jambe.'),
    ('double-passage', 3, 'leg-curl-allonge', 5, 3, 10, 12, 3, 120, null),
    ('double-passage', 3, 'elevation-laterale-poulie', 6, 3, 12, 15, 2, 90, null),
    ('double-passage', 3, 'tirage-corde-nuque', 7, 4, 12, 15, 2, 90, null),
    ('double-passage', 3, 'dead-bug', 8, 4, 10, 12, 3, 90, 'Lent, sans laisser le bas du dos se creuser. Le tronc finit la semaine sur du contrôle, pas sur de la charge. Dix à douze répétitions par côté.'),
    ('chaine-posterieure-progressive', 1, 'hip-hinge-baton', 1, 2, 6, 8, 4, 90, 'Trois points de contact avec le bâton : sacrum, milieu du dos, tête. Le mouvement part des hanches, jamais du bas du dos.'),
    ('chaine-posterieure-progressive', 1, 'curl-nordique-assiste', 2, 3, 5, 6, 3, 180, 'Descente lente, remontée aidée par les bras si besoin. La série s''arrête dès que la descente cesse d''être freinée. Le repos est long parce que les répétitions sont peu nombreuses : reprenez reposé, pas essoufflé.'),
    ('chaine-posterieure-progressive', 1, 'pont-fessier-une-jambe', 3, 3, 6, 8, 3, 90, 'Bassin de niveau. Si un côté s''affaisse, revenez au pont sur deux appuis pour cette série.'),
    ('chaine-posterieure-progressive', 1, 'presse-pieds-hauts', 4, 4, 8, 10, 3, 120, 'Pieds hauts et larges sur le plateau, dos entièrement plaqué au dossier. On descend tant que le bassin reste posé ; dès qu''il décolle, c''est le bas du dos qui prend la suite et l''amplitude était trop grande.'),
    ('chaine-posterieure-progressive', 1, 'dead-bug', 5, 3, 8, 10, 4, 90, 'Le bas du dos reste en contact avec le sol du début à la fin. Dès qu''il décolle, la répétition est terminée.'),
    ('chaine-posterieure-progressive', 2, 'hip-hinge-baton', 1, 2, 6, 8, 4, 90, 'Même geste qu''en première séance : il sert de mise en route autant que de rappel technique.'),
    ('chaine-posterieure-progressive', 2, 'nordic-curl', 2, 2, 4, 5, 3, 180, 'Vous vous rattrapez avec les mains bien avant de tomber. Ce n''est pas une épreuve : deux séries courtes suffisent pendant les premières semaines.'),
    ('chaine-posterieure-progressive', 2, 'leg-curl-assis', 3, 4, 10, 12, 3, 90, 'Assis, la cuisse est en position allongée : c''est complémentaire du travail à genoux, pas redondant. C''est ici que se fait le gros du volume de la semaine, à charge modérée.'),
    ('chaine-posterieure-progressive', 2, 'hip-thrust-elastique', 4, 3, 10, 12, 3, 90, 'Élastique en travers des hanches, menton rentré, côtes basses. On monte jusqu''à l''alignement cuisses-tronc et pas au-delà : la hauteur gagnée en cambrant ne vient pas des hanches.'),
    ('chaine-posterieure-progressive', 2, 'bird-dog', 5, 3, 6, 8, 4, 90, 'Lent, sans balancer le bassin. Une répétition = un bras et la jambe opposée, tenus quelques secondes.'),
    ('controle-avant-charge', 1, 'quad-setting', 1, 2, 8, 10, 4, 45, 'Une répétition = une contraction tenue quelques secondes, genou tendu. Sert à réveiller la cuisse, pas à la fatiguer.'),
    ('controle-avant-charge', 1, 'equilibre-unipodal', 2, 3, 4, 5, 4, 45, 'Une répétition = un maintien. Regard fixé sur un point, une main à portée d''un appui stable.'),
    ('controle-avant-charge', 1, 'pont-fessier', 3, 3, 10, 12, 3, 90, 'Poussez par les talons, montez jusqu''à l''alignement épaule-hanche-genou, sans cambrer davantage.'),
    ('controle-avant-charge', 1, 'monster-walk', 4, 3, 10, 12, 3, 90, 'Genoux légèrement fléchis, pas de côté lents. Une répétition = un pas par côté.'),
    ('controle-avant-charge', 1, 'hip-hinge-baton', 5, 3, 8, 10, 4, 90, 'Le bâton reste en contact avec la nuque, le haut du dos et le bas du dos. Le mouvement part des hanches qui reculent, les genoux ne font que suivre.'),
    ('controle-avant-charge', 1, 'squat-elastique', 6, 3, 8, 10, 4, 90, 'Descendez seulement dans l''amplitude où le genou reste calme, quitte à vous arrêter très haut. La profondeur viendra ensuite.'),
    ('controle-avant-charge', 1, 'dead-bug', 7, 3, 8, 10, 4, 90, 'Le bas du dos reste plaqué au sol. Dès qu''il décolle, la répétition est terminée.'),
    ('controle-avant-charge', 2, 'terminal-knee-extension', 1, 3, 12, 15, 3, 90, 'Les derniers degrés d''extension sont ceux qui se perdent en premier et qui se récupèrent le plus lentement.'),
    ('controle-avant-charge', 2, 'presse-une-jambe', 2, 3, 10, 12, 3, 120, 'Une jambe à la fois, pour que le côté fort ne compense pas. Réglez la butée pour éviter la fin d''amplitude qui gêne.'),
    ('controle-avant-charge', 2, 'leg-curl-assis', 3, 3, 10, 12, 3, 90, 'Descente de la charge freinée, sans à-coup en fin de course.'),
    ('controle-avant-charge', 2, 'fente-statique', 4, 3, 6, 8, 4, 90, 'Pied avant bien à plat, buste droit, descente courte. Les pieds ne bougent pas d''une répétition à l''autre.'),
    ('controle-avant-charge', 2, 'abducteurs-machine', 5, 3, 12, 15, 3, 90, 'Charge modeste, mouvement lent. C''est un travail d''alignement autant que de force.'),
    ('controle-avant-charge', 2, 'mollets-une-jambe', 6, 3, 10, 12, 3, 90, 'Une main sur un appui pour l''équilibre, pas pour s''aider à monter.'),
    ('controle-avant-charge', 2, 'gainage-lateral-genoux', 7, 3, 5, 6, 4, 45, 'Une répétition = un maintien de quelques secondes. Genoux fléchis : la version la plus courte est celle qu''on tient proprement.'),
    ('hanche-laterale-progressive', 1, 'pont-fessier', 1, 2, 10, 12, 3, 90, 'Un coussin entre les genoux si l''appui vous gêne. Montée par les talons, sans cambrer le bas du dos.'),
    ('hanche-laterale-progressive', 1, 'abduction-elastique-debout', 2, 3, 12, 15, 3, 90, 'Jambe d''appui légèrement fléchie, bassin de niveau. Ne montez pas la jambe plus haut que ce que le bassin permet sans basculer.'),
    ('hanche-laterale-progressive', 1, 'clamshell', 3, 2, 12, 15, 3, 90, 'Allongé sur le côté, un coussin sous la hanche d''appui si elle se plaint. Bassin immobile : c''est la hanche qui tourne, le tronc ne roule pas en arrière.'),
    ('hanche-laterale-progressive', 1, 'squat-gobelet', 4, 2, 8, 10, 3, 120, 'Charge modeste tenue devant la poitrine. Amplitude confortable, pieds bien à plat, poids réparti sur les deux jambes.'),
    ('hanche-laterale-progressive', 1, 'hip-hinge-baton', 5, 2, 8, 10, 4, 90, 'Un bâton le long du dos, en contact à la tête, entre les omoplates et au bas du dos. Les hanches reculent, les trois contacts ne bougent pas.'),
    ('hanche-laterale-progressive', 1, 'equilibre-unipodal', 6, 2, 6, 8, 4, 90, 'Une répétition = un maintien d''une quinzaine de secondes. Le bassin doit rester horizontal : c''est exactement le travail visé.'),
    ('hanche-laterale-progressive', 1, 'dead-bug', 7, 3, 8, 10, 4, 90, 'Bas du dos plaqué au sol pendant tout le mouvement. Une répétition = un bras et la jambe opposée.'),
    ('hanche-laterale-progressive', 2, 'abducteurs-machine', 1, 3, 12, 15, 3, 90, 'Réglage étroit au départ : on cherche la charge, pas l''amplitude extrême. Dos calé, on ne s''aide pas du buste.'),
    ('hanche-laterale-progressive', 2, 'presse-a-cuisses', 2, 2, 10, 12, 3, 120, 'Pieds à largeur de bassin. Ne laissez pas les genoux se rapprocher en fin de série.'),
    ('hanche-laterale-progressive', 2, 'hip-thrust-elastique', 3, 2, 12, 15, 3, 90, 'Menton rentré, côtes basses. La poussée finit par les hanches, pas par le bas du dos.'),
    ('hanche-laterale-progressive', 2, 'monster-walk', 4, 2, 10, 12, 3, 90, 'Élastique au-dessus des genoux, pas aux chevilles. Une répétition = un pas par côté, lent, sans laisser l''élastique vous ramener.'),
    ('hanche-laterale-progressive', 2, 'leg-curl-assis', 5, 3, 10, 12, 3, 90, 'Bassin bien calé contre le dossier, retour freiné jusqu''au bout.'),
    ('hanche-laterale-progressive', 2, 'equilibre-unipodal', 6, 2, 6, 8, 4, 90, 'Une répétition = un maintien d''une quinzaine de secondes. Deux fois par semaine : c''est la répétition qui compte ici, pas la difficulté.'),
    ('hanche-laterale-progressive', 2, 'suitcase-carry', 7, 2, 6, 8, 4, 90, 'Une répétition = un aller d''une dizaine de pas, charge d''un seul côté, puis on change de main. Épaules de niveau, pas d''inclinaison du buste : c''est le bassin qui tient.'),
    ('mollet-cheville-tempo-lent', 1, 'mollets-debout', 1, 3, 6, 8, 3, 180, 'Trois secondes pour monter, une pause en haut, trois secondes pour redescendre. Le talon descend aussi bas que la marche le permet, sans à-coup. C''est le seul exercice de la séance où l''on cherche la charge.'),
    ('mollet-cheville-tempo-lent', 1, 'mollets-assis', 2, 2, 10, 12, 3, 120, 'Genou fléchi : c''est l''autre portion du mollet qui travaille, celle que la position debout laisse de côté. Même tempo, charge plus légère.'),
    ('mollet-cheville-tempo-lent', 1, 'dorsiflexion-cheville', 3, 2, 12, 15, 3, 90, 'Élastique léger, lent dans les deux sens. Le retour compte autant que la traction.'),
    ('mollet-cheville-tempo-lent', 1, 'leg-curl-assis', 4, 2, 10, 12, 3, 90, 'Deux séries, pour garder l''arrière de la cuisse dans le coup. Ce n''est pas la pièce principale de la séance, et ça ne doit pas le devenir.'),
    ('mollet-cheville-tempo-lent', 2, 'equilibre-unipodal', 1, 2, 4, 5, 4, 60, 'Une répétition = un maintien, une main à portée d''un appui. En début de séance : c''est aussi le repère qui vous dit où en est le côté faible.'),
    ('mollet-cheville-tempo-lent', 2, 'mollets-une-jambe', 2, 3, 6, 8, 3, 150, 'Une main sur un mur pour l''équilibre, pas pour s''aider à monter. Même tempo que debout : trois secondes dans chaque sens. Commencez par le côté faible, et le côté fort ne fait pas plus que ce que le faible a fait.'),
    ('mollet-cheville-tempo-lent', 2, 'eversion-cheville', 3, 2, 12, 15, 3, 90, 'Contrôle du bord externe du pied. Peu spectaculaire, et souvent ce qui manque le plus. Le pied part du bord interne et revient lentement.'),
    ('mollet-cheville-tempo-lent', 2, 'pont-fessier', 4, 2, 10, 12, 3, 90, 'En fin de séance, sans charge. Les pieds restent à plat : le mollet ne pousse pas, il a déjà travaillé.'),
    ('retour-progressif-post-partum', 1, 'squat-gobelet', 1, 3, 8, 10, 3, 120, 'Charge modeste, expirez en remontant. Si vous devez bloquer votre respiration pour finir la série, la série était trop longue.'),
    ('retour-progressif-post-partum', 1, 'rowing-elastique', 2, 4, 10, 12, 3, 120, 'Coudes le long du corps, omoplates qui glissent vers le bas et vers l''arrière.'),
    ('retour-progressif-post-partum', 1, 'pompes-inclinees', 3, 4, 6, 8, 3, 120, 'Mains sur un plan surélevé : plus le plan est haut, plus c''est accessible. Commencez plus haut que ce que vous croyez nécessaire.'),
    ('retour-progressif-post-partum', 1, 'pont-fessier', 4, 3, 10, 12, 3, 90, 'Expirez en montant. Le mouvement est lent, sans chercher à monter plus haut que l''alignement.'),
    ('retour-progressif-post-partum', 1, 'leg-curl-elastique', 5, 3, 10, 12, 3, 90, 'Bassin posé, le mouvement vient du genou seul. Retour lent, sans lâcher l''élastique.'),
    ('retour-progressif-post-partum', 1, 'abduction-elastique-debout', 6, 2, 12, 15, 3, 90, 'Bassin de niveau. C''est la jambe d''appui qui travaille autant que celle qui bouge.'),
    ('retour-progressif-post-partum', 1, 'face-pull-elastique', 7, 2, 12, 15, 3, 90, 'Élastique à hauteur du visage, coudes hauts, sans creuser le bas du dos pour aller plus loin.'),
    ('retour-progressif-post-partum', 1, 'dead-bug', 8, 3, 8, 10, 4, 90, 'Bas du dos en contact avec le sol du début à la fin, respiration continue. Dès qu''il décolle, la répétition est finie.'),
    ('retour-progressif-post-partum', 1, 'equilibre-unipodal', 9, 2, 6, 8, 4, 90, 'Une répétition = un maintien contrôlé, en alternant les jambes. Une main à portée d''un appui stable.'),
    ('retour-progressif-post-partum', 2, 'fente-statique', 1, 3, 6, 8, 3, 120, 'Un appui à portée de main. Descente courte, buste droit, les pieds ne bougent pas.'),
    ('retour-progressif-post-partum', 2, 'tirage-horizontal', 2, 4, 10, 12, 3, 120, 'Buste stable, sans se laisser tirer en avant en fin de série.'),
    ('retour-progressif-post-partum', 2, 'developpe-elastique', 3, 4, 10, 12, 3, 120, 'Poussée devant soi, à hauteur de poitrine. Expirez en poussant, jamais en bloquant.'),
    ('retour-progressif-post-partum', 2, 'hip-thrust-elastique', 4, 3, 10, 12, 3, 90, 'Côtes basses, menton rentré. On monte jusqu''à l''alignement, pas au-delà.'),
    ('retour-progressif-post-partum', 2, 'hip-hinge-baton', 5, 3, 8, 10, 4, 90, 'Le bâton garde trois contacts : tête, milieu du dos, sacrum. Reculez les hanches, ne pliez pas la taille.'),
    ('retour-progressif-post-partum', 2, 'retraction-scapulaire', 6, 2, 12, 15, 3, 90, 'Seules les omoplates bougent. Les bras restent tendus et les épaules ne montent pas vers les oreilles.'),
    ('retour-progressif-post-partum', 2, 'equilibre-unipodal', 7, 2, 6, 8, 4, 90, 'Une répétition = un maintien contrôlé, en alternant les jambes. Une main à portée d''un appui stable.'),
    ('retour-progressif-post-partum', 2, 'pallof-press', 8, 3, 8, 10, 4, 90, 'Le but est de ne pas tourner. Charge légère, respiration continue, jamais de blocage.'),
    ('retour-progressif-post-partum', 2, 'suitcase-carry', 9, 2, 15, 20, 4, 60, 'En fin de séance. Une répétition = un pas. Quinze à vingt pas d''un côté, puis autant de l''autre, épaules de niveau. Prenez une charge que vous pourriez porter deux fois plus longtemps.'),
    ('coiffe-et-omoplate', 1, 'rotation-externe-elastique', 1, 3, 12, 15, 4, 90, 'Coude collé aux côtes, une serviette roulée entre le bras et le tronc. Le mouvement vient de l''épaule, pas du buste qui pivote.'),
    ('coiffe-et-omoplate', 1, 'rotation-interne-elastique', 2, 2, 12, 15, 4, 90, 'Même position de coude. On travaille les deux sens : une coiffe ne se renforce pas d''un seul côté.'),
    ('coiffe-et-omoplate', 1, 'retraction-scapulaire', 3, 2, 10, 12, 4, 90, 'Les omoplates glissent vers le bas et vers l''arrière, sans hausser les épaules vers les oreilles.'),
    ('coiffe-et-omoplate', 1, 'wall-slide', 4, 2, 8, 10, 4, 90, 'Avant-bras au contact du mur, montée lente. Arrêtez-vous là où le contact se perd.'),
    ('coiffe-et-omoplate', 1, 'rowing-elastique', 5, 4, 10, 12, 3, 120, 'Coudes le long du corps, on tire vers le nombril. Les coudes s''arrêtent au niveau des côtes, ils ne partent pas derrière.'),
    ('coiffe-et-omoplate', 2, 'rotation-externe-couche', 1, 3, 10, 12, 4, 90, 'Sur le côté, coude au corps, haltère léger. Ne montez pas plus haut que l''horizontale au début.'),
    ('coiffe-et-omoplate', 2, 'scaption', 2, 2, 10, 12, 4, 90, 'Bras à environ trente degrés en avant du plan du corps, pouces vers le haut, jamais plus haut que l''épaule les premières semaines.'),
    ('coiffe-et-omoplate', 2, 'serratus-punch', 3, 3, 10, 12, 4, 90, 'Le bras pousse vers le plafond en fin de course, l''omoplate suit. Petit mouvement, petite charge.'),
    ('coiffe-et-omoplate', 2, 'pull-apart-elastique', 4, 2, 12, 15, 4, 90, 'Élastique tenu devant soi, bras à hauteur de poitrine. On écarte jusqu''à la largeur des épaules, pas au-delà.'),
    ('coiffe-et-omoplate', 2, 'rowing-haltere', 5, 4, 10, 12, 3, 120, 'Main libre en appui sur un banc, dos à plat. L''haltère monte le long des côtes et s''arrête là.'),
    ('coiffe-et-omoplate', 3, 'rotation-externe-elastique', 1, 3, 12, 15, 4, 90, 'Même consigne qu''en séance A : coude aux côtes, geste lent, aucune compensation du buste.'),
    ('coiffe-et-omoplate', 3, 'scaption', 2, 2, 10, 12, 4, 90, 'Descente aussi lente que la montée. Si l''épaule remonte vers l''oreille, la série est finie.'),
    ('coiffe-et-omoplate', 3, 'face-pull-elastique', 3, 3, 12, 15, 4, 90, 'Élastique à hauteur de visage, coudes hauts. Tirez vers le front, pas vers la poitrine.'),
    ('coiffe-et-omoplate', 3, 'y-t-w', 4, 2, 8, 10, 4, 90, 'Haltères très légers, ou aucun. Ce mouvement se juge à la qualité, jamais à la charge.'),
    ('coiffe-et-omoplate', 3, 'rowing-elastique', 5, 4, 10, 12, 3, 120, null),
    ('equilibre-et-appui', 1, 'equilibre-unipodal', 1, 2, 6, 8, 4, 90, 'Une répétition = un maintien de quelques secondes, une main sur l''appui. En début de séance, jambes fraîches — pas après le reste.'),
    ('equilibre-et-appui', 1, 'quad-setting', 2, 2, 8, 10, 4, 90, 'Une répétition = une contraction tenue quelques secondes, jambe tendue. Se fait assis, sans matériel.'),
    ('equilibre-et-appui', 1, 'squat-elastique', 3, 3, 8, 10, 4, 120, 'Comme pour vous asseoir sur une chaise placée derrière vous, puis remonter sans élan. Allez seulement où vous êtes sûr de pouvoir remonter.'),
    ('equilibre-et-appui', 1, 'pont-fessier', 4, 3, 10, 12, 3, 90, null),
    ('equilibre-et-appui', 1, 'abduction-elastique-debout', 5, 2, 12, 15, 3, 90, 'Une main sur un appui stable. Le bassin reste de niveau, la jambe monte peu.'),
    ('equilibre-et-appui', 1, 'hip-hinge-baton', 6, 2, 8, 10, 4, 90, 'Un bâton ou un manche à balai le long du dos, en contact à la tête, entre les omoplates et au bas du dos. Le mouvement vient des hanches. Si un des trois contacts se décolle, descendez moins bas.'),
    ('equilibre-et-appui', 1, 'leg-curl-elastique', 7, 3, 10, 12, 3, 90, null),
    ('equilibre-et-appui', 1, 'mollets-une-jambe', 8, 2, 8, 10, 3, 90, 'Une main sur l''appui. Si une jambe seule est trop difficile, faites les deux ensemble : c''est un début, pas un échec.'),
    ('equilibre-et-appui', 1, 'marche-pointes', 9, 2, 18, 20, 4, 45, 'En fin de séance, le long d''un plan de travail. Une répétition = un pas, lentement.'),
    ('equilibre-et-appui', 2, 'equilibre-unipodal', 1, 2, 6, 8, 4, 90, 'Une répétition = un maintien de quelques secondes, une main sur l''appui. Comparez les deux côtés : l''écart entre eux compte plus que la durée.'),
    ('equilibre-et-appui', 2, 'fente-statique', 2, 2, 6, 8, 3, 120, 'Sans charge, appui à portée de main, descente courte. Les pieds ne bougent pas d''une répétition à l''autre.'),
    ('equilibre-et-appui', 2, 'terminal-knee-extension', 3, 3, 12, 15, 3, 90, null),
    ('equilibre-et-appui', 2, 'monster-walk', 4, 2, 10, 12, 3, 90, 'Le long d''un plan de travail. Une répétition = un pas par côté, sans laisser l''élastique vous ramener.'),
    ('equilibre-et-appui', 2, 'pont-fessier-une-jambe', 5, 2, 6, 8, 3, 90, 'Si le bassin bascule d''un côté, revenez au pont sur deux appuis pour cette série.'),
    ('equilibre-et-appui', 2, 'hip-hinge-baton', 6, 2, 8, 10, 4, 90, 'Mêmes trois contacts qu''au jour Jambes. C''est le geste de ramasser quelque chose au sol, répété au propre.'),
    ('equilibre-et-appui', 2, 'leg-curl-elastique', 7, 3, 10, 12, 3, 90, null),
    ('equilibre-et-appui', 2, 'mollets-une-jambe', 8, 2, 8, 10, 3, 90, 'Une main sur l''appui. Si une jambe seule est trop difficile, faites les deux ensemble.'),
    ('equilibre-et-appui', 2, 'wall-sit', 9, 2, 6, 8, 4, 90, 'Une répétition = un maintien de quelques secondes. Dos au mur, genoux au-dessus des chevilles, remontez avant que les cuisses ne tremblent — c''est pour cela qu''il n''y a que deux séries.'),
    ('equilibre-et-appui', 2, 'marche-talons', 10, 2, 18, 20, 4, 45, 'En fin de séance, le long d''un plan de travail. Une répétition = un pas, orteils décollés.'),
    ('circuit-stations', 1, 'squat-gobelet', 1, 3, 8, 12, 3, 120, 'Premier poste parce que c''est le plus exigeant : faites-le pendant que vous êtes frais. Haltère tenu contre la poitrine, coudes à l''intérieur des genoux. Descendez à la profondeur où le dos reste droit, pas plus bas. Deux minutes de repos entre les séries, montre en main.'),
    ('circuit-stations', 1, 'pompes-inclinees', 2, 3, 10, 15, 3, 90, 'Plus l''appui est haut, plus c''est facile. Réglez la hauteur pour que la dernière répétition de la troisième série reste propre, pas la première de la première.'),
    ('circuit-stations', 1, 'rowing-elastique', 3, 3, 12, 15, 3, 90, 'Tirez les coudes vers l''arrière plutôt que les mains : ce sont les omoplates qui doivent se rapprocher.'),
    ('circuit-stations', 1, 'pont-fessier', 4, 3, 12, 15, 3, 90, 'Poussez par les talons et montez jusqu''à l''alignement cuisses-tronc, pas plus haut : au-delà, c''est le bas du dos qui finit le mouvement.'),
    ('circuit-stations', 1, 'leg-curl-elastique', 5, 3, 12, 15, 3, 90, null),
    ('circuit-stations', 1, 'elevation-laterale', 6, 3, 12, 15, 3, 90, 'Charges légères, montée jusqu''à la hauteur des épaules et pas au-dessus. Si les coudes partent avant les mains, l''haltère est trop lourd.'),
    ('circuit-stations', 1, 'curl-elastique', 7, 3, 12, 15, 3, 90, null),
    ('circuit-stations', 1, 'extension-triceps-elastique', 8, 3, 12, 15, 3, 90, null),
    ('circuit-stations', 1, 'dead-bug', 9, 3, 8, 12, 3, 90, 'Une répétition = un bras et la jambe opposée qui descendent puis remontent, en alternant les côtés. Le bas du dos reste au contact du sol ; dès qu''il se décolle, la série est terminée.'),
    ('circuit-stations', 1, 'bird-dog', 10, 3, 8, 12, 3, 90, 'Une répétition par côté, bras et jambe opposés, lentement. Un verre d''eau posé dans le bas du dos ne devrait pas déborder.'),
    ('circuit-stations', 1, 'marche-pointes', 11, 3, 20, 30, 3, 60, 'Comptez un pas par répétition. Dernier poste de la séance : c''est le seul, avec son équivalent de la séance B, où le repos est court — série longue, charge nulle, c''est voulu.'),
    ('circuit-stations', 2, 'hip-hinge-baton', 1, 2, 10, 12, 3, 90, 'Le bâton touche la nuque, le haut du dos et le sacrum : ces trois points ne se quittent pas. Sans charge, lentement, et vous vous arrêtez dès que l''un des trois points décolle. C''est le geste que vous refaites chaque fois que vous ramassez quelque chose au sol.'),
    ('circuit-stations', 2, 'fente-statique', 2, 3, 8, 12, 3, 120, 'Huit à douze répétitions par jambe. Appui arrière léger, le genou avant reste au-dessus du pied. Deux minutes de repos entre les séries.'),
    ('circuit-stations', 2, 'developpe-elastique', 3, 3, 10, 15, 3, 90, null),
    ('circuit-stations', 2, 'tirage-elastique-haut', 4, 3, 10, 15, 3, 90, null),
    ('circuit-stations', 2, 'hip-thrust-elastique', 5, 3, 12, 15, 3, 90, null),
    ('circuit-stations', 2, 'leg-curl-elastique', 6, 3, 12, 15, 3, 90, 'Le même poste qu''en séance A, et c''est voulu : les ischio-jambiers ont besoin de deux rendez-vous par semaine, et celui-ci se charge sans rien demander au dos. La charnière au bâton du premier poste, elle, se fait sans charge et ne compte pas comme travail.'),
    ('circuit-stations', 2, 'scaption', 7, 3, 12, 15, 3, 90, 'Bras montés à mi-chemin entre l''avant et le côté, pouces vers le haut, pas plus haut que les épaules.'),
    ('circuit-stations', 2, 'curl-marteau', 8, 3, 10, 15, 3, 90, null),
    ('circuit-stations', 2, 'kickback-triceps', 9, 3, 12, 15, 3, 90, null),
    ('circuit-stations', 2, 'bird-dog', 10, 3, 8, 12, 3, 90, 'Une répétition par côté, bras et jambe opposés, lentement. Deuxième passage de la semaine sur ce poste : le bas du dos travaille court et souvent, pas long et rare.'),
    ('circuit-stations', 2, 'mollets-une-jambe', 11, 3, 12, 15, 3, 90, 'Sur une jambe, un doigt posé sur un mur si l''équilibre manque. Montée lente, descente plus lente encore. Douze à quinze répétitions par jambe.'),
    ('circuit-stations', 2, 'suitcase-carry', 12, 3, 20, 30, 3, 60, 'Un haltère d''un seul côté, bras le long du corps. Un pas vaut une répétition ; changez de main à chaque série. Les épaules restent à la même hauteur : dès que le tronc penche du côté de l''haltère, posez-le, la série est finie.'),
    ('blocs-de-repetitions', 1, 'presse-a-cuisses', 1, 4, 6, 15, 2, 180, 'Le repère de charge du programme. Semaines 1 et 2 en haut de la fourchette, 3 et 4 au milieu, 5 et 6 en bas ; à l''intérieur d''une quinzaine, c''est la charge qui monte, pas les répétitions.'),
    ('blocs-de-repetitions', 1, 'leg-curl-assis', 2, 4, 8, 15, 2, 150, 'Ne descend pas aussi bas que la presse : les ischio-jambiers restent au-dessus de huit répétitions les six semaines.'),
    ('blocs-de-repetitions', 1, 'hip-thrust', 3, 2, 8, 15, 2, 150, null),
    ('blocs-de-repetitions', 1, 'developpe-machine-convergent', 4, 2, 6, 15, 2, 180, 'Machine plutôt qu''haltères : le trajet est guidé et, en fin de série, il n''y a aucune charge à reposer au-dessus de toi.'),
    ('blocs-de-repetitions', 1, 'developpe-incline-machine', 5, 2, 8, 15, 2, 150, null),
    ('blocs-de-repetitions', 1, 'tirage-vertical-prise-neutre', 6, 2, 6, 15, 2, 180, null),
    ('blocs-de-repetitions', 1, 'rowing-machine-buste-soutenu', 7, 2, 8, 15, 2, 150, 'Buste soutenu : la position ne se dégrade pas quand la série devient difficile.'),
    ('blocs-de-repetitions', 1, 'face-pull', 8, 3, 12, 15, 2, 90, 'Ajouté pour le haut du dos, que le reste du circuit ne sollicite que de biais. Charge légère, mouvement large, jamais lourd.'),
    ('blocs-de-repetitions', 1, 'elevation-laterale', 9, 4, 12, 15, 2, 90, 'Les épaules restent dans la même fourchette les six semaines : une élévation latérale lourde n''apporte rien de plus.'),
    ('blocs-de-repetitions', 1, 'curl-halteres', 10, 4, 10, 15, 2, 90, null),
    ('blocs-de-repetitions', 1, 'extension-triceps-poulie', 11, 4, 10, 15, 2, 90, null),
    ('blocs-de-repetitions', 1, 'dead-bug-lest', 12, 4, 12, 15, 2, 90, 'Le compte est par côté. Les lombes restent au contact du sol : c''est ce contact qui fixe l''amplitude, pas la longueur de tes jambes.'),
    ('blocs-de-repetitions', 1, 'mollets-debout', 13, 4, 15, 20, 2, 60, 'En fin de séance : séries longues, repos court, charge modérée.'),
    ('blocs-de-repetitions', 2, 'presse-a-cuisses', 1, 4, 6, 15, 2, 180, 'Même nombre de répétitions qu''à la séance précédente. Si tu as fini avec plus de deux répétitions en réserve, monte la charge d''un cran.'),
    ('blocs-de-repetitions', 2, 'leg-curl-assis', 2, 4, 8, 15, 2, 150, null),
    ('blocs-de-repetitions', 2, 'hip-thrust', 3, 2, 8, 15, 2, 150, null),
