    ('blocs-de-repetitions', 2, 'dead-bug-lest', 12, 4, 12, 15, 2, 90, 'Le compte est par côté.'),
    ('blocs-de-repetitions', 2, 'mollets-debout', 13, 4, 15, 20, 2, 60, null),
    ('blocs-de-repetitions', 3, 'presse-a-cuisses', 1, 4, 6, 15, 2, 180, 'Troisième et dernière séance de la semaine. Note la charge : c''est elle qui sert de point de départ à la semaine suivante.'),
    ('blocs-de-repetitions', 3, 'leg-curl-assis', 2, 4, 8, 15, 2, 150, null),
