    ('blocs-de-repetitions', 3, 'dead-bug-lest', 12, 4, 12, 15, 2, 90, 'Le compte est par côté.'),
    ('blocs-de-repetitions', 3, 'mollets-debout', 13, 4, 15, 20, 2, 60, 'Dernier exercice de la semaine.'),
    ('ondulation-trois-semaines', 1, 'developpe-incline-halteres', 1, 3, 6, 8, 3, 180, 'Sans pareur, on garde trois répétitions en réserve : c''est ce qui te permet de reposer les haltères sur les cuisses au lieu de les lâcher.'),
    ('ondulation-trois-semaines', 1, 'developpe-machine-convergent', 2, 3, 8, 10, 2, 150, 'Second mouvement de poussée, sur machine : le trajet est tenu, donc tu peux charger sans avoir à stabiliser une deuxième fois après le développé aux haltères.'),
    ('ondulation-trois-semaines', 1, 'tirage-vertical-prise-neutre', 3, 3, 6, 8, 3, 180, null),
    ('ondulation-trois-semaines', 1, 'rowing-machine-buste-soutenu', 4, 3, 8, 10, 2, 150, 'Le buste soutenu retire le bas du dos de l''équation, ce qui compte sur la semaine où les charges sont les plus hautes.'),
    ('ondulation-trois-semaines', 1, 'developpe-epaules-machine', 5, 3, 8, 10, 3, 150, null),
    ('ondulation-trois-semaines', 1, 'elevation-laterale', 6, 2, 10, 12, 2, 90, 'Deux séries légères qui complètent le développé épaules. Monte à hauteur d''épaule, pas plus haut.'),
    ('ondulation-trois-semaines', 1, 'curl-barre-ez', 7, 3, 8, 10, 2, 90, null),
    ('ondulation-trois-semaines', 1, 'curl-marteau', 8, 2, 10, 12, 2, 90, null),
    ('ondulation-trois-semaines', 1, 'extension-triceps-machine', 9, 3, 8, 10, 2, 90, null),
    ('ondulation-trois-semaines', 1, 'extension-triceps-corde', 10, 2, 12, 15, 2, 90, null),
    ('ondulation-trois-semaines', 1, 'face-pull', 11, 4, 12, 15, 2, 90, 'Reste léger et lent : cet exercice n''est pas là pour la charge, il est là pour équilibrer tout ce qui pousse dans cette séance.'),
    ('ondulation-trois-semaines', 2, 'presse-a-cuisses', 1, 4, 6, 8, 3, 180, 'Descends jusqu''où le bassin reste plaqué au dossier, pas plus bas. C''est l''amplitude utile, et elle dépend de tes segments.'),
    ('ondulation-trois-semaines', 2, 'leg-curl-allonge', 2, 4, 8, 10, 2, 120, null),
    ('ondulation-trois-semaines', 2, 'presse-pieds-hauts', 3, 3, 8, 10, 2, 120, 'Pieds hauts sur le plateau : la charge part vers les fessiers et les ischio-jambiers plutôt que vers les quadriceps. Ne descends pas plus bas que ce que le bassin permet sans décoller.'),
    ('ondulation-trois-semaines', 2, 'fente-statique', 4, 3, 8, 10, 3, 120, 'Le compte est par jambe. Pied arrière posé, pas de déplacement : sur la semaine lourde, on ne rajoute pas d''équilibre à gérer.'),
    ('ondulation-trois-semaines', 2, 'mollets-debout', 5, 5, 10, 12, 2, 90, null),
    ('ondulation-trois-semaines', 2, 'pallof-press', 6, 3, 10, 12, 3, 90, 'Le compte est par côté. Le travail consiste à ne pas tourner, pas à pousser fort.'),
    ('ondulation-trois-semaines', 2, 'dead-bug', 7, 3, 10, 12, 3, 90, 'Le compte est par côté. Si le bas du dos décolle du sol, raccourcis le mouvement de jambe plutôt que de continuer.'),
    ('ondulation-trois-semaines', 3, 'developpe-incline-halteres', 1, 3, 6, 8, 3, 180, 'Même séance que la première de la semaine. Si les huit répétitions sont sorties proprement mardi, monte d''un cran ici.'),
    ('ondulation-trois-semaines', 3, 'developpe-machine-convergent', 2, 3, 8, 10, 2, 150, null),
    ('ondulation-trois-semaines', 3, 'tirage-vertical-prise-neutre', 3, 3, 6, 8, 3, 180, null),
    ('ondulation-trois-semaines', 3, 'rowing-machine-buste-soutenu', 4, 3, 8, 10, 2, 150, 'Le buste soutenu retire le bas du dos de l''équation, ce qui compte sur la semaine où les charges sont les plus hautes.'),
    ('ondulation-trois-semaines', 3, 'developpe-epaules-machine', 5, 3, 8, 10, 3, 150, null),
    ('ondulation-trois-semaines', 3, 'elevation-laterale', 6, 2, 10, 12, 2, 90, 'Monte à hauteur d''épaule, pas plus haut.'),
    ('ondulation-trois-semaines', 3, 'curl-barre-ez', 7, 3, 8, 10, 2, 90, null),
    ('ondulation-trois-semaines', 3, 'curl-marteau', 8, 2, 10, 12, 2, 90, null),
    ('ondulation-trois-semaines', 3, 'extension-triceps-machine', 9, 3, 8, 10, 2, 90, null),
    ('ondulation-trois-semaines', 3, 'extension-triceps-corde', 10, 2, 12, 15, 2, 90, null),
    ('ondulation-trois-semaines', 3, 'face-pull', 11, 4, 12, 15, 2, 90, 'Reste léger et lent : cet exercice n''est pas là pour la charge, il est là pour équilibrer tout ce qui pousse dans cette séance.'),
    ('ondulation-trois-semaines', 4, 'presse-a-cuisses', 1, 4, 6, 8, 3, 180, 'Descends jusqu''où le bassin reste plaqué au dossier, pas plus bas.'),
    ('ondulation-trois-semaines', 4, 'leg-curl-allonge', 2, 4, 8, 10, 2, 120, null),
    ('ondulation-trois-semaines', 4, 'presse-pieds-hauts', 3, 3, 8, 10, 2, 120, 'Pieds hauts sur le plateau : la charge part vers les fessiers et les ischio-jambiers plutôt que vers les quadriceps.'),
    ('ondulation-trois-semaines', 4, 'fente-statique', 4, 3, 8, 10, 3, 120, 'Le compte est par jambe. Pied arrière posé, pas de déplacement.'),
    ('ondulation-trois-semaines', 4, 'mollets-debout', 5, 5, 10, 12, 2, 90, null),
    ('ondulation-trois-semaines', 4, 'pallof-press', 6, 3, 10, 12, 3, 90, 'Le compte est par côté. Le travail consiste à ne pas tourner, pas à pousser fort.'),
    ('ondulation-trois-semaines', 4, 'dead-bug', 7, 3, 10, 12, 3, 90, 'Le compte est par côté. Si le bas du dos décolle du sol, raccourcis le mouvement de jambe.'),
    ('ondulation-trois-semaines', 5, 'developpe-couche-halteres', 1, 4, 10, 12, 2, 120, 'La charge descend par rapport à la semaine 1, le nombre de répétitions monte. C''est le même effort ressenti, pas le même travail.'),
    ('ondulation-trois-semaines', 5, 'developpe-machine-convergent', 2, 3, 10, 12, 2, 120, null),
    ('ondulation-trois-semaines', 5, 'tirage-vertical-supination', 3, 4, 10, 12, 2, 120, null),
    ('ondulation-trois-semaines', 5, 'rowing-machine-buste-soutenu', 4, 3, 10, 12, 2, 120, null),
    ('ondulation-trois-semaines', 5, 'elevation-laterale', 5, 3, 12, 15, 2, 90, null),
    ('ondulation-trois-semaines', 5, 'oiseau', 6, 2, 12, 15, 2, 90, 'Buste penché, coudes légèrement fléchis. Très léger : c''est l''arrière de l''épaule qui travaille, pas le haut du dos.'),
    ('ondulation-trois-semaines', 5, 'curl-incline', 7, 3, 10, 12, 2, 90, 'L''inclinaison étire davantage le biceps en bas. Si l''épaule tire dans cette position, redresse le dossier plutôt que de forcer.'),
    ('ondulation-trois-semaines', 5, 'curl-poulie', 8, 2, 12, 15, 2, 90, null),
    ('ondulation-trois-semaines', 5, 'extension-triceps-corde', 9, 3, 10, 12, 2, 90, null),
    ('ondulation-trois-semaines', 5, 'extension-triceps-machine', 10, 2, 12, 15, 2, 90, null),
    ('ondulation-trois-semaines', 5, 'face-pull', 11, 4, 15, 20, 2, 60, 'Seule série longue de la semaine, et elle est en dernier : léger, lent, sans balancer le buste.'),
    ('ondulation-trois-semaines', 6, 'presse-a-cuisses', 1, 4, 10, 12, 2, 120, null),
    ('ondulation-trois-semaines', 6, 'presse-une-jambe', 2, 3, 10, 12, 2, 120, 'Le compte est par jambe. Commence par la jambe la moins forte et donne à l''autre le même nombre de répétitions, pas plus.'),
    ('ondulation-trois-semaines', 6, 'leg-curl-assis', 3, 3, 10, 12, 2, 90, null),
    ('ondulation-trois-semaines', 6, 'curl-nordique-assiste', 4, 3, 6, 10, 3, 90, 'Freine la descente aussi loin que tu la contrôles, puis aide-toi des mains pour remonter. Trois répétitions bien freinées valent mieux que huit lâchées.'),
    ('ondulation-trois-semaines', 6, 'hip-thrust', 5, 3, 10, 12, 2, 120, 'Monte jusqu''à l''alignement cuisses-bassin-buste, pas au-delà : ce n''est pas le bas du dos qui doit finir le mouvement.'),
    ('ondulation-trois-semaines', 6, 'mollets-assis', 6, 5, 12, 15, 2, 90, null),
    ('ondulation-trois-semaines', 6, 'pallof-press', 7, 3, 12, 15, 3, 90, 'Le compte est par côté.'),
    ('ondulation-trois-semaines', 6, 'dead-bug', 8, 3, 12, 15, 3, 90, 'Le compte est par côté.'),
    ('ondulation-trois-semaines', 7, 'developpe-couche-halteres', 1, 4, 10, 12, 2, 120, null),
    ('ondulation-trois-semaines', 7, 'developpe-machine-convergent', 2, 3, 10, 12, 2, 120, null),
