    ('ondulation-trois-semaines', 8, 'pallof-press', 7, 3, 12, 15, 3, 90, 'Le compte est par côté.'),
    ('ondulation-trois-semaines', 8, 'dead-bug', 8, 3, 12, 15, 3, 90, 'Le compte est par côté.'),
    ('ondulation-trois-semaines', 9, 'developpe-machine-convergent', 1, 3, 12, 15, 2, 120, 'La séance n''ouvre pas sur une série longue. Ces trois-là sont en douze à quinze avec un vrai repos : c''est la mise en route, les séries longues arrivent ensuite.'),
    ('ondulation-trois-semaines', 9, 'tirage-horizontal-machine', 2, 3, 12, 15, 2, 120, null),
    ('ondulation-trois-semaines', 9, 'pec-deck', 3, 3, 15, 20, 2, 75, 'Règle le siège pour que tes mains partent à hauteur de poitrine, pas derrière la ligne des épaules.'),
    ('ondulation-trois-semaines', 9, 'tirage-vertical-prise-serree', 4, 3, 15, 20, 2, 75, 'Prise serrée, coudes qui descendent le long du corps. Charge nettement plus légère que les deux autres semaines.'),
    ('ondulation-trois-semaines', 9, 'oiseau-machine', 5, 3, 15, 20, 2, 60, null),
    ('ondulation-trois-semaines', 9, 'elevation-laterale-poulie', 6, 3, 15, 20, 2, 60, 'Le compte est par bras. Si la forme se dégrade avant le compte, tu t''arrêtes là : une série finie en balançant ne compte pas double.'),
    ('ondulation-trois-semaines', 9, 'curl-poulie', 7, 3, 15, 20, 2, 60, null),
    ('ondulation-trois-semaines', 9, 'curl-poulie-corde', 8, 2, 15, 20, 2, 60, null),
    ('ondulation-trois-semaines', 9, 'extension-triceps-poulie', 9, 3, 15, 20, 2, 60, null),
    ('ondulation-trois-semaines', 9, 'extension-triceps-machine', 10, 2, 15, 20, 2, 60, null),
    ('ondulation-trois-semaines', 9, 'face-pull', 11, 5, 15, 20, 2, 60, 'Dernier exercice, très léger. Il ferme la semaine la plus fatigante du cycle sur du travail d''équilibre plutôt que sur de la charge.'),
    ('ondulation-trois-semaines', 10, 'presse-a-cuisses', 1, 3, 12, 15, 2, 120, 'Quinze répétitions au plus, et deux minutes de repos entre les séries. La presse est le mouvement qui coupe le plus le souffle : c''est pour ça qu''elle reste dans cette zone même en semaine longue.'),
    ('ondulation-trois-semaines', 10, 'leg-curl-assis', 2, 3, 12, 15, 2, 90, null),
    ('ondulation-trois-semaines', 10, 'extension-jambes', 3, 3, 15, 20, 2, 60, 'Début des séries longues. Si l''avant du genou est gêné dans cette position, réduis l''amplitude en partant plus haut plutôt que d''alourdir la charge.'),
    ('ondulation-trois-semaines', 10, 'leg-curl-allonge', 4, 3, 15, 20, 2, 60, 'Deuxième variante de leg curl : allongé, la hanche n''est pas dans la même position qu''assis, et la course des ischio-jambiers change.'),
    ('ondulation-trois-semaines', 10, 'hip-thrust-machine', 5, 3, 15, 20, 2, 75, null),
    ('ondulation-trois-semaines', 10, 'abduction-hanche-poulie', 6, 3, 15, 20, 2, 45, 'Le compte est par jambe.'),
    ('ondulation-trois-semaines', 10, 'pallof-press', 7, 3, 15, 20, 3, 45, 'Le compte est par côté. Charge légère : le travail consiste à ne pas tourner.'),
    ('ondulation-trois-semaines', 10, 'dead-bug', 8, 3, 15, 20, 3, 45, 'Le compte est par côté. Si le bas du dos décolle du sol, raccourcis le mouvement de jambe plutôt que de continuer.'),
    ('ondulation-trois-semaines', 10, 'mollets-assis', 9, 5, 20, 25, 2, 45, 'La seule série de vingt à vingt-cinq du programme, et elle est en tout dernier. Sur les mollets, la série longue brûle sans couper le souffle.'),
    ('ondulation-trois-semaines', 11, 'developpe-machine-convergent', 1, 3, 12, 15, 2, 120, 'Mise en route en douze à quinze, avec un vrai repos. Les séries longues arrivent ensuite.'),
    ('ondulation-trois-semaines', 11, 'tirage-horizontal-machine', 2, 3, 12, 15, 2, 120, null),
    ('ondulation-trois-semaines', 11, 'pec-deck', 3, 3, 15, 20, 2, 75, 'Règle le siège pour que tes mains partent à hauteur de poitrine, pas derrière la ligne des épaules.'),
    ('ondulation-trois-semaines', 11, 'tirage-vertical-prise-serree', 4, 3, 15, 20, 2, 75, 'Prise serrée, coudes qui descendent le long du corps.'),
    ('ondulation-trois-semaines', 11, 'oiseau-machine', 5, 3, 15, 20, 2, 60, null),
    ('ondulation-trois-semaines', 11, 'elevation-laterale-poulie', 6, 3, 15, 20, 2, 60, 'Le compte est par bras. Si la forme se dégrade avant le compte, tu t''arrêtes là.'),
    ('ondulation-trois-semaines', 11, 'curl-poulie', 7, 3, 15, 20, 2, 60, null),
    ('ondulation-trois-semaines', 11, 'curl-poulie-corde', 8, 2, 15, 20, 2, 60, null),
    ('ondulation-trois-semaines', 11, 'extension-triceps-poulie', 9, 3, 15, 20, 2, 60, null),
    ('ondulation-trois-semaines', 11, 'extension-triceps-machine', 10, 2, 15, 20, 2, 60, null),
    ('ondulation-trois-semaines', 11, 'face-pull', 11, 5, 15, 20, 2, 60, 'Dernier exercice, très léger. Il ferme la semaine la plus fatigante du cycle sur du travail d''équilibre plutôt que sur de la charge.'),
    ('ondulation-trois-semaines', 12, 'presse-a-cuisses', 1, 3, 12, 15, 2, 120, 'Quinze répétitions au plus, et deux minutes de repos entre les séries.'),
    ('ondulation-trois-semaines', 12, 'leg-curl-assis', 2, 3, 12, 15, 2, 90, null),
    ('ondulation-trois-semaines', 12, 'extension-jambes', 3, 3, 15, 20, 2, 60, 'Début des séries longues. Si l''avant du genou est gêné dans cette position, réduis l''amplitude en partant plus haut plutôt que d''alourdir la charge.'),
    ('ondulation-trois-semaines', 12, 'leg-curl-allonge', 4, 3, 15, 20, 2, 60, 'Deuxième variante de leg curl : la hanche n''est pas dans la même position qu''assis, et la course des ischio-jambiers change.'),
    ('ondulation-trois-semaines', 12, 'hip-thrust-machine', 5, 3, 15, 20, 2, 75, null),
    ('ondulation-trois-semaines', 12, 'abduction-hanche-poulie', 6, 3, 15, 20, 2, 45, 'Le compte est par jambe.'),
    ('ondulation-trois-semaines', 12, 'pallof-press', 7, 3, 15, 20, 3, 45, 'Le compte est par côté. Charge légère : le travail consiste à ne pas tourner.'),
    ('ondulation-trois-semaines', 12, 'dead-bug', 8, 3, 15, 20, 3, 45, 'Le compte est par côté.'),
    ('ondulation-trois-semaines', 12, 'mollets-assis', 9, 5, 20, 25, 2, 45, 'La seule série de vingt à vingt-cinq du programme, et elle est en tout dernier.'),
    ('variantes-selon-morphologie', 1, 'developpe-couche-halteres', 1, 4, 8, 10, 2, 150, 'Haltères plutôt que barre : chaque bras suit son propre trajet au lieu d''être aligné de force. Descends jusqu''où les épaules restent posées sur le banc — si elles roulent vers l''avant en bas, tu es allé trop loin pour tes proportions. Repli : le développé machine convergent.'),
    ('variantes-selon-morphologie', 1, 'developpe-incline-machine', 2, 3, 10, 12, 2, 120, 'Règle le siège pour que les poignées partent au niveau du haut de la poitrine, pas du cou. Si l''inclinaison te fait travailler surtout l''épaule, baisse le dossier d''un cran.'),
    ('variantes-selon-morphologie', 1, 'tirage-vertical-prise-neutre', 3, 3, 10, 12, 2, 120, 'Prise neutre par défaut : c''est celle qui laisse l''épaule libre de son angle. Tire vers le haut de la poitrine, jamais derrière la nuque. Repli si tu n''as pas la poignée neutre : le tirage en supination.'),
    ('variantes-selon-morphologie', 1, 'rowing-machine-buste-soutenu', 4, 3, 10, 12, 2, 120, 'Le support de poitrine retire au bas du dos le travail de tenir la position. C''est le choix par défaut ici, y compris pour les gens qui n''ont aucune raison de le ménager.'),
    ('variantes-selon-morphologie', 1, 'elevation-laterale', 5, 4, 12, 15, 2, 90, 'Monte jusqu''à l''horizontale, pas au-dessus. Coudes très légèrement fléchis, pouces au niveau des autres doigts : si tu dois pencher le buste pour finir la série, la charge est trop lourde.'),
    ('variantes-selon-morphologie', 1, 'scaption', 6, 3, 12, 15, 2, 90, 'Même geste que l''élévation latérale, mais les bras montent à mi-chemin entre devant toi et sur le côté, dans l''axe de l''omoplate. Cherche l''angle où le bras monte sans que l''épaule ait à se réajuster en cours de route, et garde-le : il n''est pas au même endroit pour tout le monde. Hauteur d''épaule maximum. Repli si les haltères disponibles commencent déjà trop lourd : la même montée à la poulie, où la charge se règle plaque par plaque.'),
    ('variantes-selon-morphologie', 1, 'curl-barre-ez', 7, 5, 10, 12, 2, 90, 'La barre EZ est le choix par défaut parce que tout le monde n''a pas les coudes dans le même axe. Si les poignets tirent quand même, passe aux haltères : chaque main trouve alors sa rotation.'),
    ('variantes-selon-morphologie', 1, 'extension-triceps-corde', 8, 5, 12, 15, 2, 90, 'Coudes le long du corps, ils ne partent ni en avant ni sur les côtés. La corde permet aux poignets de tourner librement, ce que la barre droite interdit.'),
    ('variantes-selon-morphologie', 1, 'face-pull', 9, 3, 15, 20, 2, 60, 'Léger, lent, en fin de séance. Il équilibre tout ce qui a poussé aujourd''hui ; ce n''est pas un exercice où l''on cherche la charge.'),
    ('variantes-selon-morphologie', 2, 'presse-a-cuisses', 1, 4, 8, 12, 2, 150, 'La position des pieds sur le plateau change tout : plus haut, la charge va vers les fessiers et les ischio-jambiers ; plus bas, vers les quadriceps. Cherche la hauteur où le bassin ne décolle pas du dossier en bas, et garde-la.'),
    ('variantes-selon-morphologie', 2, 'leg-curl-assis', 2, 5, 10, 12, 2, 90, 'Cale le coussin sur le bas des cuisses et non sur les genoux. Version assise plutôt qu''allongée : elle évite d''avoir à creuser le bas du dos pour finir la série.'),
    ('variantes-selon-morphologie', 2, 'fente-statique', 3, 3, 10, 12, 2, 90, 'Le compte est par jambe. Pied arrière posé, pas de déplacement. Une main sur un appui est autorisée : ce n''est pas un exercice d''équilibre, et s''accrocher permet de charger la jambe correctement.'),
    ('variantes-selon-morphologie', 2, 'hip-thrust', 4, 3, 10, 12, 2, 120, 'Le banc se cale sous les omoplates, pas sous la nuque. Monte jusqu''à ce que le corps soit droit et pas plus haut : la suite du mouvement se fait avec le bas du dos, ce qu''on ne cherche pas.'),
    ('variantes-selon-morphologie', 2, 'mollets-assis', 5, 5, 12, 15, 2, 90, 'Genou fléchi, ce qui met en jeu le muscle profond du mollet. Descends complètement le talon avant de remonter : c''est l''amplitude basse qui fait le travail.'),
    ('variantes-selon-morphologie', 2, 'pallof-press', 6, 3, 10, 12, 3, 90, 'Le compte est par côté. Le travail consiste à résister à la rotation, pas à pousser fort : une charge modérée et rien qui bouge dans le buste.'),
    ('variantes-selon-morphologie', 2, 'bird-dog', 7, 3, 15, 20, 3, 45, 'Le compte est par côté. Lent et sans à-coup, le bassin ne tourne pas : c''est la seule chose qui compte ici, pas la vitesse. Il revient à l''identique sur l''autre séance du bas du corps — c''est voulu, pour que le bas du dos travaille deux fois dans la semaine et non une seule. Sans charge, en dernier.'),
    ('variantes-selon-morphologie', 3, 'tirage-horizontal', 1, 4, 10, 12, 2, 120, 'Buste vertical, il n''accompagne pas la traction en se balançant. Tire vers le nombril plutôt que vers la poitrine si tes bras sont longs : la barre arrive alors au bon endroit sans que les épaules partent en avant.'),
    ('variantes-selon-morphologie', 3, 'tirage-bras-tendus', 2, 3, 12, 15, 2, 90, 'Bras presque tendus, le mouvement vient des épaules et non des coudes. Si l''épaule est gênée quand les bras sont hauts, réduis le point de départ : commence au niveau du front plutôt qu''au-dessus de la tête.'),
    ('variantes-selon-morphologie', 3, 'developpe-machine-convergent', 3, 3, 10, 12, 2, 120, 'La machine convergente rapproche les mains en fin de poussée, ce qui suit le trajet naturel du bras. Version par défaut ici pour les gens à qui la barre impose un écartement fixe qui ne leur va pas.'),
    ('variantes-selon-morphologie', 3, 'pec-deck', 4, 3, 12, 15, 3, 90, 'Règle le siège pour partir mains à hauteur de poitrine, et si la machine a un réglage de départ, cale-le pour que les bras ne partent pas derrière la ligne des épaules : c''est cette position ouverte, et elle seule, qui gêne quand elle gêne. C''est aussi pourquoi il est prescrit ici une répétition plus loin de l''échec que le reste de la séance — la charge y est plus basse par construction, ce n''est pas à toi de la doser. Si l''ouverture reste gênante malgré ça, remplace par les pompes inclinées, mains sur un banc : tu poses tes mains où tu veux et les coudes ne peuvent pas partir en arrière. Changer d''écarté ne servirait à rien, ils demandent tous la même position.'),
    ('variantes-selon-morphologie', 3, 'oiseau-machine', 5, 4, 12, 15, 2, 90, 'Bras à hauteur d''épaule, coudes légèrement fléchis, et on ne serre pas les omoplates à fond : ce sont les deltoïdes arrière qu''on veut, pas les trapèzes.'),
    ('variantes-selon-morphologie', 3, 'curl-incline', 6, 5, 10, 12, 2, 90, 'L''inclinaison met le biceps en position étirée en bas, ce que le curl debout ne fait pas. Si l''épaule tire dans cette position bras en arrière, redresse le dossier : le curl assis buste droit reste utile.'),
    ('variantes-selon-morphologie', 3, 'extension-triceps-machine', 7, 5, 12, 15, 2, 90, 'Le trajet est tenu par la machine, ce qui laisse les coudes tranquilles en fin de série quand la fatigue arrive.'),
    ('variantes-selon-morphologie', 3, 'dead-bug-lest', 8, 3, 8, 10, 3, 90, 'Le compte est par côté. Charge légère : dès que le bas du dos se décolle du sol, la série est finie, quel que soit le compte.'),
    ('variantes-selon-morphologie', 3, 'y-t-w', 9, 3, 15, 20, 3, 60, 'Trois positions de bras enchaînées — en Y, en T, puis en W — allongé sur un banc légèrement incliné, avec des haltères très légers. Une répétition, c''est les trois positions. C''est ce qui manque au haut du dos quand la séance a beaucoup tiré vers soi ; la charge n''est pas le sujet, l''amplitude l''est. Repli si la position à plat ventre ne te va pas : le face pull, debout à la poulie, atteint la même zone.'),
    ('variantes-selon-morphologie', 4, 'presse-une-jambe', 1, 4, 10, 12, 2, 120, 'Le compte est par jambe. Commence toujours par la jambe la moins forte et donne à l''autre le même nombre de répétitions : c''est comme ça qu''un écart se réduit au lieu de se creuser.'),
    ('variantes-selon-morphologie', 4, 'leg-curl-allonge', 2, 4, 10, 12, 2, 90, 'Version allongée ici, en complément de la version assise de l''autre séance : la hanche n''est pas dans la même position, et les ischio-jambiers ne travaillent pas au même endroit de leur course.'),
    ('variantes-selon-morphologie', 4, 'hip-thrust-machine', 3, 3, 12, 15, 2, 90, 'La machine évite l''installation de la barre, qui est la partie la plus pénible de cet exercice. Si tu n''en as pas, la version barre avec un tapis épais fait la même chose.'),
    ('variantes-selon-morphologie', 4, 'extension-jambes', 4, 3, 12, 15, 2, 90, 'Cet exercice charge l''avant du genou plus que les autres du programme. Reste dans une amplitude confortable et modérée en charge ; si la position te gêne malgré ça, remplace par une série de presse une jambe.'),
    ('variantes-selon-morphologie', 4, 'presse-pieds-hauts', 5, 3, 12, 15, 2, 90, 'Pieds hauts et écartés sur le plateau : la charge part vers les fessiers et les ischio-jambiers. Si tes fémurs sont longs, c''est souvent la position de presse la plus confortable, et rien n''interdit d''en faire ta position par défaut.'),
    ('variantes-selon-morphologie', 4, 'mollets-debout', 6, 5, 10, 15, 2, 90, 'Genou tendu ici, contrairement à la version assise de l''autre séance. Les deux sont nécessaires : elles ne touchent pas la même partie du mollet.'),
    ('variantes-selon-morphologie', 4, 'bird-dog', 7, 3, 15, 20, 3, 45, 'Le compte est par côté. Lent et sans à-coup, le bassin ne tourne pas. Même exercice que sur l''autre séance du bas du corps, et c''est voulu : ici c''est le retour dans la semaine qui compte, pas la variété. C''est la dernière chose de la séance, elle se fait sans charge.'),
    ('plafond-volontaire', 1, 'developpe-militaire', 1, 3, 5, 5, 3, 240, 'Charge calculée sur votre plafond, pas sur votre meilleur jour. Trois répétitions doivent rester en réserve à la dernière série.'),
    ('plafond-volontaire', 1, 'developpe-couche-halteres', 2, 3, 8, 10, 2, 150, null),
    ('plafond-volontaire', 1, 'tirage-vertical', 3, 4, 8, 12, 2, 120, null),
    ('plafond-volontaire', 1, 'face-pull', 4, 3, 12, 15, 3, 90, 'Présent à chaque tour du programme, séances allégées comprises : c''est ce qui rend deux développés par tour tenables dans la durée.'),
    ('plafond-volontaire', 1, 'dead-bug', 5, 3, 10, 12, 3, 90, null),
    ('plafond-volontaire', 2, 'souleve-de-terre', 1, 3, 5, 5, 3, 300, 'Reposez la barre au sol entre chaque répétition et repartez d''une position propre. Trois répétitions en réserve, sans exception.'),
    ('plafond-volontaire', 2, 'presse-a-cuisses', 2, 3, 10, 12, 2, 180, null),
    ('plafond-volontaire', 2, 'leg-curl-allonge', 3, 3, 10, 12, 2, 120, null),
    ('plafond-volontaire', 2, 'mollets-debout', 4, 3, 12, 15, 2, 90, null),
    ('plafond-volontaire', 2, 'pallof-press', 5, 3, 10, 12, 3, 90, null),
    ('plafond-volontaire', 3, 'developpe-couche-barre', 1, 3, 5, 5, 3, 240, 'Même règle que les autres barres : la charge vient du plafond, et trois répétitions restent en réserve.'),
    ('plafond-volontaire', 3, 'developpe-incline-halteres', 2, 4, 8, 10, 2, 150, null),
    ('plafond-volontaire', 3, 'rowing-haltere', 3, 4, 8, 10, 2, 150, null),
    ('plafond-volontaire', 3, 'traction-assistee', 4, 3, 6, 8, 2, 150, null),
    ('plafond-volontaire', 3, 'elevation-laterale', 5, 3, 12, 15, 3, 90, null),
    ('plafond-volontaire', 3, 'face-pull-elastique', 6, 3, 15, 20, 3, 60, 'En fin de séance, léger et long : c''est du travail d''endurance, pas une série de plus.'),
    ('plafond-volontaire', 4, 'squat-barre-dos', 1, 3, 5, 5, 3, 300, 'Charge calculée sur votre plafond. Trois répétitions en réserve : vous devez pouvoir refaire la série.'),
    ('plafond-volontaire', 4, 'fente-arriere', 2, 3, 8, 10, 2, 150, 'Le pas vers l''arrière charge moins le genou avant que le pas vers l''avant.'),
    ('plafond-volontaire', 4, 'leg-curl-assis', 3, 3, 10, 12, 2, 120, null),
    ('plafond-volontaire', 4, 'tirage-horizontal', 4, 4, 10, 12, 2, 120, null),
    ('plafond-volontaire', 4, 'mollets-assis', 5, 3, 12, 15, 2, 90, null),
    ('plafond-volontaire', 4, 'crunch-inverse', 6, 3, 12, 15, 3, 90, null),
    ('plafond-volontaire', 5, 'developpe-militaire', 1, 2, 5, 5, 3, 240, 'Tour allégé, à faire après trois tours complets : moitié de la charge habituelle, deux séries au lieu de trois. Cette séance doit sembler facile — c''est exactement ce qu''on lui demande.'),
    ('plafond-volontaire', 5, 'face-pull', 2, 2, 12, 15, 3, 90, null),
    ('plafond-volontaire', 5, 'dead-bug', 3, 2, 10, 12, 3, 90, null),
    ('plafond-volontaire', 6, 'souleve-de-terre', 1, 2, 5, 5, 3, 300, 'Moitié de la charge habituelle, deux séries. Reposez la barre au sol entre chaque répétition, comme d''habitude.'),
    ('plafond-volontaire', 6, 'leg-curl-allonge', 2, 2, 10, 12, 3, 120, null),
    ('plafond-volontaire', 6, 'pallof-press', 3, 2, 10, 12, 3, 90, null),
    ('plafond-volontaire', 7, 'developpe-couche-barre', 1, 2, 5, 5, 3, 240, 'Moitié de la charge habituelle, deux séries. Si la barre vous semble lourde ce jour-là, c''est le signe que le tour allégé arrivait au bon moment.'),
    ('plafond-volontaire', 7, 'rowing-haltere', 2, 2, 8, 10, 3, 150, null),
    ('plafond-volontaire', 7, 'face-pull-elastique', 3, 2, 15, 20, 3, 60, null),
    ('plafond-volontaire', 8, 'squat-barre-dos', 1, 2, 5, 5, 3, 300, 'Moitié de la charge habituelle, deux séries. Après cette séance, le tour allégé est terminé : reprenez à la première séance avec vos charges normales.'),
    ('plafond-volontaire', 8, 'tirage-horizontal', 2, 2, 10, 12, 3, 120, null),
    ('plafond-volontaire', 8, 'mollets-assis', 3, 2, 12, 15, 3, 90, null),
    ('reserve-de-repetitions', 1, 'squat-halteres', 1, 4, 6, 8, 3, 180, 'Choisissez la charge après la mise en train, pas la veille. Trois répétitions doivent rester à la dernière série. Les haltères restent le long du corps : rien ne repose sur la nuque.'),
    ('reserve-de-repetitions', 1, 'presse-a-cuisses', 2, 3, 8, 10, 3, 150, null),
    ('reserve-de-repetitions', 1, 'leg-curl-assis', 3, 4, 8, 10, 3, 120, null),
    ('reserve-de-repetitions', 1, 'abduction-hanche-poulie', 4, 3, 12, 15, 3, 90, null),
    ('reserve-de-repetitions', 1, 'mollets-debout', 5, 5, 12, 15, 3, 90, null),
    ('reserve-de-repetitions', 1, 'pallof-press', 6, 4, 10, 12, 3, 90, 'L''effort consiste à ne pas tourner. Si le buste part avec les bras, la charge est trop lourde.'),
    ('reserve-de-repetitions', 2, 'floor-press', 1, 5, 6, 8, 3, 180, 'Le sol arrête les coudes : c''est lui qui fixe l''amplitude, et non votre souplesse d''épaule.'),
    ('reserve-de-repetitions', 2, 'tirage-horizontal', 2, 4, 8, 10, 3, 150, null),
    ('reserve-de-repetitions', 2, 'scaption', 3, 4, 10, 12, 3, 90, 'Les bras montent en diagonale, à mi-chemin entre l''avant et le côté, et pas plus haut que les épaules.'),
    ('reserve-de-repetitions', 2, 'face-pull', 4, 4, 12, 15, 3, 90, null),
    ('reserve-de-repetitions', 2, 'curl-marteau', 5, 3, 10, 12, 3, 90, null),
    ('reserve-de-repetitions', 2, 'extension-triceps-corde', 6, 3, 12, 15, 3, 90, null),
    ('reserve-de-repetitions', 3, 'hip-thrust', 1, 4, 6, 8, 3, 180, 'Montez jusqu''à ce que le bassin soit dans l''axe des cuisses, pas au-delà. Le dos reste calé sur le banc du début à la fin.'),
    ('reserve-de-repetitions', 3, 'fente-arriere', 2, 3, 8, 10, 3, 150, 'Une jambe à la fois : les écarts entre les deux côtés se voient tout de suite, et c''est une information utile.'),
    ('reserve-de-repetitions', 3, 'curl-nordique-assiste', 3, 3, 8, 10, 3, 120, 'La difficulté se règle par l''amplitude et par l''appui des mains. Réduisez la descente tant que trois répétitions ne restent pas en réserve.'),
    ('reserve-de-repetitions', 3, 'leg-curl-allonge', 4, 3, 10, 12, 3, 120, null),
    ('reserve-de-repetitions', 3, 'mollets-assis', 5, 5, 12, 15, 3, 90, null),
    ('reserve-de-repetitions', 3, 'dead-bug', 6, 4, 10, 12, 3, 90, 'Le bas du dos reste au contact du sol. Dès qu''il se décolle, la jambe est allée trop loin.'),
    ('reserve-de-repetitions', 4, 'traction-assistee', 1, 4, 6, 8, 3, 180, 'L''assistance se règle comme une charge : elle baisse quand la réserve dépasse trois répétitions.'),
    ('reserve-de-repetitions', 4, 'developpe-incline-machine', 2, 5, 8, 10, 3, 150, null),
    ('reserve-de-repetitions', 4, 'rowing-haltere', 3, 3, 8, 10, 3, 150, null),
    ('reserve-de-repetitions', 4, 'elevation-laterale', 4, 4, 12, 15, 3, 90, null),
    ('reserve-de-repetitions', 4, 'y-t-w', 5, 4, 12, 15, 3, 90, null),
    ('reserve-de-repetitions', 4, 'curl-halteres', 6, 3, 10, 12, 3, 90, null),
    ('reserve-de-repetitions', 4, 'extension-triceps-machine', 7, 3, 12, 15, 3, 90, null),
    ('trois-etages', 1, 'squat-barre-dos', 1, 5, 3, 3, 2, 240, 'Étage 1. Les quatre premières séries montent vers la cinquième, qui est la seule difficile.'),
    ('trois-etages', 1, 'developpe-couche-barre', 2, 3, 10, 10, 3, 150, 'Étage 2. Ce n''est pas une variante du squat : c''est le développé couché du jour C, repris ici à environ deux tiers de la charge que vous y utilisez.'),
    ('trois-etages', 1, 'tirage-vertical', 3, 4, 12, 15, 3, 90, 'Étage 3. Léger, long, jamais forcé.'),
    ('trois-etages', 1, 'face-pull', 4, 3, 12, 15, 3, 90, 'Second tirage de la séance. Il n''est pas optionnel : c''est lui qui équilibre le développé.'),
    ('trois-etages', 1, 'mollets-assis', 5, 3, 12, 15, 3, 90, null),
    ('trois-etages', 1, 'dead-bug', 6, 3, 10, 12, 3, 90, null),
    ('trois-etages', 2, 'developpe-militaire', 1, 5, 3, 3, 2, 240, 'Étage 1. Si une gêne apparaît à l''épaule, arrêtez la série et reprenez plus léger — ne raccourcissez pas l''amplitude pour garder la charge.'),
    ('trois-etages', 2, 'hip-thrust', 2, 3, 10, 12, 3, 150, 'Étage 2. Il prend la place du second soulevé de terre hebdomadaire de la méthode d''origine. Il travaille les fessiers, pas l''arrière de la cuisse — d''où l''exercice suivant.'),
    ('trois-etages', 2, 'leg-curl-allonge', 3, 3, 12, 15, 3, 90, 'Étage 3. Seconde stimulation hebdomadaire des ischio-jambiers, sans charger le bas du dos avant le jour du soulevé de terre.'),
    ('trois-etages', 2, 'rowing-haltere', 4, 4, 12, 15, 3, 90, null),
    ('trois-etages', 2, 'pull-apart-elastique', 5, 3, 12, 15, 3, 90, 'Second tirage de la séance.'),
    ('trois-etages', 2, 'fente-arriere', 6, 2, 10, 12, 3, 120, 'Deux séries seulement, et c''est voulu : le squat, le hip thrust et le soulevé de terre couvrent déjà largement le volume fessier de la semaine.'),
    ('trois-etages', 3, 'developpe-couche-barre', 1, 5, 3, 3, 2, 240, 'Étage 1. Barres de sécurité ou partenaire, sans exception, à cette intensité.'),
    ('trois-etages', 3, 'presse-a-cuisses', 2, 3, 10, 10, 3, 180, 'Étage 2. Le squat revient ici sans la barre sur la nuque : une seule séance par semaine charge la colonne debout. Charge modérée, dix répétitions propres.'),
    ('trois-etages', 3, 'tirage-vertical-supination', 3, 4, 12, 15, 3, 90, null),
    ('trois-etages', 3, 'face-pull-elastique', 4, 3, 12, 15, 3, 90, 'Second tirage de la séance, le jour où le développé est le plus lourd.'),
    ('trois-etages', 3, 'mollets-debout', 5, 3, 12, 15, 3, 90, null),
    ('trois-etages', 3, 'pallof-press', 6, 3, 10, 12, 3, 90, null),
    ('trois-etages', 4, 'souleve-de-terre', 1, 5, 3, 3, 2, 300, 'Étage 1, et unique passage hebdomadaire du mouvement. Chaque répétition repart du sol, position remise en place.'),
    ('trois-etages', 4, 'developpe-militaire', 2, 3, 10, 10, 3, 150, 'Étage 2. Version moyenne du mouvement lourd du jour B.'),
    ('trois-etages', 4, 'rowing-machine-buste-soutenu', 3, 4, 12, 15, 3, 90, 'Buste soutenu : le bas du dos ne travaille pas, ce qui est voulu le jour du soulevé de terre.'),
    ('trois-etages', 4, 'oiseau', 4, 3, 12, 15, 3, 90, 'Second tirage de la séance. Épaule arrière, en contrepoids des dix séries lourdes de développé de la semaine.'),
    ('trois-etages', 4, 'leg-curl-assis', 5, 3, 12, 15, 3, 90, null),
    ('appui-et-transfert', 1, 'equilibre-unipodal', 1, 3, 30, 45, 4, 45, 'Les répétitions comptent des secondes, par jambe. Un doigt sur un mur les premières semaines, puis rien.'),
    ('appui-et-transfert', 1, 'hip-airplane', 2, 3, 5, 8, 4, 60, 'Répétitions par côté. Lentement : c''est un exercice de contrôle, pas d''amplitude.'),
    ('appui-et-transfert', 1, 'pont-fessier-une-jambe', 3, 3, 8, 12, 3, 60, 'Répétitions par jambe. Le bassin reste horizontal.'),
    ('appui-et-transfert', 1, 'hip-hinge-baton', 4, 3, 8, 12, 4, 45, 'Le bâton touche la nuque, le haut du dos et le sacrum du début à la fin : c''est le repère. Le mouvement vient des hanches, les genoux se déverrouillent sans plus.'),
    ('appui-et-transfert', 1, 'leg-curl-elastique', 5, 3, 12, 15, 3, 60, 'Répétitions par jambe. La descente est lente, c''est là que se fait le travail.'),
    ('appui-et-transfert', 1, 'wall-sit', 6, 3, 20, 40, 3, 60, 'Les répétitions comptent des secondes. La hauteur du bassin est le réglage : plus haut, plus facile.'),
    ('appui-et-transfert', 1, 'terminal-knee-extension', 7, 3, 12, 15, 3, 45, 'Répétitions par jambe. Le genou finit tendu sans se verrouiller d''un coup.'),
    ('appui-et-transfert', 1, 'monster-walk', 8, 2, 15, 20, 3, 45, 'Les répétitions comptent des pas, de côté. Les pieds restent parallèles.'),
    ('appui-et-transfert', 1, 'pull-apart-elastique', 9, 2, 12, 15, 3, 45, 'Entretien du haut du corps.'),
    ('appui-et-transfert', 1, 'developpe-elastique', 10, 2, 12, 15, 3, 60, 'Entretien du haut du corps.'),
    ('appui-et-transfert', 1, 'gainage-ventral', 11, 3, 20, 30, 3, 45, 'Les répétitions comptent des secondes. Mains posées sur une table plutôt qu''au sol si la position basse tire dans le bas du dos.'),
    ('appui-et-transfert', 1, 'rotation-thoracique', 12, 2, 8, 10, 4, 30, 'Répétitions par côté.'),
    ('appui-et-transfert', 2, 'marche-talons', 1, 2, 20, 30, 4, 30, 'Les répétitions comptent des pas.'),
    ('appui-et-transfert', 2, 'marche-pointes', 2, 2, 20, 30, 4, 30, 'Les répétitions comptent des pas.'),
    ('appui-et-transfert', 2, 'fente-statique', 3, 3, 8, 12, 3, 90, 'Répétitions par jambe. À vide d''abord ; les haltères ne viennent que si la position est stable et indolore.'),
    ('appui-et-transfert', 2, 'hip-hinge-baton', 4, 3, 8, 12, 3, 45, 'Le poids reste sur les talons et l''arrière de cuisse tire à mi-course : c''est le signe que la charnière vient bien des hanches.'),
    ('appui-et-transfert', 2, 'abduction-elastique-debout', 5, 3, 12, 15, 3, 45, 'Répétitions par jambe. La jambe d''appui travaille autant que celle qui bouge.'),
    ('appui-et-transfert', 2, 'clamshell', 6, 2, 12, 15, 4, 45, 'Répétitions par côté. Le bassin ne roule pas en arrière.'),
    ('appui-et-transfert', 2, 'rowing-elastique', 7, 3, 12, 15, 3, 60, 'Entretien du haut du corps.'),
    ('appui-et-transfert', 2, 'face-pull-elastique', 8, 2, 12, 15, 3, 45, 'Entretien du haut du corps.'),
    ('appui-et-transfert', 2, 'bird-dog', 9, 3, 6, 8, 3, 45, 'Répétitions par côté. Le bassin ne bascule pas.'),
    ('appui-et-transfert', 2, 'gainage-lateral-genoux', 10, 3, 20, 30, 3, 45, 'Les répétitions comptent des secondes, par côté.'),
    ('appui-et-transfert', 2, 'cat-cow', 11, 2, 8, 10, 4, 30, null),
    ('appui-et-transfert', 3, 'equilibre-unipodal', 1, 3, 30, 45, 4, 45, 'Les répétitions comptent des secondes, par jambe. Yeux fermés seulement si l''appui est déjà sûr.'),
    ('appui-et-transfert', 3, 'quad-setting', 2, 2, 10, 12, 4, 30, 'Répétitions par jambe, environ cinq secondes de contraction chacune.'),
    ('appui-et-transfert', 3, 'wall-sit', 3, 3, 25, 45, 3, 60, 'Les répétitions comptent des secondes.'),
    ('appui-et-transfert', 3, 'hip-thrust-une-jambe', 4, 3, 10, 12, 3, 60, 'Répétitions par jambe.'),
    ('appui-et-transfert', 3, 'leg-curl-elastique', 5, 4, 12, 15, 3, 60, 'Répétitions par jambe. La descente est lente, c''est là que se fait le travail.'),
    ('appui-et-transfert', 3, 'mollets-une-jambe', 6, 3, 10, 15, 3, 45, 'Répétitions par jambe. La descente est lente.'),
    ('appui-et-transfert', 3, 'suitcase-carry', 7, 3, 30, 40, 3, 60, 'Les répétitions comptent des pas, charge d''un seul côté. Les épaules restent au même niveau.'),
    ('appui-et-transfert', 3, 'tirage-elastique-haut', 8, 3, 10, 15, 3, 60, 'Entretien du haut du corps.'),
    ('appui-et-transfert', 3, 'pompes-inclinees', 9, 2, 8, 12, 3, 60, 'Entretien du haut du corps. Plus les mains sont hautes, plus c''est facile.'),
    ('appui-et-transfert', 3, 'dead-bug', 10, 3, 6, 10, 3, 45, 'Répétitions par côté.'),
    ('releve-et-portage', 1, 'turkish-get-up', 1, 3, 3, 3, 4, 180, 'Trois répétitions par côté, charge légère, trois minutes de repos. Le critère d''arrêt est la qualité du trajet, jamais la fatigue : une étape hésitante, on repose la cloche même s''il restait des répétitions.'),
    ('releve-et-portage', 1, 'developpe-elastique', 2, 3, 10, 15, 3, 90, 'Les coudes restent à quarante-cinq degrés du buste, pas à l''équerre.'),
    ('releve-et-portage', 1, 'goblet-squat-kettlebell', 3, 4, 8, 12, 3, 120, 'Les coudes glissent à l''intérieur des genoux, le buste reste droit.'),
    ('releve-et-portage', 1, 'rowing-haltere', 4, 4, 8, 12, 3, 90, 'Répétitions par bras.'),
    ('releve-et-portage', 1, 'suitcase-carry', 5, 2, 20, 30, 3, 90, 'Les répétitions comptent des pas, charge d''un seul côté, une série par côté. Les épaules restent au même niveau.'),
    ('releve-et-portage', 1, 'rotation-externe-elastique', 6, 3, 15, 20, 3, 45, 'Répétitions par bras. Le coude reste collé au corps.'),
    ('releve-et-portage', 1, 'pull-apart-elastique', 7, 2, 15, 20, 3, 45, null),
    ('releve-et-portage', 1, 'mollets-une-jambe', 8, 3, 15, 20, 3, 45, 'Répétitions par jambe.'),
    ('releve-et-portage', 1, 'gainage-lateral', 9, 2, 20, 30, 3, 45, 'Les répétitions comptent des secondes, une série par côté.'),
    ('releve-et-portage', 1, 'suspension-barre', 10, 2, 20, 30, 3, 45, 'Les répétitions comptent des secondes. Les pieds peuvent rester au sol si la suspension complète tire trop sur les épaules.'),
    ('releve-et-portage', 2, 'turkish-get-up', 1, 2, 3, 3, 4, 180, 'Répétitions par côté. Séance allégée sur le relevé : c''est la charnière qui porte celle-ci.'),
    ('releve-et-portage', 2, 'hip-hinge-baton', 2, 3, 10, 12, 3, 90, 'Le bâton touche l''arrière de la tête, le haut du dos et le sacrum, et ne quitte aucun des trois. C''est la charnière apprise à vide, avant celle qui est chargée.'),
    ('releve-et-portage', 2, 'kettlebell-swing', 3, 3, 10, 12, 3, 120, 'Le mouvement vient des hanches, pas des bras ni des genoux. La cloche ne monte pas plus haut que la poitrine.'),
    ('releve-et-portage', 2, 'fente-arriere', 4, 4, 8, 10, 3, 90, 'Répétitions par jambe. Le pas part vers l''arrière, le genou avant ne dépasse pas la pointe du pied.'),
    ('releve-et-portage', 2, 'tirage-vertical-prise-neutre', 5, 3, 8, 12, 3, 90, 'Prise neutre, paumes face à face : c''est l''angle le plus confortable pour l''épaule.'),
    ('releve-et-portage', 2, 'pompes-inclinees', 6, 3, 10, 15, 3, 90, 'Mains sur un banc ou une caisse. Plus l''appui est haut, plus c''est facile.'),
    ('releve-et-portage', 2, 'y-t-w', 7, 3, 15, 20, 3, 45, 'Charge très légère. Ce sont les omoplates qui travaillent, pas les bras.'),
    ('releve-et-portage', 2, 'mollets-une-jambe', 8, 3, 15, 20, 3, 45, 'Répétitions par jambe.'),
    ('releve-et-portage', 2, 'dead-bug-lest', 9, 3, 6, 10, 3, 90, 'Répétitions par côté. Le bas du dos reste plaqué au sol ; si le contact se perd, la charge est trop lourde.'),
    ('releve-et-portage', 3, 'turkish-get-up', 1, 3, 3, 3, 4, 180, 'Répétitions par côté. Toujours en début de séance, jamais quand l''attention baisse.'),
    ('releve-et-portage', 3, 'front-rack-carry', 2, 2, 20, 30, 3, 90, 'Les répétitions comptent des pas, une série par côté. Les côtes restent basses, on ne cambre pas pour compenser.'),
    ('releve-et-portage', 3, 'farmer-walk', 3, 3, 20, 30, 3, 90, 'Les répétitions comptent des pas. Charge égale des deux côtés, contrairement au port valise.'),
    ('releve-et-portage', 3, 'rowing-inverse', 4, 3, 8, 12, 3, 90, 'Plus le corps est proche de la verticale, plus c''est facile.'),
    ('releve-et-portage', 3, 'pompes', 5, 4, 8, 15, 3, 90, 'Genoux au sol si la série entière ne tient pas au sol complet.'),
    ('releve-et-portage', 3, 'pont-fessier-une-jambe', 6, 3, 10, 12, 3, 90, 'Répétitions par jambe. Le bassin reste de niveau : c''est le côté qui pousse qui monte, pas le dos qui cambre.'),
    ('releve-et-portage', 3, 'curl-nordique-assiste', 7, 3, 6, 10, 3, 90, 'Talons sur une serviette ou des patins, hanches tendues pendant tout le trajet. Descente lente, remontée aidée par les bras si nécessaire.'),
    ('releve-et-portage', 3, 'scaption', 8, 3, 15, 20, 3, 45, 'Charge très légère, bras montés à mi-chemin entre l''avant et le côté, pouces vers le haut. On ne monte pas plus haut que les épaules.'),
    ('releve-et-portage', 3, 'pallof-press', 9, 2, 10, 12, 3, 90, 'Répétitions par côté. Les bras poussent droit devant ; c''est le tronc qui refuse la rotation.'),
    ('poigne-et-charge-asymetrique', 1, 'squat-gobelet', 1, 4, 10, 12, 2, 120, 'La charge se tient devant, contre la poitrine. La prise fatigue avant les jambes : dès que les mains glissent, on repose la charge, la série est finie.'),
    ('poigne-et-charge-asymetrique', 1, 'developpe-halteres-unilateral', 2, 4, 8, 10, 2, 120, 'Répétitions par bras. Monter jusqu''où l''épaule reste libre, pas plus haut.'),
    ('poigne-et-charge-asymetrique', 1, 'rowing-haltere', 3, 4, 10, 12, 2, 120, 'Répétitions par bras. Une main en appui sur le banc, le dos reste plat.'),
    ('poigne-et-charge-asymetrique', 1, 'romanian-une-jambe', 4, 3, 8, 10, 3, 120, 'Répétitions par jambe. Charge légère : ici c''est l''équilibre qui limite, pas les ischio-jambiers. Une main libre peut se poser sur un mur.'),
    ('poigne-et-charge-asymetrique', 1, 'face-pull', 5, 3, 12, 15, 3, 90, 'Coudes hauts, mouvement lent. Contrepoids de tout ce que la séance pousse et porte devant.'),
    ('poigne-et-charge-asymetrique', 1, 'curl-marteau', 6, 3, 10, 12, 2, 90, 'Prise neutre, poignet dans l''axe de l''avant-bras.'),
    ('poigne-et-charge-asymetrique', 1, 'mollets-une-jambe', 7, 3, 12, 15, 2, 90, 'Répétitions par jambe. Amplitude complète, sans rebond en bas.'),
    ('poigne-et-charge-asymetrique', 1, 'pallof-press', 8, 3, 8, 10, 3, 90, 'Répétitions par côté. Rien ne bouge sauf les bras.'),
    ('poigne-et-charge-asymetrique', 1, 'extension-poignet', 9, 2, 12, 15, 3, 90, 'Amplitude courte, charge légère, avant-bras posé. Le poignet se renforce en semaines, pas en séances.'),
    ('poigne-et-charge-asymetrique', 1, 'front-rack-carry', 10, 3, 20, 30, 3, 90, 'Les chiffres sont des secondes de marche. On repose la charge au sol quand le buste s''affaisse ou que les coudes tombent — pas quand le compte est atteint.'),
    ('poigne-et-charge-asymetrique', 2, 'presse-une-jambe', 1, 4, 10, 12, 2, 120, 'Répétitions par jambe. Le genou suit la pointe du pied.'),
    ('poigne-et-charge-asymetrique', 2, 'suspension-barre', 2, 3, 10, 20, 3, 90, 'Les chiffres sont des secondes. Barre assez basse pour poser les pieds sans sauter. On redescend pendant que la prise tient encore : si les doigts commencent à glisser, la série s''arrête là, avant le compte. Placée tôt dans la séance, prise fraîche, avant les ports.'),
    ('poigne-et-charge-asymetrique', 2, 'tirage-unilateral-poulie', 3, 4, 10, 12, 2, 120, 'Répétitions par bras. L''épaule descend avant que le coude ne plie.'),
    ('poigne-et-charge-asymetrique', 2, 'leg-curl-assis', 4, 3, 10, 12, 2, 90, 'Retour lent, plus lent que l''aller.'),
    ('poigne-et-charge-asymetrique', 2, 'hip-thrust-une-jambe', 5, 3, 12, 15, 2, 90, 'Répétitions par jambe. Menton rentré, on monte par la hanche et pas par le bas du dos.'),
    ('poigne-et-charge-asymetrique', 2, 'elevation-laterale', 6, 3, 12, 15, 2, 90, 'Charge légère, montée jusqu''à l''horizontale, pas plus haut.'),
    ('poigne-et-charge-asymetrique', 2, 'y-t-w', 7, 3, 12, 15, 3, 90, 'Presque rien dans les mains : ces trois positions se travaillent au poids des bras ou avec la plus petite charge de la salle.'),
    ('poigne-et-charge-asymetrique', 2, 'curl-concentre', 8, 3, 10, 12, 2, 90, 'Répétitions par bras. Coude calé contre la cuisse.'),
    ('poigne-et-charge-asymetrique', 2, 'mollets-assis', 9, 3, 12, 15, 2, 90, 'Temps d''arrêt en haut, descente contrôlée.'),
    ('poigne-et-charge-asymetrique', 2, 'farmer-walk', 10, 3, 20, 30, 3, 90, 'Secondes de marche. Charge égale des deux côtés, épaules basses. On repose au sol dès que la posture se dégrade ou que les doigts s''ouvrent.'),
    ('poigne-et-charge-asymetrique', 2, 'suitcase-carry', 11, 3, 20, 30, 3, 90, 'Secondes de marche, par côté. Une seule charge, à une main : l''intérêt est de ne pas se laisser incliner. On repose au sol dès qu''on penche.'),
    ('poids-de-corps-densite', 1, 'step-down', 1, 4, 8, 10, 2, 90, 'Répétitions par jambe. La descente est lente : c''est elle qui compte, pas la remontée. Marche basse pour commencer, on ne monte de hauteur que quand les dix répétitions passent sans à-coup.'),
    ('poids-de-corps-densite', 1, 'pompes', 2, 4, 8, 15, 2, 90, 'Corps en ligne des talons à la tête. Si la forme se casse avant le bas de la fourchette, posez les genoux et gardez la même ligne.'),
    ('poids-de-corps-densite', 1, 'hip-thrust-une-jambe', 3, 3, 10, 12, 2, 90, 'Répétitions par jambe.'),
    ('poids-de-corps-densite', 1, 'pompes-diamant', 4, 4, 6, 10, 2, 90, 'Coudes le long du corps. Si l''épaule tire, revenez aux pompes classiques pour cette série.'),
    ('poids-de-corps-densite', 1, 'rowing-inverse', 5, 3, 8, 12, 2, 90, 'Barre basse, table solide ou plan de travail. Plus le corps est redressé, plus c''est facile : c''est là qu''on règle la difficulté.'),
    ('poids-de-corps-densite', 1, 'hip-hinge-baton', 6, 4, 10, 12, 3, 90, 'Un bâton, un manche à balai ou une règle le long du dos : il doit toucher l''arrière de la tête, le haut du dos et le bas du dos du début à la fin. Le mouvement part des hanches. Si un contact se perd, descendez moins bas.'),
    ('poids-de-corps-densite', 1, 'mollets-une-jambe', 7, 4, 12, 15, 2, 90, 'Répétitions par jambe.'),
    ('poids-de-corps-densite', 1, 'wall-slide', 8, 3, 10, 12, 3, 90, 'Dos, avant-bras et poignets contre le mur, on remonte les bras sans les décoller. Dès qu''un poignet quitte le mur, on est allé trop haut.'),
    ('poids-de-corps-densite', 1, 'hollow-hold', 9, 3, 20, 30, 3, 60, 'Les répétitions comptent des secondes de maintien. Le bas du dos reste plaqué au sol : dès qu''il décolle, la série est finie.'),
    ('poids-de-corps-densite', 1, 'cat-cow', 10, 2, 8, 10, 3, 60, 'Sans forcer, en respirant. C''est une fin de séance, pas un exercice de force.'),
    ('poids-de-corps-densite', 2, 'rowing-inverse-eleve', 1, 4, 6, 10, 2, 120, 'Pieds surélevés. Si la série ne passe pas, reposez les pieds au sol : c''est le même exercice en plus facile.'),
    ('poids-de-corps-densite', 2, 'curl-nordique-assiste', 2, 3, 6, 8, 3, 120, 'Genoux calés sur quelque chose de doux, pieds bloqués. On descend en retenant le plus longtemps possible, et on s''aide des mains pour remonter : la remontée ne compte pas. Allez doucement, c''est l''exercice du programme qui laisse le plus de courbatures les premières semaines.'),
    ('poids-de-corps-densite', 2, 'scapular-pull-up', 3, 4, 8, 10, 3, 90, 'Les bras restent tendus : seules les omoplates travaillent.'),
    ('poids-de-corps-densite', 2, 'pompes-inclinees', 4, 3, 12, 15, 2, 90, 'Mains sur un appui haut. Plus l''appui est bas, plus c''est difficile.'),
    ('poids-de-corps-densite', 2, 'pont-fessier-une-jambe', 5, 3, 10, 12, 2, 90, 'Répétitions par jambe.'),
    ('poids-de-corps-densite', 2, 'pompes-diamant', 6, 3, 10, 12, 2, 90, 'Deuxième passage de la semaine : la fourchette monte, la réserve reste la même.'),
    ('poids-de-corps-densite', 2, 'wall-sit', 7, 3, 30, 45, 3, 90, 'Les répétitions comptent des secondes de maintien. Dos plat contre le mur, cuisses vers l''horizontale.'),
    ('poids-de-corps-densite', 2, 'extension-lombaire', 8, 3, 10, 12, 3, 90, 'Au sol, à plat ventre. On décolle le buste de quelques centimètres seulement, sans à-coup, et on redescend. Ce n''est pas une cambrure maximale.'),
    ('poids-de-corps-densite', 2, 'gainage-lateral', 9, 3, 20, 30, 3, 45, 'Secondes de maintien, par côté.'),
    ('poids-de-corps-densite', 2, 'bird-dog', 10, 3, 8, 10, 3, 60, 'Répétitions par côté. Le bassin ne bascule pas.'),
    ('poids-de-corps-densite', 3, 'step-down', 1, 3, 12, 15, 2, 90, 'Répétitions par jambe. Même descente lente qu''à la première séance : plus de répétitions, pas moins de contrôle. Le repos reste long ici.'),
    ('poids-de-corps-densite', 3, 'pompes-diamant', 2, 3, 12, 15, 2, 90, 'Le repos reste à 90 secondes : c''est le mouvement le plus exigeant pour le coude, on ne le raccourcit pas.'),
    ('poids-de-corps-densite', 3, 'scapular-pull-up', 3, 3, 10, 12, 3, 90, 'Les bras restent tendus.'),
    ('poids-de-corps-densite', 3, 'hip-hinge-baton', 4, 3, 12, 15, 3, 90, 'Le bâton garde ses trois points de contact. Si un contact se perd, la série est finie.'),
    ('poids-de-corps-densite', 3, 'pompes', 5, 3, 15, 20, 2, 60, 'Séries plus longues, repos plus courts. Si la forme se dégrade, allongez le repos plutôt que d''écourter la série.'),
    ('poids-de-corps-densite', 3, 'rowing-inverse', 6, 3, 15, 20, 2, 60, 'Redressez-vous un peu si le haut de la fourchette ne passe pas.'),
    ('poids-de-corps-densite', 3, 'pont-fessier', 7, 3, 15, 20, 2, 60, 'Les deux pieds au sol. On monte, on tient une seconde en haut, on redescend sans poser complètement le bassin.'),
    ('poids-de-corps-densite', 3, 'mollets-une-jambe', 8, 3, 15, 20, 2, 60, 'Répétitions par jambe.'),
    ('poids-de-corps-densite', 3, 'mountain-climber', 9, 3, 20, 30, 3, 45, 'Répétitions par jambe. Le bassin ne monte pas, et on n''accélère pas.'),
    ('poids-de-corps-densite', 3, 'marche-pointes', 10, 3, 30, 40, 3, 45, 'Secondes de marche sur la pointe des pieds, sans poser les talons.'),
    ('poids-de-corps-densite', 3, 'bear-crawl', 11, 2, 30, 40, 3, 60, 'Secondes de déplacement. Genoux à quelques centimètres du sol, bassin bas.'),
    ('poids-de-corps-densite', 3, 'gainage-ventral', 12, 3, 30, 45, 3, 60, 'Les répétitions comptent des secondes de maintien. Dès que le bas du dos s''affaisse, la série est finie, même s''il reste du temps.'),
    ('poids-de-corps-densite', 3, 'rotation-thoracique', 13, 2, 8, 10, 3, 60, 'Répétitions par côté. Mobilité, pas force : c''est une fin de séance.'),
    ('enchainements-au-sol', 1, 'cat-cow', 1, 2, 8, 10, 3, 30, 'En respirant : l''expiration accompagne l''arrondi.'),
    ('enchainements-au-sol', 1, 'rotation-thoracique', 2, 2, 8, 10, 3, 30, 'Répétitions par côté.'),
    ('enchainements-au-sol', 1, 'bear-crawl', 3, 3, 20, 30, 3, 60, 'Secondes de déplacement. Genoux à quelques centimètres du sol, bassin bas. Vingt secondes suffisent aux premières séances : c''est ce qui charge le plus les poignets.'),
    ('enchainements-au-sol', 1, 'hip-hinge-baton', 4, 2, 10, 12, 3, 60, 'Le bâton touche la tête, le haut du dos et le sacrum, et ne les quitte pas.'),
    ('enchainements-au-sol', 1, 'rowing-inverse', 5, 3, 8, 12, 3, 90, 'Un bord de table basse ou une barre basse suffit. Plus le corps est proche de l''horizontale, plus c''est difficile : commencez buste haut.'),
    ('enchainements-au-sol', 1, 'pompes-inclinees', 6, 3, 8, 12, 3, 90, 'Mains sur un appui haut, jamais au sol : les poignets travaillent déjà beaucoup ici.'),
    ('enchainements-au-sol', 1, 'planche-alternee', 7, 2, 8, 10, 3, 45, 'Répétitions par bras. Le bassin ne tourne pas.'),
    ('enchainements-au-sol', 1, 'gainage-lateral-genoux', 8, 2, 20, 30, 3, 45, 'Secondes de maintien, par côté. Genoux fléchis, appui sur l''avant-bras : rien ne passe par le poignet.'),
    ('enchainements-au-sol', 1, 'pont-fessier', 9, 3, 12, 15, 3, 90, 'On monte jusqu''à l''alignement, pas au-delà.'),
    ('enchainements-au-sol', 2, 'cat-cow', 1, 2, 8, 10, 3, 30, 'Même ouverture qu''à la première séance.'),
    ('enchainements-au-sol', 2, 'rotation-thoracique', 2, 2, 8, 10, 3, 30, 'Répétitions par côté.'),
    ('enchainements-au-sol', 2, 'hip-hinge-baton', 3, 2, 10, 12, 3, 60, 'Les trois points de contact d''abord, l''amplitude ensuite.'),
    ('enchainements-au-sol', 2, 'mountain-climber', 4, 2, 12, 15, 3, 45, 'Répétitions par jambe, sans accélérer. C''est un déplacement, pas un sprint.'),
    ('enchainements-au-sol', 2, 'rowing-inverse', 5, 3, 8, 12, 3, 90, 'Même réglage qu''à la première séance.'),
    ('enchainements-au-sol', 2, 'pompes-inclinees', 6, 3, 8, 12, 3, 90, 'Mains surélevées, comme à la première séance.'),
    ('enchainements-au-sol', 2, 'dead-bug', 7, 2, 8, 10, 3, 45, 'Répétitions par côté. Le bas du dos reste au contact du sol.'),
    ('enchainements-au-sol', 2, 'crunch-inverse', 8, 2, 10, 12, 3, 45, 'Les genoux montent vers la poitrine sans élan.'),
    ('enchainements-au-sol', 2, 'hip-airplane', 9, 2, 6, 8, 3, 45, 'Répétitions par jambe. Se tenir à un appui au début.'),
    ('enchainements-au-sol', 2, 'pont-fessier', 10, 2, 12, 15, 3, 90, 'On monte jusqu''à l''alignement, pas au-delà.'),
    ('nuque-et-ceinture-scapulaire', 1, 'retraction-cervicale', 1, 2, 8, 10, 4, 90, 'Amplitude petite, sans forcer. Le menton recule de deux ou trois centimètres et on tient trois à cinq secondes.'),
    ('nuque-et-ceinture-scapulaire', 1, 'wall-slide', 2, 2, 8, 10, 3, 90, 'Avant-bras collés au mur du début à la fin. Si le contact se perd, c''est que vous êtes monté trop haut.'),
    ('nuque-et-ceinture-scapulaire', 1, 'face-pull-elastique', 3, 3, 12, 15, 3, 90, 'Élastique fin, ancré à hauteur de visage, coudes hauts. L''élastique vient vers le visage, pas vers la poitrine.'),
    ('nuque-et-ceinture-scapulaire', 1, 'rowing-elastique', 4, 3, 10, 12, 3, 120, 'Assis ou debout, élastique ancré devant soi. Le buste reste droit, on ne se balance pas d''avant en arrière.'),
    ('nuque-et-ceinture-scapulaire', 1, 'rotation-externe-elastique', 5, 2, 12, 15, 3, 90, 'Répétitions par bras. Coude au corps, élastique léger.'),
    ('nuque-et-ceinture-scapulaire', 1, 'bird-dog', 6, 2, 8, 10, 3, 90, 'Répétitions par côté. La nuque suit le dos, elle ne se relève pas.'),
    ('nuque-et-ceinture-scapulaire', 1, 'gainage-ventral', 7, 3, 20, 30, 3, 60, 'Secondes de maintien. La tête reste dans le prolongement du dos, le regard au sol.'),
    ('nuque-et-ceinture-scapulaire', 2, 'retraction-cervicale', 1, 2, 8, 10, 4, 90, 'Même consigne : petit, lent, sans douleur.'),
    ('nuque-et-ceinture-scapulaire', 2, 'retraction-scapulaire', 2, 2, 10, 12, 3, 90, 'Les bras ne tirent pas : ce sont les omoplates qui se rapprochent.'),
    ('nuque-et-ceinture-scapulaire', 2, 'rowing-haltere', 3, 3, 10, 12, 3, 120, 'Répétitions par bras. Une main et un genou sur la chaise ou le banc, le dos à l''horizontale, la tête dans son prolongement.'),
    ('nuque-et-ceinture-scapulaire', 2, 'scaption', 4, 2, 10, 12, 3, 90, 'Les bras montent à mi-chemin entre l''avant et le côté, pouces vers le haut, sans dépasser la hauteur d''épaule.'),
    ('nuque-et-ceinture-scapulaire', 2, 'serratus-punch', 5, 2, 10, 12, 3, 90, 'Répétitions par bras. L''épaule avance en fin de mouvement, le coude reste tendu.'),
    ('nuque-et-ceinture-scapulaire', 2, 'y-t-w', 6, 2, 8, 10, 3, 90, 'Haltères très légers, ou rien du tout. Les trois lettres à la suite font une répétition.'),
    ('nuque-et-ceinture-scapulaire', 2, 'bird-dog', 7, 2, 8, 10, 3, 90, 'Répétitions par côté. Le bassin ne bascule pas quand la jambe part en arrière.'),
    ('nuque-et-ceinture-scapulaire', 2, 'suitcase-carry', 8, 2, 20, 30, 3, 60, 'Secondes de marche, par côté. Épaule basse, on ne s''incline pas.'),
    ('kettlebell-deux-mouvements', 1, 'cat-cow', 1, 2, 8, 10, 4, 30, 'Réveil du bas du dos avant de le charger. Bougez au rythme de la respiration, sans chercher l''amplitude maximale.'),
    ('kettlebell-deux-mouvements', 1, 'hip-hinge-baton', 2, 3, 8, 10, 4, 45, 'Le bâton touche l''arrière de la tête, le haut du dos et le sacrum en même temps, du départ à l''arrivée. Si un contact se perd, c''est que le dos plie au lieu de la hanche — et c''est exactement ce que le swing va amplifier.'),
    ('kettlebell-deux-mouvements', 1, 'kettlebell-swing', 3, 5, 10, 15, 4, 90, 'Le swing est un coup de hanche, pas un mouvement d''épaule : la kettlebell monte parce que le bassin se redresse. Arrêtez la série dès que la trajectoire descend plus bas que le nombril ou que le dos s''arrondit, même s''il reste des répétitions au compteur.'),
    ('kettlebell-deux-mouvements', 1, 'dead-bug', 4, 3, 8, 10, 4, 60, 'Contrepoids du swing : ici le ventre travaille à empêcher le dos de se creuser. Le bas du dos reste plaqué au sol du début à la fin, c''est le seul critère.'),
    ('kettlebell-deux-mouvements', 2, 'wall-slide', 1, 3, 8, 10, 4, 45, 'Prépare l''omoplate à porter une charge bras tendu. Les avant-bras et les poignets restent en contact avec le mur ; s''ils décollent, montez moins haut.'),
    ('kettlebell-deux-mouvements', 2, 'turkish-get-up', 2, 5, 1, 2, 4, 120, 'Une répétition par côté et par série, en marquant une seconde d''arrêt à chaque étape. Ce n''est pas un exercice de force mais de contrôle : la charge se choisit sur la position la plus fragile de l''enchaînement, jamais sur la plus forte. Les premières semaines, l''enchaînement à vide ou avec une bouteille en équilibre sur le poing apprend davantage qu''une kettlebell.'),
    ('kettlebell-deux-mouvements', 2, 'rowing-haltere', 3, 3, 8, 12, 3, 90, 'La kettlebell dans une main, l''autre main en appui sur un banc ou sur la cuisse. Le coude longe le corps et l''omoplate part vers la colonne : c''est le dos qui tire, pas le bras, et le bassin ne pivote pas pour aller chercher la répétition. C''est le seul exercice du programme où l''on peut approcher un peu plus l''effort — il n''est ni balistique, ni au-dessus de la tête.'),
    ('kettlebell-hardstyle', 1, 'hip-hinge-baton', 1, 2, 8, 10, 4, 45, 'Mise en place, pas encore de l''entraînement : le bâton touche l''arrière de la tête, le haut du dos et le sacrum, et ces trois points ne se décollent pas pendant que les hanches reculent. C''est le repère que vous chercherez pendant les swings.'),
    ('kettlebell-hardstyle', 1, 'wall-slide', 2, 2, 8, 10, 4, 45, 'Ouvre l''épaule avant de la charger au-dessus de la tête. Les avant-bras restent au contact du mur ; si les côtes se soulèvent pour gagner de la hauteur, arrêtez la montée là.'),
    ('kettlebell-hardstyle', 1, 'press-kettlebell', 3, 4, 5, 6, 3, 180, 'Le développé hardstyle se fait sous tension : on serre la poignée, la sangle abdominale et le fessier du côté opposé avant de pousser. Si le buste doit s''incliner sur le côté ou le bras dévier devant la tête pour que la charge passe, elle est trop lourde.'),
    ('kettlebell-hardstyle', 1, 'kettlebell-swing', 4, 3, 10, 12, 3, 120, 'Trois séries, pas davantage : le swing revient à chaque séance et c''est le total de la semaine qui compte, pas celui du jour. Ici il se fait sur des jambes fraîches, après le développé. Arrêtez la série sur le premier arrondi de dos, pas sur le premier essoufflement.'),
    ('kettlebell-hardstyle', 1, 'goblet-squat-kettlebell', 5, 3, 6, 8, 3, 150, 'La kettlebell tenue contre la poitrine sert de contrepoids : elle vous permet de descendre buste droit sans que le bas du dos ne compense. Descendez seulement jusqu''à la profondeur où le dos reste plat, et pas un centimètre de plus.'),
    ('kettlebell-hardstyle', 1, 'rowing-haltere', 6, 3, 8, 10, 3, 90, 'Le tirage du programme, et un ajout assumé : le répertoire d''origine n''en contient aucun. Une kettlebell fait aussi bien l''affaire qu''un haltère. Tirez le coude vers la hanche plutôt que vers l''épaule, et gardez le buste immobile — s''il se redresse pour accompagner, la charge est trop lourde.'),
    ('kettlebell-hardstyle', 1, 'face-pull-elastique', 7, 3, 12, 15, 3, 90, 'Contrepoids du travail au-dessus de la tête : l''arrière de l''épaule et le milieu du dos, qui ne travaillent nulle part ailleurs dans une séance kettlebell. Ajout hors répertoire, lui aussi, et il revient aux deux séances.'),
    ('kettlebell-hardstyle', 1, 'front-rack-carry', 8, 2, 20, 30, 4, 90, 'Comptez un pas par répétition. La kettlebell posée sur l''avant-bras, le coude serré contre les côtes ; la marche reste silencieuse et le buste droit. Posez la kettlebell dès que le coude s''écarte des côtes, même s''il reste des pas à faire.'),
    ('kettlebell-hardstyle', 2, 'hip-hinge-baton', 1, 2, 8, 10, 4, 45, 'Même mise en place qu''au jour A. Les swings arrivent plus loin dans la séance : le repère de dos plat se prend à froid, jamais en pleine série.'),
    ('kettlebell-hardstyle', 2, 'wall-slide', 2, 2, 8, 10, 4, 45, 'Le get-up finit bras tendu au-dessus de la tête : l''épaule s''ouvre avant, pas pendant. Les avant-bras restent au mur.'),
    ('kettlebell-hardstyle', 2, 'turkish-get-up', 3, 4, 1, 2, 4, 120, 'Une répétition par côté et par série, avec un temps d''arrêt à chaque étape. Le regard reste sur la kettlebell tant qu''elle est basse ; la charge se choisit sur l''étape la plus fragile, pas sur la plus facile.'),
    ('kettlebell-hardstyle', 2, 'kettlebell-swing', 4, 3, 10, 12, 3, 120, 'Mêmes trois séries qu''au jour A : la kettlebell monte parce que le bassin se redresse, jamais parce que les bras tirent. Neuf séries de swing sur une semaine de trois séances, c''est le compte, et il tient déjà compte du squat gobelet qui charge la même hanche.'),
    ('kettlebell-hardstyle', 2, 'goblet-squat-kettlebell', 5, 3, 8, 10, 3, 150, 'Deux répétitions de plus qu''au jour A, avec une charge un peu plus légère : même mouvement, autre intention. Là encore, la profondeur s''arrête où le dos cesse d''être plat.'),
    ('kettlebell-hardstyle', 2, 'rowing-haltere', 6, 3, 10, 12, 3, 90, 'Le tirage revient à chaque séance, un peu plus léger ici qu''au jour A. Coude vers la hanche, buste immobile.'),
    ('kettlebell-hardstyle', 2, 'face-pull-elastique', 7, 3, 12, 15, 3, 90, 'En fin de séance, sans charge à chercher : c''est la tenue une seconde en fin de mouvement qui compte, pas la tension de l''élastique.'),
    ('kettlebell-efforts-brefs', 1, 'hip-hinge-baton', 1, 2, 8, 10, 3, 45, 'Deux séries pour retrouver la charnière avant de faire le geste chargé. Le bâton reste en contact avec la tête, le haut du dos et le sacrum.'),
    ('kettlebell-efforts-brefs', 1, 'kettlebell-swing', 2, 6, 6, 8, 3, 90, 'Six séries, pas davantage : chacune dure une dizaine de secondes et se termine loin de l''essoufflement. Le régulateur n''est pas la fatigue mais la vitesse — dès qu''une répétition monte moins haut ou moins vite que la première, la séance est finie, même s''il reste des séries au programme.'),
    ('kettlebell-efforts-brefs', 1, 'pompes', 3, 6, 6, 8, 3, 90, 'Alternez une série de swings et une série de pompes : six de chaque, le compte tombe juste et aucune série ne reste orpheline. Le repos indiqué s''applique entre chaque série, quel que soit le mouvement. Poussez vite, redescendez posément. Mains sur un banc si la position au sol casse l''alignement du bassin.'),
    ('kettlebell-efforts-brefs', 1, 'mcgill-curl-up', 4, 3, 8, 10, 3, 90, 'Une seule main sous le creux du dos, l''autre par-dessus : c''est elle qui vous dit si le bas du dos bouge. Seuls la tête et les épaules décollent, et le mouvement reste lent.'),
    ('kettlebell-efforts-brefs', 1, 'cat-cow', 5, 1, 8, 10, 3, 0, 'Fin de séance : on rend au dos la mobilité qu''une série de charnières a mise sous tension. Lentement, au rythme de la respiration.'),
    ('kettlebell-efforts-brefs', 2, 'hip-hinge-baton', 1, 2, 8, 10, 3, 45, 'Même préparation qu''au jour 1 : le bâton reste en contact avec la tête, le haut du dos et le sacrum.'),
    ('kettlebell-efforts-brefs', 2, 'kettlebell-swing', 2, 6, 6, 8, 3, 90, 'Même consigne qu''au jour 1 : six séries, très courtes, très vives, et l''on s''arrête sur la première répétition moins haute.'),
    ('kettlebell-efforts-brefs', 2, 'pompes', 3, 4, 6, 8, 3, 90, 'Ici, pas d''alternance : les quatre séries viennent après le bloc de swings, avec le même repos entre chacune. Même consigne de vitesse à la montée.'),
    ('kettlebell-efforts-brefs', 2, 'front-rack-carry', 4, 4, 20, 30, 3, 90, 'Comptez un pas par répétition, coude serré contre les côtes. Après des séries explosives, le tronc travaille ici à tenir la position plutôt qu''à produire de la force.'),
    ('kettlebell-efforts-brefs', 2, 'dead-bug', 5, 3, 8, 10, 3, 90, 'Le bas du dos reste plaqué au sol du début à la fin. C''est le contrepoids exact d''une séance passée à redresser le bassin.'),
    ('kettlebell-efforts-brefs', 2, 'cat-cow', 6, 1, 8, 10, 3, 0, 'Pour finir, sans forcer l''amplitude.'),
    ('gainage-sans-poussee', 1, 'cat-cow', 1, 2, 8, 10, 4, 90, 'Mise en route. Soufflez quand le dos s''arrondit, inspirez quand il se creuse — c''est le rythme que garde toute la séance.'),
    ('gainage-sans-poussee', 1, 'hip-hinge-baton', 2, 2, 8, 10, 4, 90, 'Un bâton le long du dos, trois points de contact conservés du début à la fin. C''est le repère qui rend toutes les charnières de hanche sûres, y compris celles d''un autre programme.'),
    ('gainage-sans-poussee', 1, 'dead-bug', 3, 2, 8, 10, 4, 90, 'Répétitions par côté. Soufflez pendant que la jambe s''éloigne. Le ventre ne se bombe pas vers l''avant ; s''il le fait, la jambe s''éloigne moins.'),
    ('gainage-sans-poussee', 1, 'bird-dog', 4, 3, 8, 10, 4, 90, 'Répétitions par côté. Le bassin reste à plat, la respiration ne s''interrompt pas pendant le maintien.'),
    ('gainage-sans-poussee', 1, 'pallof-press', 5, 2, 10, 12, 4, 90, 'Répétitions par côté. Soufflez en poussant les bras. Charge légère : le but est de ne pas tourner, pas de pousser fort.'),
    ('gainage-sans-poussee', 1, 'pont-fessier', 6, 3, 12, 15, 4, 90, 'Montez sans creuser le bas du dos : ce sont les fessiers qui soulèvent le bassin, pas la colonne qui se cambre.'),
    ('gainage-sans-poussee', 1, 'gainage-ventral', 7, 2, 20, 30, 4, 60, 'Les répétitions comptent des secondes de maintien. On respire pendant : bloquer le souffle est exactement ce que cette séance cherche à éviter. Reposez les genoux dès que la respiration se tend, sans attendre la fin du compte.'),
    ('gainage-sans-poussee', 1, 'gainage-lateral-genoux', 8, 2, 20, 30, 4, 60, 'Les répétitions comptent des secondes, par côté. C''est ce maintien qui remplace un port de charge d''un seul côté : même travail contre l''inclinaison, sans poids à porter. Version à genoux d''abord ; on passe aux jambes tendues quand celle-ci se fait en respirant normalement.'),
    ('controle-du-centre', 1, 'cat-cow', 1, 2, 8, 10, 4, 90, 'Échauffement du dos, segment par segment. On ne cherche aucune amplitude maximale : le mouvement s''arrête là où il reste facile.'),
    ('controle-du-centre', 1, 'dead-bug', 2, 2, 8, 10, 3, 90, 'Répétitions par côté. Le bas du dos reste en contact avec le sol : c''est ce contact qui définit l''amplitude, pas la longueur de votre jambe.'),
    ('controle-du-centre', 1, 'bird-dog', 3, 3, 8, 10, 3, 90, 'Répétitions par côté. Le bassin ne bascule pas quand la jambe se tend ; si vous le sentez partir, la jambe monte moins haut.'),
    ('controle-du-centre', 1, 'pont-fessier', 4, 3, 10, 12, 3, 90, 'Montez vertèbre par vertèbre et redescendez de même. La lenteur est le travail, pas un ralentissement du travail.'),
    ('controle-du-centre', 1, 'fire-hydrant', 5, 2, 12, 15, 3, 90, 'Répétitions par côté, à quatre pattes. Le bassin ne roule pas sur le côté : seul le genou s''ouvre, et il s''arrête avant que le dos ne suive.'),
    ('controle-du-centre', 1, 'wall-slide', 6, 3, 10, 12, 3, 90, 'Le bas du dos reste plaqué au mur pendant toute la montée. Si le dos décolle, la montée s''arrête là.'),
    ('controle-du-centre', 1, 'retraction-cervicale', 7, 2, 10, 12, 4, 90, 'Le menton recule à l''horizontale, sans lever ni baisser le regard. Le mouvement est très court : c''est normal, il n''y a rien à forcer.'),
    ('controle-du-centre', 1, 'planche-alternee', 8, 2, 8, 10, 3, 90, 'Une répétition = une main qui quitte le sol, en alternant. Bras tendus, poussez le sol pour éloigner les omoplates du dos. Les hanches ne tournent pas : écartez les pieds pour vous stabiliser, et si elles tournent quand même, la main se lève moins haut.'),
    ('controle-du-centre', 1, 'mollets-une-jambe', 9, 3, 10, 12, 3, 90, 'Répétitions par jambe, une main posée au mur pour l''équilibre et non pour vous porter. Montée lente, descente plus lente encore, sans rebond en bas.'),
    ('controle-du-centre', 1, 'gainage-lateral-genoux', 10, 2, 20, 30, 3, 60, 'Les répétitions comptent des secondes, par côté. On tient sur les genoux : le bassin monte et reste haut, et la série s''arrête quand il redescend — pas quand le compte est atteint.'),
    ('controle-du-centre', 1, 'equilibre-unipodal', 11, 2, 20, 30, 4, 60, 'Les répétitions comptent des secondes, par jambe. Placez-vous à portée d''un mur ou d''un dossier, sans vous y tenir tant que ce n''est pas nécessaire. La durée est volontairement courte : on s''arrête avant que l''équilibre se dégrade, pas après.'),
    ('amplitude-active', 1, 'retraction-cervicale', 1, 2, 10, 12, 4, 30, 'Le menton recule à l''horizontale, sans lever ni baisser la tête. Aucun à-coup, aucune force.'),
    ('amplitude-active', 1, 'cat-cow', 2, 2, 8, 10, 4, 30, 'On cherche à sentir chaque segment bouger séparément, pas à atteindre une amplitude.'),
    ('amplitude-active', 1, 'rotation-thoracique', 3, 2, 8, 10, 4, 30, 'Répétitions par côté. La rotation vient du haut du dos ; le bassin reste immobile.'),
    ('amplitude-active', 1, 'scaption', 4, 2, 12, 15, 3, 60, 'Charge très légère. Les bras montent à mi-chemin entre l''avant et le côté, dans le plan où l''épaule est le plus à l''aise.'),
    ('amplitude-active', 1, 'rotation-externe-elastique', 5, 2, 12, 15, 3, 60, 'Répétitions par côté. Le coude reste au corps ; c''est l''avant-bras qui tourne, pas l''épaule qui s''écarte.'),
    ('amplitude-active', 1, 'y-t-w', 6, 2, 8, 10, 3, 60, 'Sans charge ou presque. Trois positions enchaînées, le cou reste long et les épaules basses.'),
    ('amplitude-active', 1, 'hip-airplane', 7, 2, 6, 8, 3, 60, 'Répétitions par côté. Tenez un appui de la main : l''exercice mesure le contrôle de la hanche, pas l''équilibre.'),
    ('amplitude-active', 1, 'clamshell', 8, 2, 12, 15, 3, 45, 'Répétitions par côté. Ouverture lente, fermeture aussi lente — la descente compte autant que la montée.'),
    ('amplitude-active', 1, 'terminal-knee-extension', 9, 3, 12, 15, 3, 45, 'Répétitions par côté. Le genou finit tendu sans se verrouiller sèchement.'),
    ('amplitude-active', 1, 'dorsiflexion-cheville', 10, 3, 12, 15, 3, 45, 'Répétitions par côté. Les orteils remontent vers le tibia, le talon ne décolle pas.'),
    ('amplitude-active', 1, 'pronation-supination', 11, 2, 12, 15, 4, 45, 'Répétitions par côté. Un haltère léger tenu par une extrémité suffit ; le coude reste plié et immobile.'),
    ('methode-naturelle', 1, 'squat-gobelet', 1, 4, 10, 15, 3, 120, 'Charge modérée tenue contre la poitrine, descente lente, talons au sol. Ce qui compte est l''appui, pas le poids.'),
    ('methode-naturelle', 1, 'pompes', 2, 4, 8, 15, 3, 120, 'Mains sous les épaules, corps d''un bloc. Mains sur un banc ou contre un mur si le bassin s''affaisse : c''est la même série, à une pente qui te laisse finir propre.'),
    ('methode-naturelle', 1, 'traction-neutre', 3, 3, 3, 6, 3, 180, 'Trois à six répétitions franches. Tant qu''elles ne viennent pas, la traction scapulaire et le rowing inversé des plateaux 2 et 3 font le travail — ils sont déjà au programme.'),
    ('methode-naturelle', 1, 'hip-hinge-baton', 4, 4, 10, 12, 4, 90, 'Trois points de contact avec le bâton : nuque, milieu du dos, bassin. Le mouvement part des hanches. C''est la charnière que tu réutilises partout ensuite.'),
    ('methode-naturelle', 1, 'pont-fessier-une-jambe', 5, 3, 8, 12, 3, 90, 'Par jambe. Bassin de niveau, montée jusqu''à l''alignement cuisse-tronc, sans chercher plus haut.'),
    ('methode-naturelle', 1, 'farmer-walk', 6, 4, 1, null, 3, 90, 'Un trajet de 20 à 30 pas compte pour une répétition. Charges le long du corps, épaules basses ; on repose au sol dès que le buste s''affaisse.'),
    ('methode-naturelle', 1, 'bear-crawl', 7, 3, 1, null, 3, 90, 'Un aller de 10 à 15 mètres compte pour une répétition. Bassin bas, genoux à quelques centimètres du sol, petits pas.'),
    ('methode-naturelle', 1, 'scaption', 8, 3, 15, 20, 3, 60, 'Bras montés à mi-chemin entre l''avant et le côté, pouces vers le haut, jusqu''à hauteur d''épaule et pas plus. Charge légère : c''est la série longue qui fait le travail.'),
    ('methode-naturelle', 1, 'gainage-lateral', 9, 2, 1, null, 4, 60, 'Une tenue de 20 à 40 secondes par côté compte pour une répétition. Coupe la tenue dès que le bassin descend, sans chercher à finir le chrono.'),
    ('methode-naturelle', 1, 'marche-pointes', 10, 3, 1, null, 4, 45, '20 à 30 pas sur la pointe des pieds, un aller compte pour une répétition.'),
    ('methode-naturelle', 2, 'fente-statique', 1, 4, 8, 12, 3, 120, 'Par jambe. Genou arrière qui descend à la verticale, buste droit, pieds sur deux rails et non sur une ligne.'),
    ('methode-naturelle', 2, 'rowing-inverse', 2, 4, 8, 12, 3, 120, 'Plus les pieds sont loin, plus c''est dur. Recule-les d''un pas quand le haut de la fourchette devient facile.'),
    ('methode-naturelle', 2, 'pompes-inclinees', 3, 4, 10, 15, 3, 90, 'Mains sur un banc, une table ou un appui de fenêtre : plus l''appui est haut, plus c''est léger. Choisis la hauteur qui te laisse finir la série sans que le bassin bouge.'),
    ('methode-naturelle', 2, 'curl-nordique-assiste', 4, 3, 6, 8, 4, 120, 'Descente lente et contrôlée, mains prêtes à rattraper. Trois séries suffisent : ce travail laisse des courbatures longues et la quatrième n''apporte rien de plus.'),
    ('methode-naturelle', 2, 'scapular-pull-up', 5, 4, 8, 10, 3, 90, 'Bras tendus, on descend les épaules sans plier les coudes. Petite amplitude, mouvement lent.'),
    ('methode-naturelle', 2, 'suitcase-carry', 6, 3, 1, null, 3, 60, 'Une charge d''un seul côté, 20 à 30 pas, puis on change. Épaules de niveau : c''est le tronc qui fait le travail.'),
    ('methode-naturelle', 2, 'dead-bug', 7, 3, 8, 12, 4, 90, 'Bas du dos plaqué au sol du début à la fin. S''il décolle, réduis l''amplitude.'),
    ('methode-naturelle', 2, 'elevation-laterale', 8, 4, 15, 20, 3, 60, 'Charge légère, montée jusqu''à hauteur d''épaule et pas plus haut, sans élan des jambes.'),
    ('methode-naturelle', 2, 'suspension-barre', 9, 3, 1, null, 4, 60, 'Une suspension de 20 à 40 secondes compte pour une répétition. Pose les pieds dès que la prise lâche.'),
    ('methode-naturelle', 2, 'equilibre-unipodal', 10, 3, 1, null, 4, 45, 'Une tenue de 20 à 30 secondes par jambe compte pour une répétition. Garde un appui à portée de main les premières fois.'),
    ('methode-naturelle', 3, 'fente-arriere', 1, 4, 8, 12, 3, 120, 'Par jambe. Le pied part vers l''arrière, le genou avant reste au-dessus du pied.'),
    ('methode-naturelle', 3, 'rowing-haltere', 2, 4, 8, 12, 3, 120, 'Par bras. Main libre en appui, dos plat, on tire vers la hanche.'),
    ('methode-naturelle', 3, 'pompes', 3, 4, 8, 15, 3, 120, 'Deuxième passage de la semaine sur le même mouvement. Même consigne : la pente monte si la fin de série se dégrade.'),
    ('methode-naturelle', 3, 'hip-thrust-une-jambe', 4, 3, 8, 12, 3, 90, 'Par jambe, haut du dos sur un banc ou un canapé. Côtes basses, on monte jusqu''à l''alignement, pas au-delà.'),
    ('methode-naturelle', 3, 'scapular-pull-up', 5, 3, 8, 10, 3, 90, 'Deuxième passage de la semaine. Même amplitude courte, même lenteur.'),
    ('methode-naturelle', 3, 'farmer-walk', 6, 3, 1, null, 3, 90, 'Un trajet de 20 à 30 pas compte pour une répétition. On repose au sol dès que la prise ou le buste lâche.'),
    ('methode-naturelle', 3, 'gainage-ventral', 7, 3, 1, null, 4, 60, 'Une tenue de 20 à 45 secondes compte pour une répétition. Bassin dans l''axe, on coupe dès qu''il descend.'),
    ('methode-naturelle', 3, 'oiseau', 8, 3, 15, 20, 3, 60, 'Buste penché, charge légère, coudes légèrement fléchis. Montée jusqu''à l''horizontale, pas plus.'),
    ('methode-naturelle', 3, 'leg-curl-elastique', 9, 3, 15, 20, 3, 60, 'Élastique fixé bas, talon vers la fesse, retour lent. Une jambe après l''autre.'),
    ('methode-naturelle', 3, 'mollets-une-jambe', 10, 4, 15, 20, 3, 60, 'Par jambe, amplitude complète, court temps d''arrêt en haut.'),
    ('preparation-integree', 1, 'cat-cow', 1, 1, 8, 10, 4, 30, 'Mise en route, sans recherche d''effort.'),
    ('preparation-integree', 1, 'pull-apart-elastique', 2, 3, 12, 15, 4, 45, 'Élastique léger, omoplates qui se rapprochent.'),
    ('preparation-integree', 1, 'developpe-couche-halteres', 3, 4, 8, 12, 3, 150, null),
    ('preparation-integree', 1, 'presse-a-cuisses', 4, 4, 10, 15, 3, 150, 'Amplitude confortable, dos plaqué contre le dossier du début à la fin.'),
    ('preparation-integree', 1, 'tirage-horizontal', 5, 4, 10, 12, 3, 120, null),
    ('preparation-integree', 1, 'leg-curl-allonge', 6, 3, 10, 15, 3, 90, 'Le bassin reste au contact du banc : si tu dois cambrer pour finir la répétition, la série est terminée.'),
    ('preparation-integree', 1, 'ecarte-poulie-basse', 7, 3, 12, 15, 3, 90, null),
    ('preparation-integree', 1, 'elevation-laterale', 8, 3, 12, 15, 3, 90, 'Charge légère, montée jusqu''à l''horizontale, pas au-delà.'),
    ('preparation-integree', 1, 'gainage-ventral', 9, 3, 1, null, 4, 60, 'Une tenue de 30 à 45 secondes compte pour une répétition.'),
    ('preparation-integree', 1, 'pallof-press', 10, 2, 8, 10, 4, 60, 'Par côté. Le tronc résiste à la rotation, il ne la produit pas.'),
    ('preparation-integree', 2, 'rotation-thoracique', 1, 1, 8, 10, 4, 30, 'Par côté, en mise en route.'),
    ('preparation-integree', 2, 'clamshell', 2, 2, 12, 15, 4, 45, null),
    ('preparation-integree', 2, 'souleve-de-terre-trap-bar', 3, 4, 6, 10, 3, 180, 'La barre trap place la charge dans l''axe du corps : c''est la version la plus facile à tenir propre. Elle charge les cuisses et les fessiers — l''arrière de la cuisse, c''est l''exercice suivant qui s''en occupe. Arrête la série dès que le dos s''arrondit.'),
    ('preparation-integree', 2, 'romanian-une-jambe', 4, 3, 8, 10, 3, 120, 'Par jambe, un seul haltère, l''autre main sur un appui. La hanche recule, le genou reste presque tendu, le dos plat. C''est la charnière de la semaine : elle se travaille léger, l''équilibre limite la charge avant que le dos ne le fasse.'),
    ('preparation-integree', 2, 'tirage-vertical', 5, 4, 8, 12, 3, 120, null),
    ('preparation-integree', 2, 'leg-curl-assis', 6, 3, 10, 15, 3, 90, null),
    ('preparation-integree', 2, 'oiseau', 7, 4, 12, 15, 3, 90, 'Buste penché, coudes à peine fléchis, charge légère : ce sont les bras qui montent, pas le buste qui se redresse.'),
    ('preparation-integree', 2, 'face-pull', 8, 4, 12, 15, 3, 90, 'Coudes hauts, tirage vers le front. Charge modérée, le mouvement reste lent sur toute l''amplitude.'),
    ('preparation-integree', 2, 'suitcase-carry', 9, 3, 1, null, 3, 60, '20 à 30 pas par côté comptent pour une répétition.'),
    ('preparation-integree', 2, 'dead-bug', 10, 2, 8, 12, 4, 45, null),
    ('preparation-integree', 3, 'wall-slide', 1, 3, 8, 10, 4, 45, 'Dos et avant-bras au contact du mur, sans creuser le bas du dos.'),
    ('preparation-integree', 3, 'fente-arriere', 2, 3, 8, 12, 3, 120, 'Par jambe. Le pas vers l''arrière charge moins le genou que le pas vers l''avant.'),
    ('preparation-integree', 3, 'developpe-epaules-halteres', 3, 4, 8, 12, 3, 120, null),
    ('preparation-integree', 3, 'rowing-haltere', 4, 4, 8, 12, 3, 120, 'Par bras.'),
    ('preparation-integree', 3, 'hip-thrust', 5, 3, 8, 12, 3, 120, null),
    ('preparation-integree', 3, 'curl-nordique-assiste', 6, 3, 6, 10, 3, 90, 'Talons sur un support glissant. Descends aussi loin que tu peux remonter sans t''aider des mains, et pas plus : ici on réduit l''amplitude, jamais la qualité.'),
    ('preparation-integree', 3, 'pompes', 7, 3, 8, 15, 3, 90, null),
    ('preparation-integree', 3, 'mcgill-curl-up', 8, 2, 6, 8, 4, 45, 'Une main sous le creux des lombaires, une jambe pliée : on décolle à peine les omoplates.'),
    ('preparation-integree', 3, 'gainage-lateral', 9, 2, 1, null, 4, 45, 'Une tenue de 20 à 40 secondes par côté compte pour une répétition.'),
    ('renfort-zones-exposees', 1, 'rotation-externe-elastique', 1, 3, 12, 15, 3, 90, 'Coude collé au corps, élastique léger. C''est du contrôle, pas de la charge — placé en premier pour qu''il soit fait sérieusement.'),
    ('renfort-zones-exposees', 1, 'scaption', 2, 3, 10, 12, 3, 90, 'Bras à 30-45° en avant du corps, pouces vers le haut. Haltères très légers.'),
    ('renfort-zones-exposees', 1, 'y-t-w', 3, 3, 10, 12, 3, 90, 'Sans charge, ou avec des haltères très légers. Trois lettres, trois positions, sans à-coups.'),
    ('renfort-zones-exposees', 1, 'tirage-vertical-prise-neutre', 4, 5, 8, 12, 3, 120, 'Mains face à face : c''est l''angle le plus confortable pour la plupart des gens.'),
    ('renfort-zones-exposees', 1, 'rowing-machine-buste-soutenu', 5, 3, 10, 12, 3, 120, 'Buste posé sur le support : le bas du dos ne participe pas, tout part des omoplates.'),
    ('renfort-zones-exposees', 1, 'developpe-incline-machine', 6, 5, 8, 12, 3, 120, 'La machine guide la trajectoire : après le travail d''omoplate, l''épaule n''a pas à stabiliser une deuxième fois.'),
    ('renfort-zones-exposees', 1, 'face-pull', 7, 3, 12, 15, 3, 90, 'Corde à hauteur du visage, coudes hauts, on finit en écartant les mains.'),
    ('renfort-zones-exposees', 1, 'serratus-punch', 8, 2, 10, 12, 3, 90, 'L''omoplate glisse vers l''avant en fin de mouvement, sans hausser l''épaule.'),
    ('renfort-zones-exposees', 1, 'mollets-assis', 9, 4, 12, 15, 3, 90, 'Genou fléchi, amplitude complète, temps d''arrêt en bas. Premier des trois passages de la semaine sur le mollet.'),
    ('renfort-zones-exposees', 1, 'dead-bug', 10, 3, 10, 12, 3, 90, 'Bas du dos plaqué au sol pendant toute la série. Une répétition = un bras et la jambe opposée.'),
    ('renfort-zones-exposees', 2, 'leg-curl-allonge', 1, 4, 8, 12, 3, 90, 'Placé en premier volontairement : l''arrière de la cuisse est ce que la plupart des programmes servent en dernier, quand il ne reste plus rien.'),
    ('renfort-zones-exposees', 2, 'presse-pieds-hauts', 2, 3, 10, 12, 3, 150, 'Pieds hauts sur le plateau : la hanche mène le mouvement, le genou suit.'),
    ('renfort-zones-exposees', 2, 'presse-a-cuisses', 3, 4, 10, 15, 3, 150, 'Descente contrôlée. On ne cherche pas l''amplitude maximale à tout prix : le bassin reste posé sur le siège.'),
    ('renfort-zones-exposees', 2, 'curl-nordique-assiste', 4, 2, 6, 8, 3, 120, 'Descente lente en s''aidant des mains, retour comme on peut. Deux séries suffisent, c''est très demandant.'),
    ('renfort-zones-exposees', 2, 'terminal-knee-extension', 5, 3, 12, 15, 3, 90, 'Petite amplitude, sur les derniers degrés d''extension. Léger et lent.'),
    ('renfort-zones-exposees', 2, 'hip-thrust', 6, 3, 8, 12, 3, 120, 'Menton rentré, côtes basses. On monte jusqu''à l''alignement du buste et des cuisses, pas plus haut.'),
    ('renfort-zones-exposees', 2, 'abduction-hanche-poulie', 7, 3, 12, 15, 3, 90, 'Par jambe. Le plan latéral est celui qu''on n''entraîne presque jamais, et c''est lui qui tient le bassin quand tu marches.'),
    ('renfort-zones-exposees', 2, 'gainage-lateral', 8, 3, 1, 1, 3, 60, 'Une tenue de 20 à 40 secondes par côté compte pour une répétition.'),
    ('renfort-zones-exposees', 2, 'mollets-debout', 9, 4, 12, 15, 3, 90, 'Genou tendu ici, ce qui déplace le travail par rapport au mollet assis de la première séance.'),
    ('renfort-zones-exposees', 2, 'dorsiflexion-cheville', 10, 2, 15, 20, 3, 45, 'Élastique léger, en fin de séance. La cheville qui monte compte autant que celle qui pousse.'),
    ('renfort-zones-exposees', 3, 'pallof-press', 1, 3, 8, 12, 3, 90, 'Par côté. Bassin immobile, ce sont les bras qui sortent. Il ouvre la séance, c''est voulu.'),
    ('renfort-zones-exposees', 3, 'rotation-externe-couche', 2, 3, 12, 15, 3, 90, 'Couché sur le côté, haltère très léger. Deuxième passage de la semaine sur les rotateurs : ici c''est la fréquence qui compte, pas la charge.'),
    ('renfort-zones-exposees', 3, 'elevation-laterale-machine', 3, 3, 12, 15, 3, 90, 'Il n''y a pas de développé au-dessus de la tête dans ce programme : le deltoïde est chargé ici, sur une trajectoire guidée. Monte jusqu''à l''horizontale, pas plus haut.'),
    ('renfort-zones-exposees', 3, 'leg-curl-assis', 4, 3, 10, 12, 3, 90, 'Deuxième passage sur l''arrière de la cuisse, hanche fléchie cette fois.'),
    ('renfort-zones-exposees', 3, 'presse-une-jambe', 5, 3, 10, 12, 3, 120, 'Par jambe. L''unilatéral révèle l''écart entre les deux côtés que le bilatéral masque.'),
    ('renfort-zones-exposees', 3, 'fente-statique', 6, 3, 8, 12, 3, 120, 'Par jambe, pieds fixes du début à la fin de la série. Charge légère à modérée, buste droit, on descend à la verticale.'),
    ('renfort-zones-exposees', 3, 'rowing-machine-unilateral', 7, 3, 10, 12, 3, 120, 'Par bras. Garde la même charge des deux côtés et compare ce que ça donne.'),
    ('renfort-zones-exposees', 3, 'pompes', 8, 5, 8, 15, 3, 120, 'Mains sous les épaules, corps d''un bloc. Mains surélevées sur un banc si les dernières séries se dégradent.'),
    ('renfort-zones-exposees', 3, 'pull-apart-elastique', 9, 3, 12, 15, 3, 90, 'Bras tendus, on écarte jusqu''à ce que l''élastique touche la poitrine. Deuxième passage de la semaine sur les omoplates.'),
    ('renfort-zones-exposees', 3, 'suitcase-carry', 10, 3, 1, 1, 3, 60, '20 à 30 pas par côté comptent pour une répétition. Charge d''un seul côté, épaules à niveau.'),
    ('renfort-zones-exposees', 3, 'eversion-cheville', 11, 2, 15, 20, 3, 45, 'Élastique léger, en fin de séance. Le mouvement part de la cheville, le genou ne tourne pas.'),
    ('trois-mouvements-sous-maximal', 1, 'squat-barre-dos', 1, 3, 6, 8, 3, 180, 'Journée volontairement facile : séries plus longues, barre nettement plus légère que les deux autres jours. Tu dois reposer la barre en te disant qu''il t''en restait trois.'),
    ('trois-mouvements-sous-maximal', 1, 'developpe-couche-barre', 2, 3, 6, 8, 3, 180, 'Barres de sécurité réglées avant la première série, ou un pareur. Les trois répétitions de réserve sont le premier garde-fou, les barres sont le second.'),
    ('trois-mouvements-sous-maximal', 1, 'traction-pronation', 3, 3, 6, 8, 3, 180, 'Si le haut de la fourchette passe en gardant trois répétitions de réserve sur toutes les séries, ajoute une petite charge à la ceinture plutôt que des répétitions.'),
    ('trois-mouvements-sous-maximal', 1, 'souleve-de-terre-roumain', 4, 4, 8, 10, 3, 150, 'L''arrière de la cuisse, absent de la version précédente. Dos long, barre qui frôle la jambe, on s''arrête à la hauteur où le bassin reste tenu, pas plus bas.'),
    ('trois-mouvements-sous-maximal', 1, 'face-pull', 5, 4, 12, 15, 3, 120, 'Ajout à la méthode d''origine : trois séances de poussée par semaine sans travail d''omoplate, l''épaule finit par le payer.'),
    ('trois-mouvements-sous-maximal', 1, 'dead-bug', 6, 4, 15, 20, 3, 45, 'Le bas du dos reste au contact du sol. S''il se creuse, réduis l''amplitude du bras et de la jambe plutôt que le nombre de répétitions.'),
    ('trois-mouvements-sous-maximal', 1, 'bird-dog', 7, 4, 15, 20, 3, 45, 'Lent, et le bassin ne bascule pas. C''est un exercice de tenue, pas un exercice de vitesse.'),
    ('trois-mouvements-sous-maximal', 1, 'mollets-une-jambe', 8, 4, 15, 20, 3, 45, 'Amplitude complète, temps d''arrêt en haut, une jambe à la fois. Appuie-toi au mur pour l''équilibre, pas pour t''aider à monter.'),
    ('trois-mouvements-sous-maximal', 2, 'squat-barre-dos', 1, 4, 3, 5, 3, 240, 'La journée la plus chargée de la semaine. Trois répétitions encore possibles à la fin de chaque série : si tu hésites, tu es déjà trop lourd.'),
    ('trois-mouvements-sous-maximal', 2, 'developpe-couche-barre', 2, 4, 3, 5, 3, 240, 'Barres de sécurité réglées avant la première série, pas après.'),
    ('trois-mouvements-sous-maximal', 2, 'traction-pronation', 3, 4, 3, 5, 3, 240, 'Descente contrôlée, sans se laisser tomber en fin de série.'),
    ('trois-mouvements-sous-maximal', 2, 'presse-pieds-hauts', 4, 5, 8, 10, 3, 150, 'Pieds hauts sur le plateau : c''est l''arrière de la cuisse et la fesse qui travaillent. Pas de charnière ce jour-là, le bas du dos vient de faire quatre séries de squat lourd.'),
    ('trois-mouvements-sous-maximal', 2, 'face-pull', 5, 3, 12, 15, 3, 120, null),
    ('trois-mouvements-sous-maximal', 2, 'dead-bug', 6, 3, 15, 20, 3, 45, null),
    ('trois-mouvements-sous-maximal', 2, 'bird-dog', 7, 3, 15, 20, 3, 45, null),
    ('trois-mouvements-sous-maximal', 2, 'mollets-une-jambe', 8, 3, 15, 20, 3, 45, null),
    ('trois-mouvements-sous-maximal', 3, 'squat-barre-dos', 1, 4, 5, 6, 3, 210, 'Séries un peu plus longues, charge plus basse que la journée chargée. C''est la séance où la technique se travaille.'),
    ('trois-mouvements-sous-maximal', 3, 'developpe-couche-barre', 2, 4, 5, 6, 3, 210, null),
    ('trois-mouvements-sous-maximal', 3, 'traction-pronation', 3, 4, 5, 6, 3, 210, null),
    ('trois-mouvements-sous-maximal', 3, 'leg-curl-assis', 4, 4, 8, 12, 3, 120, 'Flexion de genou pure, sans charge sur la colonne : c''est le contrepoids direct des séries de squat de la semaine.'),
    ('trois-mouvements-sous-maximal', 3, 'face-pull', 5, 3, 12, 15, 3, 120, null),
    ('trois-mouvements-sous-maximal', 3, 'dead-bug', 6, 3, 15, 20, 3, 45, null),
    ('trois-mouvements-sous-maximal', 3, 'bird-dog', 7, 3, 15, 20, 3, 45, null),
    ('trois-mouvements-sous-maximal', 3, 'mollets-une-jambe', 8, 3, 15, 20, 3, 45, null),
    ('porter-et-marcher', 1, 'equilibre-unipodal', 1, 2, 1, null, 4, 45, 'Une tenue de 30 secondes par jambe compte pour une répétition. Yeux ouverts d''abord ; ferme-les seulement quand la tenue est stable.'),
    ('porter-et-marcher', 1, 'fente-arriere', 2, 3, 8, 12, 3, 90, 'Par jambe, en reculant : le genou avant bouge peu, c''est la hanche qui travaille. Sans charge au départ, haltères quand les trois séries passent proprement.'),
    ('porter-et-marcher', 1, 'pompes', 3, 4, 8, 15, 3, 90, null),
    ('porter-et-marcher', 1, 'tirage-horizontal', 4, 4, 10, 12, 3, 120, 'Le haut du dos est ce qui tient un sac en place, et c''est lui qui lâche en premier sur la durée.'),
    ('porter-et-marcher', 1, 'curl-nordique-assiste', 5, 3, 8, 12, 4, 90, 'Descente lente, remontée aidée par les mains. L''arrière de cuisse freine la jambe à chaque pas : il revient dans les trois séances.'),
    ('porter-et-marcher', 1, 'farmer-walk', 6, 4, 1, null, 3, 90, '20 à 30 pas comptent pour une répétition. La charge ne monte d''un cran que lorsque les quatre séries passent sans que le buste s''affaisse.'),
    ('porter-et-marcher', 1, 'mollets-assis', 7, 3, 10, 15, 3, 90, 'Genou fléchi : ce ne sont pas les mêmes fibres que debout, et ce sont celles qui tiennent sur la distance. C''est la seule version chargée de la séance d''ouverture, parce qu''elle tire moins sur le tendon.'),
    ('porter-et-marcher', 1, 'dorsiflexion-cheville', 8, 2, 15, 20, 4, 45, 'Élastique léger, pied qui monte vers le tibia. Séries longues, placées en fin de séance.'),
    ('porter-et-marcher', 1, 'eversion-cheville', 9, 2, 15, 20, 4, 45, 'Par cheville, élastique léger. C''est la direction qui rattrape un mauvais appui.'),
    ('porter-et-marcher', 1, 'gainage-lateral', 10, 2, 1, null, 4, 45, 'Une tenue de 20 à 40 secondes par côté compte pour une répétition.'),
    ('porter-et-marcher', 2, 'marche-elastique-avant', 1, 2, 10, 12, 4, 60, 'Élastique au-dessus des genoux, petits pas, genoux qui restent écartés.'),
    ('porter-et-marcher', 2, 'goblet-squat-kettlebell', 2, 4, 10, 15, 3, 120, 'Charge tenue haute contre la poitrine, buste droit.'),
    ('porter-et-marcher', 2, 'hip-thrust', 3, 3, 8, 12, 3, 120, 'Menton rentré, côtes basses : on monte le bassin sans cambrer le bas du dos.'),
    ('porter-et-marcher', 2, 'leg-curl-assis', 4, 4, 10, 15, 3, 90, null),
    ('porter-et-marcher', 2, 'rowing-machine-buste-soutenu', 5, 4, 10, 12, 3, 120, 'Buste posé sur le support : le bas du dos ne tient rien, tout part des omoplates.'),
    ('porter-et-marcher', 2, 'pompes-inclinees', 6, 3, 10, 15, 3, 90, 'Mains sur un banc ou une barre haute. Descends le support quand le haut de la fourchette devient facile.'),
    ('porter-et-marcher', 2, 'front-rack-carry', 7, 3, 1, null, 3, 75, '20 à 30 pas comptent pour une répétition, charge tenue haute contre la poitrine. Respire pendant le trajet, ne bloque pas.'),
    ('porter-et-marcher', 2, 'suspension-barre', 8, 3, 1, null, 3, 60, 'Une suspension de 20 à 40 secondes compte pour une répétition. Pieds posés au sol ou sur une caisse si la barre est basse. La poigne est ce qui lâche en premier quand on porte longtemps, et elle se travaille comme le reste.'),
    ('porter-et-marcher', 2, 'mollets-debout', 9, 3, 10, 15, 3, 90, 'Amplitude complète, temps d''arrêt en haut.'),
    ('porter-et-marcher', 2, 'wall-slide', 10, 2, 8, 10, 4, 45, null),
    ('porter-et-marcher', 3, 'presse-a-cuisses', 1, 4, 10, 15, 3, 120, null),
    ('porter-et-marcher', 3, 'leg-curl-allonge', 2, 3, 10, 15, 3, 90, null),
    ('porter-et-marcher', 3, 'tirage-vertical-prise-neutre', 3, 3, 10, 12, 3, 120, 'Prise neutre, paumes face à face.'),
    ('porter-et-marcher', 3, 'developpe-elastique', 4, 3, 10, 15, 3, 90, 'Élastique passé dans le dos, poussée devant. Termine le travail de poussée de la semaine sans charge sur les épaules.'),
    ('porter-et-marcher', 3, 'face-pull-elastique', 5, 3, 12, 15, 3, 60, 'Coudes hauts, mains qui passent au niveau des oreilles. C''est le contrepoids des portages, qui tirent tout vers l''avant.'),
    ('porter-et-marcher', 3, 'farmer-walk', 6, 3, 1, null, 3, 90, '20 à 30 pas comptent pour une répétition. Deuxième passage de la semaine, une série de moins que le premier jour.'),
    ('porter-et-marcher', 3, 'suitcase-carry', 7, 3, 1, null, 3, 60, '20 à 30 pas par côté comptent pour une répétition. Charge d''un seul côté : c''est le tronc qui empêche le buste de pencher.'),
    ('porter-et-marcher', 3, 'gainage-ventral', 8, 3, 1, null, 4, 45, 'Une tenue de 30 à 45 secondes compte pour une répétition.'),
    ('porter-et-marcher', 3, 'mollets-une-jambe', 9, 3, 15, 25, 3, 45, 'Par jambe. Séries longues placées en fin de séance : ici on entraîne la tenue, pas la force.'),
    ('porter-et-marcher', 3, 'marche-pointes', 10, 2, 1, null, 4, 30, '20 à 30 pas sur la pointe des pieds.'),
    ('porter-et-marcher', 3, 'marche-talons', 11, 2, 1, null, 4, 30, '20 à 30 pas sur les talons, pointes relevées.'),
    ('musculation-et-cardio', 1, 'presse-a-cuisses', 1, 3, 8, 12, 3, 150, 'Trois répétitions en réserve, comme sur tout le bas du corps : ce sont les jambes qui courent.'),
    ('musculation-et-cardio', 1, 'developpe-machine-convergent', 2, 3, 8, 12, 2, 150, 'Poussée sur machine plutôt qu''à la barre : la trajectoire est guidée et l''amplitude se règle.'),
    ('musculation-et-cardio', 1, 'tirage-vertical', 3, 3, 8, 12, 2, 120, null),
    ('musculation-et-cardio', 1, 'presse-pieds-hauts', 4, 3, 8, 12, 3, 120, 'Pieds hauts sur la plateforme : les hanches et l''arrière de cuisse travaillent sans aucun soulevé au sol.'),
    ('musculation-et-cardio', 1, 'elevation-laterale', 5, 2, 12, 15, 2, 90, 'Deuxième exposition des deltoïdes dans la semaine, avec l''oiseau de la séance B.'),
    ('musculation-et-cardio', 1, 'face-pull', 6, 2, 12, 15, 2, 90, null),
    ('musculation-et-cardio', 1, 'presse-mollets', 7, 2, 12, 15, 3, 90, null),
    ('musculation-et-cardio', 1, 'gainage-ventral', 8, 2, 20, 30, 2, 60, 'Les répétitions comptent des secondes de maintien. En fin de séance, repos court.'),
    ('musculation-et-cardio', 2, 'squat-gobelet', 1, 3, 10, 12, 3, 120, null),
    ('musculation-et-cardio', 2, 'developpe-incline-machine', 2, 3, 8, 12, 2, 120, null),
    ('musculation-et-cardio', 2, 'rowing-machine-buste-soutenu', 3, 3, 8, 12, 2, 120, 'Buste soutenu par le pupitre : le bas du dos ne tient rien pendant la série.'),
    ('musculation-et-cardio', 2, 'hip-thrust', 4, 3, 8, 12, 3, 120, 'Choisi à la place d''un soulevé lourd : il charge les fessiers sans laisser l''arrière de cuisse douloureux pour la sortie du lendemain.'),
    ('musculation-et-cardio', 2, 'leg-curl-assis', 5, 3, 10, 12, 3, 90, 'Trois répétitions en réserve, volontairement : les ischio-jambiers doivent rester disponibles.'),
    ('musculation-et-cardio', 2, 'oiseau', 6, 2, 12, 15, 2, 90, 'Buste penché, coudes à peine fléchis, montée courte.'),
    ('musculation-et-cardio', 2, 'mollets-assis', 7, 2, 12, 15, 3, 90, null),
    ('musculation-et-cardio', 2, 'pallof-press', 8, 2, 10, 12, 2, 90, 'Répétitions par côté. Rien ne tourne : c''est tout l''exercice.'),
    ('serie-unique', 1, 'hip-hinge-baton', 1, 1, 8, 10, 4, 90, 'À vide, un bâton qui touche la nuque, le haut du dos et le bas du dos en même temps. Les hanches partent vers l''arrière, les genoux fléchissent à peine, et le bâton ne décolle en aucun point. Cet exercice s''apprend, il ne se force pas.'),
    ('serie-unique', 1, 'presse-a-cuisses', 2, 1, 10, 12, 3, 120, 'Deux montées en charge très légères avant la série de travail : c''est la seule série qui compte. Descendez seulement aussi bas que le bas du dos reste plaqué au dossier.'),
    ('serie-unique', 1, 'hip-thrust-machine', 3, 1, 10, 12, 3, 120, 'Montez jusqu''à ce que le buste et les cuisses soient alignés, pas plus haut. Le mouvement vient des hanches, pas d''une cambrure du bas du dos.'),
    ('serie-unique', 1, 'developpe-machine-pectoraux', 4, 1, 10, 12, 3, 120, 'Deux montées en charge très légères avant la série de travail. Réglez le siège pour que les poignées arrivent à hauteur de poitrine, pas d''épaules.'),
    ('serie-unique', 1, 'tirage-horizontal', 5, 1, 10, 12, 3, 120, 'Tirez avec le dos, pas avec les bras : les coudes passent le long du corps et les omoplates se rapprochent. Le buste reste immobile, il ne part pas en arrière pour aider.'),
    ('serie-unique', 1, 'dead-bug', 6, 1, 8, 10, 3, 90, 'Comptez les répétitions par côté, en alternant. Le bas du dos reste en contact avec le sol du début à la fin : si le contact se perd, réduisez l''amplitude.'),
    ('serie-unique', 1, 'face-pull-elastique', 7, 1, 12, 15, 4, 90, 'Léger et sans forcer : cet exercice entretient, il ne fatigue pas. Prenez un élastique où les quinze répétitions restent faciles.'),
    ('machines-guidees', 1, 'presse-a-cuisses', 1, 2, 10, 12, 2, 150, 'Réglez le dossier avant de charger : le bas du dos doit rester plaqué en bas du mouvement.'),
    ('machines-guidees', 1, 'hip-thrust-machine', 2, 2, 10, 12, 2, 120, 'Montez jusqu''à ce que le bassin et les épaules soient alignés, sans chercher à aller plus haut en cambrant.'),
    ('machines-guidees', 1, 'leg-curl-assis', 3, 2, 10, 12, 2, 120, 'L''axe de la machine se place au niveau du genou : c''est ce réglage qui décide du confort de la série.'),
    ('machines-guidees', 1, 'tirage-horizontal-machine', 4, 2, 10, 12, 2, 120, null),
    ('machines-guidees', 1, 'developpe-machine-pectoraux', 5, 2, 10, 12, 2, 120, 'La hauteur de siège est correcte quand les poignées arrivent au niveau du milieu de la poitrine.'),
    ('machines-guidees', 1, 'elevation-laterale-machine', 6, 2, 12, 15, 2, 90, 'Montez jusqu''à l''horizontale, pas au-dessus : la charge doit rester assez légère pour que les épaules ne remontent pas vers les oreilles.'),
    ('machines-guidees', 1, 'bird-dog', 7, 2, 8, 10, 3, 90, 'Bras et jambe opposés, tendus lentement puis ramenés : comptez les répétitions par côté. Le bassin ne doit pas basculer.'),
    ('machines-guidees', 1, 'mcgill-curl-up', 8, 2, 6, 8, 3, 90, 'Une jambe pliée, mains sous le bas du dos, et l''on décolle à peine les épaules du sol en tenant quelques secondes. Le mouvement vient du tronc, jamais de la nuque.'),
    ('micro-doses', 1, 'squat-gobelet', 1, 4, 8, 10, 2, 120, 'Charge tenue contre la poitrine, talons au sol. On descend aussi bas que le contrôle le permet, pas plus.'),
    ('micro-doses', 1, 'developpe-machine-pectoraux', 2, 3, 10, 12, 2, 90, null),
    ('micro-doses', 1, 'tirage-horizontal', 3, 3, 10, 12, 2, 90, null),
    ('micro-doses', 1, 'dead-bug', 4, 4, 10, 10, 3, 90, 'Par côté, en alternant.'),
    ('micro-doses', 2, 'hip-thrust', 1, 3, 10, 12, 2, 120, 'Les côtes restent basses en haut du mouvement : on cherche l''extension de hanche, pas la cambrure.'),
    ('micro-doses', 2, 'developpe-epaules-machine', 2, 4, 10, 12, 2, 90, 'Le seul mouvement du programme qui charge l''épaule et la nuque au-dessus de la tête. Si l''une des deux vous limite, voyez le programme prévu pour cette contrainte plutôt que d''adapter celui-ci.'),
    ('micro-doses', 2, 'tirage-vertical-prise-neutre', 3, 3, 10, 12, 2, 90, null),
    ('micro-doses', 2, 'leg-curl-assis', 4, 3, 12, 15, 2, 90, null),
    ('micro-doses', 3, 'presse-a-cuisses', 1, 4, 10, 12, 2, 120, 'Le bas du dos reste en contact avec le dossier sur toute l''amplitude ; c''est lui qui fixe la profondeur, pas la butée de la machine.'),
    ('micro-doses', 3, 'pompes', 2, 3, 8, 12, 2, 90, 'Si douze passent facilement, surélevez les pieds. Si huit ne passent pas, posez les mains sur un banc plutôt que de raccourcir l''amplitude.'),
    ('micro-doses', 3, 'rowing-haltere', 3, 3, 10, 12, 2, 90, 'Par côté, un appui de la main libre sur un banc.'),
    ('micro-doses', 3, 'pallof-press', 4, 4, 10, 10, 3, 90, 'Par côté. Le bassin ne tourne pas : c''est tout l''exercice.'),
    ('micro-doses', 4, 'presse-pieds-hauts', 1, 3, 10, 12, 2, 120, 'Pieds hauts sur le plateau : le travail passe aux fessiers et aux ischio-jambiers.'),
    ('micro-doses', 4, 'developpe-machine-convergent', 2, 3, 10, 12, 2, 90, null),
    ('micro-doses', 4, 'oiseau', 3, 4, 12, 15, 3, 90, 'Léger. Si les haltères montent grâce à un mouvement du buste, ils sont trop lourds.'),
    ('micro-doses', 4, 'leg-curl-allonge', 4, 3, 12, 15, 2, 90, null),
    ('court-a-la-maison', 1, 'cat-cow', 1, 1, 8, 10, 4, 30, 'Lentement, en suivant la respiration. C''est une mise en route, pas une série de travail.'),
    ('court-a-la-maison', 1, 'pompes-inclinees', 2, 3, 8, 12, 3, 90, 'Mains sur un plan de travail ou le bord d''un lit. Plus l''appui est haut, plus c''est facile : ajustez la hauteur, pas le nombre de répétitions.'),
    ('court-a-la-maison', 1, 'step-down', 3, 3, 8, 10, 3, 90, 'Par côté, depuis une marche basse. Le genou reste dans l''axe du pied et la descente est freinée, jamais lâchée. Si la marche vous paraît haute, prenez-en une plus basse plutôt que de réduire l''amplitude.'),
    ('court-a-la-maison', 1, 'rowing-inverse', 4, 2, 8, 12, 3, 90, 'Sous une table solide ou sur une barre basse. Vérifiez la stabilité de l''appui avant de vous mettre dessous. Plus le corps est redressé, plus c''est facile.'),
    ('court-a-la-maison', 1, 'curl-nordique-assiste', 5, 2, 6, 8, 3, 90, 'Sur un sol lisse, en chaussettes ou avec un chiffon sous les talons. Deux jambes, petite amplitude au début : allongez-la seulement quand les hanches cessent de s''affaisser.'),
    ('court-a-la-maison', 1, 'pont-fessier', 6, 2, 15, 20, 3, 45, 'En fin de séance, sur un rythme régulier et des repos courts. Les côtes restent basses : ce sont les fessiers qui montent le bassin, pas le bas du dos.'),
    ('court-a-la-maison', 1, 'dead-bug', 7, 3, 16, 20, 3, 45, 'En alternant les côtés, chaque bras-jambe compte pour une répétition. Le bas du dos reste en contact avec le sol : si le contact se perd, raccourcissez le geste du bras et de la jambe.'),
    ('court-a-la-maison', 2, 'rotation-thoracique', 1, 1, 8, 10, 4, 30, 'Par côté, sans forcer l''amplitude. C''est une mise en route, pas une série de travail.'),
    ('court-a-la-maison', 2, 'rowing-inverse', 2, 3, 8, 12, 3, 90, 'Même appui qu''en séance A, une série de plus. Revérifiez la stabilité de la table avant de vous mettre dessous. Redressez le corps pour alléger, allongez-le pour durcir.'),
    ('court-a-la-maison', 2, 'curl-nordique-assiste', 3, 3, 6, 8, 3, 90, 'Sur un sol lisse. La descente est lente, la remontée se fait en poussant par les talons. Gardez la même amplitude qu''en séance A tant qu''elle se tient proprement.'),
    ('court-a-la-maison', 2, 'pompes', 4, 2, 6, 10, 3, 90, 'Au sol cette fois. Si six répétitions propres ne sortent pas, remettez les mains sur un appui surélevé et gardez le même nombre de séries.'),
    ('court-a-la-maison', 2, 'pont-fessier-une-jambe', 5, 2, 8, 10, 3, 90, 'Par côté. Le bassin reste horizontal : si un côté s''affaisse, revenez au pont sur deux jambes.'),
    ('court-a-la-maison', 2, 'step-down', 6, 2, 8, 10, 3, 90, 'Par côté, comme en séance A mais deux séries seulement. Marche basse, genou dans l''axe du pied, descente freinée.'),
    ('court-a-la-maison', 2, 'crunch-inverse', 7, 2, 15, 20, 3, 45, 'En fin de séance, repos courts. Le bassin décolle sans élan : si les jambes lancent le mouvement, réduisez l''amplitude.'),
    ('trois-mouvements-quotidiens', 1, 'pompes-inclinees', 1, 2, 6, 10, 4, 90, 'Choisissez une hauteur de support où dix répétitions restent faciles : un plan de travail, un dossier de canapé, un mur. Plus le support est haut, plus c''est facile.'),
    ('trois-mouvements-quotidiens', 1, 'rowing-inverse', 2, 2, 6, 10, 4, 90, 'Plus le corps est proche de la verticale, plus c''est facile. Une table solide fait l''affaire.'),
    ('trois-mouvements-quotidiens', 1, 'pont-fessier', 3, 2, 6, 10, 4, 90, 'Dos au sol, pieds à plat, poussez dans les talons pour monter le bassin, puis redescendez lentement. Montez seulement aussi haut que ça reste confortable.'),
    ('onze-minutes', 1, 'cat-cow', 1, 1, 8, 10, 3, 90, 'Ouverture de séance. Au rythme de la respiration, sans forcer : l''amplitude utile est celle qui ne tire nulle part.'),
    ('onze-minutes', 1, 'mcgill-curl-up', 2, 2, 8, 10, 3, 90, 'Une main sous le creux du dos, un genou fléchi, l''autre jambe tendue. Les épaules décollent à peine : c''est tout le mouvement. Le cou ne tire pas.'),
    ('onze-minutes', 1, 'bird-dog', 3, 2, 8, 10, 3, 90, 'Répétitions par côté. Le bassin reste horizontal ; si le dos se creuse, on tend moins loin.'),
    ('onze-minutes', 1, 'pompes-inclinees', 4, 3, 8, 12, 3, 90, 'Plus le support est haut, plus le mouvement est facile. On ajoute les répétitions d''abord : le support ne descend qu''une fois le haut de la fourchette atteint proprement.'),
    ('onze-minutes', 1, 'rowing-inverse', 5, 3, 8, 12, 3, 90, 'Sous une table solide ou une barre basse, talons au sol. Plus le buste est proche de la verticale, plus c''est facile. Même règle : les répétitions d''abord, on ne s''allonge qu''ensuite.'),
    ('onze-minutes', 1, 'mountain-climber', 6, 1, 15, 25, 3, 60, 'Une répétition = un genou ramené. À tempo maîtrisé : ce n''est pas un chrono, le bassin ne monte pas et le dos ne se creuse pas.'),
    ('gestes-utilitaires', 1, 'cat-cow', 1, 1, 8, 10, 4, 45, 'Sans forcer, au rythme de la respiration. C''est l''ouverture de séance, pas un exercice de force.'),
    ('gestes-utilitaires', 1, 'wall-slide', 2, 2, 8, 10, 4, 45, 'Dos, tête et avant-bras au contact du mur, on monte et on descend lentement. Si un avant-bras décolle, on s''arrête là et on redescend.'),
    ('gestes-utilitaires', 1, 'hip-hinge-baton', 3, 2, 8, 10, 4, 60, 'Le bâton garde trois contacts : tête, milieu du dos, sacrum. C''est le geste de ramassage installé à vide, avant de mettre du poids dessus.'),
    ('gestes-utilitaires', 1, 'squat-gobelet', 4, 3, 8, 12, 3, 120, 'Un haltère, ou tout objet lesté tenu contre la poitrine. Les coudes restent devant, à l''intérieur des genoux. Si le buste bascule vers l''avant, l''objet est trop lourd.'),
    ('gestes-utilitaires', 1, 'traction-neutre', 5, 3, 3, 6, 2, 180, 'La famille « grimper ». Trois à six répétitions complètes, en gardant deux répétitions de marge. Si aucune répétition complète ne vient, on ne force pas ici : c''est le rowing inversé, juste en dessous, qui construit ce mouvement — on revient à la barre le jour où trois répétitions passent.'),
    ('gestes-utilitaires', 1, 'rowing-inverse', 6, 3, 8, 12, 3, 90, 'Plus le corps est proche de la verticale, plus c''est facile. C''est le seul réglage : on choisit l''inclinaison qui laisse trois répétitions de marge à la douzième.'),
    ('gestes-utilitaires', 1, 'pompes-inclinees', 7, 3, 8, 12, 3, 90, 'Mains sur un support haut — plan de travail, rebord de fenêtre, dossier de banc. Plus le support est bas, plus c''est dur.'),
    ('gestes-utilitaires', 1, 'farmer-walk', 8, 3, 20, 30, 3, 90, 'Les répétitions comptent des pas. Une charge dans chaque main, épaules basses, on marche normalement.'),
    ('gestes-utilitaires', 1, 'bear-crawl', 9, 2, 15, 20, 3, 60, 'Les répétitions comptent des appuis de main. Bassin bas, déplacement lent, genoux à quelques centimètres du sol.'),
    ('gestes-utilitaires', 1, 'equilibre-unipodal', 10, 2, 20, 30, 4, 45, 'Les répétitions comptent des secondes de maintien, par jambe. Un appui à portée de main.'),
    ('gestes-utilitaires', 2, 'cat-cow', 1, 1, 8, 10, 4, 45, 'Sans forcer, au rythme de la respiration. Même ouverture qu''en leçon A.'),
    ('gestes-utilitaires', 2, 'wall-slide', 2, 2, 8, 10, 4, 45, 'Deuxième passage de la semaine sur la préparation d''épaule. Même consigne qu''en leçon A.'),
    ('gestes-utilitaires', 2, 'curl-nordique-assiste', 3, 2, 6, 10, 4, 90, 'Talons sur un linge, sur un sol lisse : bassin décollé, on éloigne les talons puis on les ramène. On garde l''amplitude où le bassin ne retombe pas — c''est elle qui règle la difficulté.'),
    ('gestes-utilitaires', 2, 'step-up', 4, 3, 8, 10, 3, 90, 'Répétitions par jambe. On monte avec la jambe posée sur la marche, sans s''aider d''une impulsion de celle restée au sol. Une marche basse d''abord : la hauteur est le réglage.'),
    ('gestes-utilitaires', 2, 'rowing-inverse', 5, 3, 8, 12, 3, 90, 'Deuxième passage de la semaine sur le tirage. Même réglage qu''en leçon A : l''inclinaison choisie laisse trois répétitions de marge.'),
    ('gestes-utilitaires', 2, 'pompes', 6, 3, 6, 12, 3, 90, 'Si six répétitions ne viennent pas au sol, les mains sur un support haut règlent le problème et le travail reste le même.'),
    ('gestes-utilitaires', 2, 'suitcase-carry', 7, 4, 15, 20, 3, 75, 'Les répétitions comptent des pas, d''un seul côté. Quatre séries : deux à gauche, deux à droite, en alternant. Le buste reste droit, c''est tout l''exercice — le tronc travaille en résistant à l''inclinaison, pas en se pliant.'),
    ('gestes-utilitaires', 2, 'suspension-barre', 8, 2, 20, 30, 4, 60, 'Les répétitions comptent des secondes. Pieds au sol si nécessaire : on ne suspend alors qu''une partie du poids, et c''est le réglage.'),
    ('gestes-utilitaires', 2, 'marche-talons', 9, 2, 20, 30, 3, 45, 'Les répétitions comptent des pas, pointes de pieds relevées.'),
    ('gestes-utilitaires', 2, 'bird-dog', 10, 2, 8, 10, 3, 60, 'Répétitions par côté. Bras et jambe opposés, sans que le bassin ne bascule.'),
    ('jambes-et-equilibre', 1, 'hip-hinge-baton', 1, 2, 8, 10, 4, 90, 'Sans charge, pour ouvrir la séance. Un manche à balai le long du dos, en contact à la tête, entre les omoplates et au bassin : on se penche en gardant ces trois contacts.'),
    ('jambes-et-equilibre', 1, 'squat-gobelet', 2, 4, 8, 12, 3, 120, 'C''est le geste de se lever d''une chaise, avec une charge tenue contre la poitrine. Descendre à la hauteur qui reste confortable, pas plus bas. Une chaise derrière vous ne coûte rien.'),
    ('jambes-et-equilibre', 1, 'leg-curl-elastique', 3, 3, 10, 15, 3, 90, 'Par jambe, une main sur un appui.'),
    ('jambes-et-equilibre', 1, 'pont-fessier', 4, 3, 10, 12, 3, 90, 'Au sol. Pousser par les talons, monter jusqu''à l''alignement et pas au-delà.'),
    ('jambes-et-equilibre', 1, 'rowing-elastique', 5, 4, 10, 15, 3, 90, 'Ajouté à la méthode d''origine, qui ne travaillait que le bas du corps. Il figure dans les deux séances. Tirer les coudes vers l''arrière, épaules basses.'),
    ('jambes-et-equilibre', 1, 'bird-dog', 6, 4, 8, 10, 4, 90, 'Par côté, en alternant. Un bras et une jambe bougent, le dos ne bouge pas ; si le bassin bascule, lever moins haut.'),
    ('jambes-et-equilibre', 1, 'mollets-une-jambe', 7, 2, 10, 15, 3, 90, 'Par jambe, une main sur un appui.'),
    ('jambes-et-equilibre', 1, 'equilibre-unipodal', 8, 2, 20, 30, 4, 45, 'Compter en secondes de tenue, pas en répétitions. Une main posée sur un appui stable, les yeux ouverts, un mur à portée. Changer de jambe à chaque série.'),
    ('jambes-et-equilibre', 1, 'marche-pointes', 9, 2, 15, 20, 4, 45, 'Compter en pas. Le long d''un mur ou dans un couloir étroit, une main libre pour se rattraper.'),
    ('jambes-et-equilibre', 2, 'hip-hinge-baton', 1, 2, 8, 10, 4, 90, 'Sans charge, pour ouvrir la séance. Un manche à balai le long du dos, en contact à la tête, entre les omoplates et au bassin : on se penche en gardant ces trois contacts.'),
    ('jambes-et-equilibre', 2, 'fente-statique', 2, 4, 8, 10, 4, 120, 'Par jambe. Les deux pieds restent posés : rien ne se déplace pendant la série. Le genou arrière descend seulement jusqu''où cela reste facile. Commencer sans charge, une main sur un appui ; l''haltère viendra quand la position sera sûre.'),
    ('jambes-et-equilibre', 2, 'leg-curl-elastique', 3, 3, 10, 15, 3, 90, 'Par jambe, une main sur un appui.'),
    ('jambes-et-equilibre', 2, 'abduction-elastique-debout', 4, 3, 12, 15, 3, 90, 'Par jambe. Se tenir à un appui de l''autre main et garder le buste droit : c''est la hanche qui travaille, pas le tronc qui se penche.'),
    ('jambes-et-equilibre', 2, 'rowing-elastique', 5, 4, 10, 15, 3, 90, 'Ajouté à la méthode d''origine, qui ne travaillait que le bas du corps. Il figure dans les deux séances. Tirer les coudes vers l''arrière, épaules basses.'),
    ('jambes-et-equilibre', 2, 'bird-dog', 6, 4, 8, 10, 4, 90, 'Par côté, en alternant. Un bras et une jambe bougent, le dos ne bouge pas ; si le bassin bascule, lever moins haut.'),
    ('jambes-et-equilibre', 2, 'dorsiflexion-cheville', 7, 2, 12, 15, 4, 90, 'Par pied. Assis, l''élastique accroché devant.'),
    ('jambes-et-equilibre', 2, 'equilibre-unipodal', 8, 2, 20, 30, 4, 45, 'Compter en secondes de tenue, pas en répétitions. Une main posée sur un appui stable, les yeux ouverts, un mur à portée. Changer de jambe à chaque série.'),
    ('jambes-et-equilibre', 2, 'marche-talons', 9, 2, 15, 20, 4, 45, 'Compter en pas. Même précaution que la marche sur les pointes : un appui à portée de main.'),
    ('entretien-grossesse', 1, 'squat-gobelet', 1, 3, 10, 12, 3, 120, 'Charge tenue contre la poitrine, buste droit. Descendre à la hauteur confortable du jour, qui changera au fil des semaines. Expirer en remontant.'),
    ('entretien-grossesse', 1, 'rowing-elastique', 2, 3, 12, 15, 3, 90, 'Debout ou assis, élastique fixé devant vous. Épaules basses, coudes le long du corps.'),
    ('entretien-grossesse', 1, 'pompes-inclinees', 3, 3, 8, 12, 3, 90, 'Mains sur un banc, une table ou un mur. Plus les mains sont hautes, plus c''est facile : monter les mains plutôt que de forcer.'),
    ('entretien-grossesse', 1, 'hip-hinge-baton', 4, 2, 10, 12, 4, 90, 'Debout, un bâton ou un manche à balai le long du dos, en contact à la tête, entre les omoplates et au bassin. Pousser les hanches vers l''arrière, genoux à peine fléchis, sans que le bâton décolle. Sans charge, et l''amplitude se réduit d''elle-même au fil des semaines : c''est normal.'),
    ('entretien-grossesse', 1, 'abduction-elastique-debout', 5, 2, 12, 15, 3, 90, 'Par jambe, une main sur un appui. Élastique au-dessus des chevilles, le buste reste droit.'),
    ('entretien-grossesse', 1, 'scaption', 6, 2, 12, 15, 3, 90, 'Haltères légers, monter dans un plan à mi-chemin entre l''avant et le côté, jusqu''à hauteur d''épaule au maximum. Rien au-dessus de la tête.'),
    ('entretien-grossesse', 1, 'retraction-scapulaire', 7, 2, 12, 15, 4, 90, 'Charge légère, pour le haut du dos qui passe ses journées penché en avant. Rapprocher les omoplates sans hausser les épaules.'),
    ('entretien-grossesse', 1, 'marche-pointes', 8, 2, 12, 15, 4, 90, 'Le long d''un mur ou d''un plan de travail, une main libre pour se rattraper. Compter les pas par pied.'),
    ('entretien-grossesse', 1, 'suitcase-carry', 9, 3, 12, 15, 4, 90, 'Un seul haltère, dans une main, bras le long du corps. Marcher en restant droit, sans se pencher du côté chargé — c''est là tout le travail. Compter les pas, puis changer de main.'),
    ('entretien-grossesse', 1, 'bird-dog', 10, 3, 8, 10, 4, 90, 'Par côté. À quatre pattes, le dos immobile ; si le bassin bascule, lever moins haut.'),
    ('entretien-grossesse', 2, 'fente-statique', 1, 3, 8, 10, 3, 120, 'Par jambe, les pieds restent en place, un mur à portée de main. Ne pas descendre plus bas que ce qui reste stable.'),
    ('entretien-grossesse', 2, 'tirage-elastique-haut', 2, 3, 12, 15, 3, 90, 'Élastique accroché en hauteur, assis ou à genoux, dos droit. Tirer les coudes vers les côtes sans se pencher en arrière.'),
    ('entretien-grossesse', 2, 'developpe-elastique', 3, 3, 12, 15, 3, 90, 'Debout, élastique dans le dos. Expirer en poussant.'),
    ('entretien-grossesse', 2, 'leg-curl-elastique', 4, 2, 12, 15, 4, 90, 'Debout, une main sur un appui, l''élastique à la cheville : plier le genou en ramenant le talon vers la fesse. Par jambe.'),
    ('entretien-grossesse', 2, 'elevation-laterale', 5, 2, 12, 15, 3, 90, 'Charge légère, monter jusqu''à l''horizontale au maximum.'),
    ('entretien-grossesse', 2, 'face-pull-elastique', 6, 2, 12, 15, 4, 90, 'Élastique à hauteur de visage, tirer vers le front en ouvrant les coudes. Épaules basses.'),
    ('entretien-grossesse', 2, 'dorsiflexion-cheville', 7, 2, 12, 15, 4, 90, 'Assis, élastique autour de l''avant du pied, ramener les orteils vers soi. Par pied.'),
    ('entretien-grossesse', 2, 'gainage-lateral-genoux', 8, 3, 12, 15, 4, 90, 'Par côté, compter en secondes de tenue. Genoux fléchis : c''est la version qui demande le moins au ventre, et c''est volontaire.'),
    ('entretien-grossesse', 2, 'bird-dog', 9, 3, 8, 10, 4, 90, 'Par côté. Le même qu''en séance A, et c''est voulu : c''est le mouvement qui tient le bas du dos, il revient à chaque séance.'),
    ('entretien-grossesse', 2, 'cat-cow', 10, 2, 8, 10, 4, 90, 'Compter les allers-retours. Sans forcer, en respirant : c''est un moment de mobilité, pas un exercice de force.'),
    ('post-partum-progressif', 1, 'pont-fessier', 1, 3, 10, 12, 3, 90, 'Expirer en montant. Monter jusqu''à l''alignement et pas au-delà : on ne cherche pas à cambrer.'),
    ('post-partum-progressif', 1, 'squat-gobelet', 2, 3, 10, 12, 3, 120, 'Charge légère au début. Expirer en remontant, sans jamais bloquer la respiration.'),
    ('post-partum-progressif', 1, 'rowing-elastique', 3, 3, 12, 15, 3, 90, 'Le haut du dos passe ses journées penché en avant ; ce mouvement fait exactement le contraire.'),
    ('post-partum-progressif', 1, 'developpe-elastique', 4, 3, 10, 12, 3, 90, 'Debout, l''élastique passé dans le dos. Expirer en poussant ; si le dos se cambre pour aller plus loin, prendre un élastique moins tendu.'),
    ('post-partum-progressif', 1, 'leg-curl-elastique', 5, 3, 12, 15, 3, 90, 'Par jambe.'),
    ('post-partum-progressif', 1, 'bird-dog', 6, 3, 8, 10, 4, 90, 'Par côté. Expirer en tendant. Si le bassin bascule ou si le ventre pousse vers le bas, lever moins haut.'),
    ('post-partum-progressif', 1, 'gainage-lateral-genoux', 7, 3, 15, 20, 4, 60, 'Par côté, compter en secondes de tenue. Genoux fléchis, c''est volontaire : cette version demande beaucoup moins au ventre que la planche sur les coudes. Elle remplace ici le port de charge d''un seul côté — même travail, résister à l''inclinaison, sans rien à soulever.'),
    ('post-partum-progressif', 1, 'clamshell', 8, 2, 12, 15, 4, 90, 'Par côté.'),
    ('post-partum-progressif', 2, 'hip-thrust-elastique', 1, 3, 12, 15, 3, 90, 'Expirer en montant, sans cambrer en fin de mouvement.'),
    ('post-partum-progressif', 2, 'fente-statique', 2, 3, 8, 10, 3, 120, 'Par jambe, les pieds restent en place, un appui à portée de main.'),
    ('post-partum-progressif', 2, 'hip-hinge-baton', 3, 3, 8, 10, 4, 90, 'Sans charge, un bâton le long du dos. C''est le geste qu''on refait vingt fois par jour pour ramasser quelque chose : il se réapprend avant de se charger.'),
    ('post-partum-progressif', 2, 'tirage-elastique-haut', 4, 3, 10, 12, 3, 90, 'Élastique fixé en hauteur, tirer vers la poitrine sans se pencher en arrière pour aller plus loin.'),
    ('post-partum-progressif', 2, 'pompes-inclinees', 5, 3, 8, 12, 3, 90, 'Mains sur un banc ou un plan de travail. Le ventre ne doit pas s''affaisser ; si c''est le cas, monter les mains.'),
    ('post-partum-progressif', 2, 'gainage-lateral-genoux', 6, 3, 15, 20, 4, 60, 'Par côté, compter en secondes de tenue. Genoux fléchis : cette version demande beaucoup moins au ventre que la planche sur les coudes.'),
    ('post-partum-progressif', 2, 'dead-bug', 7, 3, 8, 10, 4, 90, 'Par côté, en alternant. Expirer en tendant la jambe, et ne descendre que jusqu''où le bas du dos reste plaqué au sol.'),
    ('post-partum-progressif', 2, 'monster-walk', 8, 2, 12, 15, 4, 90, 'Compter les pas par direction.'),
    ('post-partum-progressif', 2, 'cat-cow', 9, 2, 15, 20, 4, 45, 'En fin de séance, compter les allers-retours, lentement et sans forcer : c''est de la mobilité, pas un effort.'),
    ('sans-materiel-par-niveaux', 1, 'pompes-inclinees', 1, 4, 8, 15, 3, 90, 'Règle la difficulté par la hauteur des mains : plus c''est haut, plus c''est facile. Quand tu tiens quinze répétitions propres sur deux séances d''affilée, descends d''un cran, jusqu''aux pompes au sol puis aux pompes déclinées.'),
    ('sans-materiel-par-niveaux', 1, 'rowing-inverse', 2, 4, 8, 12, 3, 90, 'Sous une table solide ou une barre basse. Plus ton corps est proche de la verticale, plus c''est facile ; le cran suivant est de surélever les pieds.'),
    ('sans-materiel-par-niveaux', 1, 'step-down', 3, 3, 8, 12, 3, 90, 'Le compte est par jambe. La hauteur de la marche règle la difficulté : commence bas. Si l''avant du genou est gêné, réduis la hauteur avant de réduire les répétitions.'),
    ('sans-materiel-par-niveaux', 1, 'curl-nordique-assiste', 4, 3, 6, 10, 3, 90, 'Freine la descente aussi loin que tu la contrôles, puis aide-toi des mains pour remonter. L''amplitude s''allonge d''elle-même au fil des semaines.'),
    ('sans-materiel-par-niveaux', 1, 'mollets-une-jambe', 5, 3, 12, 20, 2, 60, 'Le compte est par jambe. Une main au mur pour l''équilibre, sans t''appuyer dessus.'),
    ('sans-materiel-par-niveaux', 1, 'dead-bug', 6, 3, 8, 10, 3, 60, 'Le compte est par côté. Le bas du dos reste au contact du sol du début à la fin ; dès qu''il se décolle, la série est finie.'),
    ('sans-materiel-par-niveaux', 1, 'gainage-lateral', 7, 3, 1, 1, 3, 45, 'Une série égale un maintien de vingt à trente secondes de chaque côté. Si c''est trop, pose les genoux : c''est le cran en dessous.'),
    ('sans-materiel-par-niveaux', 2, 'pompes', 1, 3, 6, 12, 3, 90, 'C''est le cran au-dessus des pompes inclinées de la séance A : mêmes appuis, mais au sol. Si tu n''y es pas encore, garde les mains sur une marche basse. Quand les douze répétitions sont acquises, rapprocher les mains est le cran suivant pour les triceps.'),
    ('sans-materiel-par-niveaux', 2, 'rowing-inverse-eleve', 2, 4, 6, 12, 3, 90, 'C''est le cran au-dessus du tirage de la séance A. Si tu n''y arrives pas encore, repose les pieds au sol : la séance reste valable.'),
    ('sans-materiel-par-niveaux', 2, 'wall-sit', 3, 3, 1, 1, 3, 90, 'Une série égale un maintien de trente à quarante-cinq secondes. Monte la durée avant de descendre plus bas sur le mur.'),
    ('sans-materiel-par-niveaux', 2, 'pont-fessier-une-jambe', 4, 3, 10, 15, 3, 60, 'Le compte est par jambe. Si le bassin bascule d''un côté, repasse aux deux jambes le temps que ça se tienne.'),
    ('sans-materiel-par-niveaux', 2, 'curl-nordique-assiste', 5, 2, 6, 10, 3, 90, 'Deux séries suffisent ici : l''exercice revient dans la séance A, et l''important est que les ischio-jambiers travaillent deux fois par semaine plutôt que beaucoup une seule fois.'),
    ('sans-materiel-par-niveaux', 2, 'bird-dog', 6, 3, 8, 10, 3, 45, 'Le compte est par côté. Lent, sans à-coup : un verre d''eau posé sur le bas du dos ne devrait pas se renverser.'),
    ('sans-materiel-par-niveaux', 2, 'mcgill-curl-up', 7, 3, 6, 8, 3, 45, 'Les mains sous le bas du dos, une jambe pliée. On monte à peine — quelques centimètres — et on tient trois secondes. La nuque ne tire pas.'),
    ('sans-materiel-par-niveaux', 2, 'equilibre-unipodal', 8, 2, 1, 1, 3, 45, 'Une série égale trente secondes par jambe. Le cran au-dessus consiste à fermer les yeux, pas à tenir plus longtemps.'),
    ('lourd-moyen-leger', 1, 'squat-barre-dos', 1, 5, 5, 5, 2, 240, 'Les quatre premières séries montent progressivement vers la cinquième. Seule la dernière est difficile.'),
    ('lourd-moyen-leger', 1, 'developpe-couche-barre', 2, 5, 5, 5, 2, 210, 'Même montée en charge. Un partenaire ou des barres de sécurité, systématiquement.'),
    ('lourd-moyen-leger', 1, 'rowing-barre', 3, 5, 5, 5, 2, 180, 'Buste stable, pas de balancier. Si le dos s''arrondit, la série est terminée.'),
    ('lourd-moyen-leger', 1, 'face-pull', 4, 3, 12, 15, 3, 90, 'Contrepoids aux trois mouvements de la séance, qui poussent l''épaule vers l''avant.'),
    ('lourd-moyen-leger', 1, 'pallof-press', 5, 3, 10, 12, 3, 60, 'Le tronc travaille à résister à la rotation, pas à en produire.'),
    ('lourd-moyen-leger', 2, 'squat-gobelet', 1, 4, 8, 10, 3, 120, 'L''haltère tenu devant borne la charge : impossible d''en faire une séance lourde déguisée.'),
    ('lourd-moyen-leger', 2, 'developpe-incline-halteres', 2, 4, 8, 10, 3, 150, null),
    ('lourd-moyen-leger', 2, 'tirage-horizontal', 3, 4, 10, 12, 3, 120, null),
    ('lourd-moyen-leger', 2, 'leg-curl-assis', 4, 3, 10, 12, 3, 120, 'Les squats seuls ne suffisent pas à l''arrière de la cuisse.'),
    ('lourd-moyen-leger', 2, 'hip-thrust', 5, 3, 10, 12, 3, 120, null),
    ('lourd-moyen-leger', 2, 'y-t-w', 6, 3, 12, 15, 3, 60, 'Charges très légères. C''est un travail de position, pas de force.'),
    ('lourd-moyen-leger', 3, 'squat-barre-dos', 1, 5, 5, 5, 3, 210, 'Environ dix pour cent de moins que la journée lourde. La séance doit se terminer avec de la marge.'),
    ('lourd-moyen-leger', 3, 'developpe-couche-barre', 2, 5, 5, 5, 3, 180, null),
    ('lourd-moyen-leger', 3, 'traction-assistee', 3, 4, 6, 8, 2, 150, 'Réglez l''assistance pour finir la quatrième série proprement, pas pour survivre à la première.'),
    ('lourd-moyen-leger', 3, 'leg-curl-allonge', 4, 3, 10, 12, 2, 120, null),
    ('lourd-moyen-leger', 3, 'elevation-laterale', 5, 3, 12, 15, 3, 90, null),
    ('lourd-moyen-leger', 3, 'dead-bug', 6, 3, 10, 12, 3, 60, 'Le bas du dos reste plaqué au sol. Dès qu''il se décolle, on arrête.'),
    ('quinze-minutes-quotidiennes', 1, 'cat-cow', 1, 1, 10, 12, 4, 20, 'La mise en route. Lentement, sans forcer les fins d''amplitude.'),
    ('quinze-minutes-quotidiennes', 1, 'rotation-thoracique', 2, 1, 8, 10, 4, 20, 'Répétitions par côté.'),
    ('quinze-minutes-quotidiennes', 1, 'retraction-cervicale', 3, 2, 10, 12, 4, 30, 'Le menton recule à l''horizontale, il ne descend pas vers la poitrine.'),
    ('quinze-minutes-quotidiennes', 1, 'wall-slide', 4, 2, 8, 12, 4, 30, 'Les avant-bras restent en contact avec le mur.'),
    ('quinze-minutes-quotidiennes', 1, 'pompes-inclinees', 5, 2, 8, 12, 3, 60, 'Mains sur un plan de travail, un rebord de fenêtre, une table. Plus les mains sont hautes, plus c''est facile.'),
    ('quinze-minutes-quotidiennes', 1, 'rowing-inverse', 6, 3, 8, 12, 3, 60, 'Sous une table solide, ou à une barre basse. Plus le corps est proche de la verticale, plus c''est facile.'),
    ('quinze-minutes-quotidiennes', 1, 'pont-fessier', 7, 2, 12, 15, 3, 45, null),
    ('quinze-minutes-quotidiennes', 1, 'wall-sit', 8, 2, 25, 40, 3, 45, 'Les répétitions comptent des secondes. Remonter la hauteur du bassin si le genou tire.'),
    ('quinze-minutes-quotidiennes', 1, 'hip-hinge-baton', 9, 1, 8, 10, 4, 30, 'Le bâton garde trois contacts : nuque, milieu du dos, sacrum.'),
    ('quinze-minutes-quotidiennes', 1, 'dead-bug', 10, 2, 6, 10, 3, 30, 'Répétitions par côté. Le bas du dos reste plaqué au sol.'),
    ('quinze-minutes-quotidiennes', 1, 'gainage-lateral-genoux', 11, 2, 20, 30, 3, 30, 'Les répétitions comptent des secondes, par côté.'),
    ('quinze-minutes-quotidiennes', 1, 'equilibre-unipodal', 12, 1, 30, 45, 4, 20, 'Les répétitions comptent des secondes, par jambe. C''est la fin de séance : on se pose, on respire, on tient.'),
    ('equilibre-et-posture', 1, 'equilibre-unipodal', 1, 3, 30, 45, 3, 45, 'Secondes par jambe. Se tenir à un mur au début : l''objectif est de passer du temps sur une jambe, pas de se rattraper.'),
    ('equilibre-et-posture', 1, 'squat-gobelet', 2, 3, 10, 12, 2, 120, 'La charge tenue devant redresse le buste toute seule : c''est pour cela qu''elle ouvre la séance.'),
    ('equilibre-et-posture', 1, 'pompes', 3, 3, 8, 12, 2, 90, 'Mains sur un appui haut si la série complète ne passe pas au sol.'),
    ('equilibre-et-posture', 1, 'rowing-haltere', 4, 3, 10, 12, 2, 90, 'Répétitions par bras.'),
    ('equilibre-et-posture', 1, 'fente-arriere', 5, 3, 8, 10, 2, 90, 'Répétitions par jambe. Le pas part vers l''arrière : le genou avant reste au-dessus du pied.'),
    ('equilibre-et-posture', 1, 'dead-bug', 6, 3, 8, 10, 3, 45, 'Répétitions par côté.'),
    ('equilibre-et-posture', 1, 'marche-talons', 7, 2, 20, 30, 3, 45, 'Les répétitions comptent des pas. Pointes de pieds levées, sans se pencher en arrière.'),
    ('equilibre-et-posture', 2, 'equilibre-unipodal', 1, 3, 30, 45, 3, 45, 'Secondes par jambe, yeux ouverts. Fermer les yeux n''apporte rien tant que la version simple n''est pas stable.'),
    ('equilibre-et-posture', 2, 'romanian-une-jambe', 2, 3, 8, 10, 2, 90, 'Répétitions par jambe. Charge légère : ici c''est l''équilibre qui limite.'),
    ('equilibre-et-posture', 2, 'rowing-elastique', 3, 3, 12, 15, 2, 60, null),
    ('equilibre-et-posture', 2, 'developpe-elastique', 4, 3, 12, 15, 2, 60, null),
    ('equilibre-et-posture', 2, 'step-up', 5, 3, 8, 10, 2, 90, 'Répétitions par jambe. Marche basse : commencez plus bas que vous ne le pensez, la hauteur se gagne ensuite.'),
    ('equilibre-et-posture', 2, 'hip-airplane', 6, 2, 6, 8, 3, 45, 'Répétitions par jambe. Se tenir à un appui.'),
    ('equilibre-et-posture', 2, 'gainage-lateral-genoux', 7, 3, 20, 30, 3, 45, 'Secondes de maintien, par côté.'),
    ('equilibre-et-posture', 2, 'marche-pointes', 8, 2, 20, 30, 3, 45, 'Les répétitions comptent des pas. Talons levés, en gardant le buste droit.')
       ) as v(program_slug, day_position, exercise_slug, position, target_sets,
              target_reps_min, target_reps_max, target_rir, rest_seconds, note)
  join public.programs p     on p.slug = v.program_slug and p.is_template = true
  join public.program_days d on d.program_id = p.id and d.position = v.day_position
  join public.exercises e    on e.slug = v.exercise_slug and e.is_custom = false;


do $$
declare
  attendu constant int := 1015;
  obtenu  int;
begin
  select count(*) into obtenu
    from public.program_exercises pe
    join public.program_days d on d.id = pe.program_day_id
    join public.programs p     on p.id = d.program_id and p.is_template = true
   where p.slug in ('levers-comptes','charge-ondulee','double-passage','chaine-posterieure-progressive','controle-avant-charge','hanche-laterale-progressive','mollet-cheville-tempo-lent','retour-progressif-post-partum','coiffe-et-omoplate','equilibre-et-appui','circuit-stations','blocs-de-repetitions','ondulation-trois-semaines','variantes-selon-morphologie','plafond-volontaire','reserve-de-repetitions','trois-etages','appui-et-transfert','releve-et-portage','poigne-et-charge-asymetrique','poids-de-corps-densite','enchainements-au-sol','nuque-et-ceinture-scapulaire','kettlebell-deux-mouvements','kettlebell-hardstyle','kettlebell-efforts-brefs','gainage-sans-poussee','controle-du-centre','amplitude-active','methode-naturelle','preparation-integree','renfort-zones-exposees','trois-mouvements-sous-maximal','porter-et-marcher','musculation-et-cardio','serie-unique','machines-guidees','micro-doses','court-a-la-maison','trois-mouvements-quotidiens','onze-minutes','gestes-utilitaires','jambes-et-equilibre','entretien-grossesse','post-partum-progressif','sans-materiel-par-niveaux','lourd-moyen-leger','quinze-minutes-quotidiennes','equilibre-et-posture');

  if obtenu <> attendu then
    raise exception
      'Le référentiel a posé % exercices au lieu de %. Un slug est introuvable au catalogue.',
      obtenu, attendu;
  end if;
end $$;

commit;
